export function getWorkspaceSessionContext(
  db: Database,
  workspaceRoot: string,
  userId: string,
): WorkspaceSessionContext | null {
  const normalizedUserId = typeof userId === "string" ? userId.trim() : "";
  if (!normalizedUserId) return null;
  const user = readBetterAuthUser(db, normalizedUserId);
  if (!user || !isAuthorizedIdentity(db, user)) return null;
  const access = getWorkspaceUserAccess(db, normalizedUserId);
  if (!access.active || !access.workspaceRole) return null;

  const memberships = db.query(
    `SELECT current.company_slug, current.company_role
       FROM rm_company_membership_events AS current
       JOIN (
         SELECT company_slug, MAX(id) AS latest_id
           FROM rm_company_membership_events
          WHERE user_id = ?
          GROUP BY company_slug
       ) AS latest ON latest.latest_id = current.id
      WHERE current.user_id = ? AND current.event_type = 'grant'`,
  ).all(normalizedUserId, normalizedUserId) as Array<{
    company_slug: string;
    company_role: CompanyRole;
  }>;
  const roleBySlug = new Map(memberships.map((membership) => [
    membership.company_slug,
    membership.company_role,
  ]));

  return {
    user: {
      id: user.id,
      email: user.email,
      emailVerified: user.emailVerified === 1,
      twoFactorEnabled: user.twoFactorEnabled === 1,
    },
    workspaceRole: access.workspaceRole,
    companies: listWorkspaceCompanies(workspaceRoot)
      .flatMap((company) => {
        const role = roleBySlug.get(company.slug);
        return role ? [{ slug: company.slug, name: company.name, role, archived: company.archived }] : [];
      }),
  };
}

export function listAvailableConsolidationProfiles(
  db: Database,
  workspaceRoot: string,
  visibleCompanySlugs: ReadonlySet<string>,
  asOfInput: string,
) {
  const asOf = parseGroupAsOf(asOfInput);
  const groups = readCurrentGroupManifest(db, workspaceRoot);
  if (!groups) return { scope: "consolidation-report-profiles" as const, asOf, profiles: [] };
  const profiles = [...current(readEvents(db)).values()].flatMap((event) => {
    if (event.event_type !== "approved") return [];
    const profile = decoded(event, groups.manifest);
    const group = groups.manifest.groups.find((candidate) => candidate.id === profile.groupId);
    if (!group || !active(profile, asOf)) return [];
    const activeMembers = group.memberships.filter((membership) => active(membership, asOf));
    if (activeMembers.some((membership) => !visibleCompanySlugs.has(membership.companySlug))) return [];
    return [{
      id: profile.id,
      groupId: profile.groupId,
      currency: profile.currency,
      validFrom: profile.validFrom,
      validToExclusive: profile.validToExclusive,
    }];
  }).sort((a, b) => compare(a.id, b.id));
  return { scope: "consolidation-report-profiles" as const, asOf, profiles };
}

