export async function handleCompanyUpdate(
  config: ServerConfig,
  slug: string,
  request: Request,
): Promise<Response> {
  assertWorkspaceWriteAllowed(request, config);
  if (!findWorkspaceCompany(config.workspaceRoot, slug)) {
