                a.name             AS name,
                a.type             AS type,
                a.normal_balance   AS normalBalance,
                a.default_vat_code AS defaultVatCode,
                EXISTS(
                  SELECT 1 FROM journal_lines jl WHERE jl.account_id = a.id
