    const savepoint=`batch_item_${index}`;
    db.exec(`SAVEPOINT ${savepoint}`);
    try { input.testOnly?.beforeItem?.(item.actionKey); db.query("INSERT INTO bookkeeping_batch_item_attempts(run_id,action_key,evidence_hash,outcome,created_at) VALUES(?,?,?,?,?)").run(input.runId,item.actionKey,item.evidenceHash,"started",new Date().toISOString()); const applied=applyPurchaseAction(db,plan,item,input.actor,principal); if(applied.outcome!=="applied") throw new Error(applied.error); if(![applied.journalEntryId,applied.vatPreflightId,applied.postingRuleApplicationId,applied.purchaseApplicationId].every(Number.isInteger)) throw new Error("purchase application did not produce immutable evidence ids"); db.query("INSERT INTO bookkeeping_batch_applied_links(run_id,action_key,document_id,journal_entry_id,bank_transaction_id,vat_preflight_id,posting_rule_application_id,purchase_application_id,evidence_hash,created_at) VALUES(?,?,?,?,?,?,?,?,?,?)").run(input.runId,item.actionKey,applied.documentId,applied.journalEntryId,applied.bankTransactionId,applied.vatPreflightId,applied.postingRuleApplicationId,applied.purchaseApplicationId,item.evidenceHash,new Date().toISOString()); db.query("INSERT INTO bookkeeping_batch_item_receipts(run_id,action_key,receipt_json,created_at) VALUES(?,?,?,?)").run(input.runId,item.actionKey,canonical(applied),new Date().toISOString()); input.testOnly?.afterItem?.(item.actionKey); db.query("INSERT INTO bookkeeping_batch_item_attempts(run_id,action_key,evidence_hash,outcome,created_at) VALUES(?,?,?,?,?)").run(input.runId,item.actionKey,item.evidenceHash,"applied",new Date().toISOString()); db.exec(`RELEASE ${savepoint}`); applyEvent("item_applied",applied,item.actionKey); results.push({actionKey:item.actionKey,outcome:"applied"}); }
