coreContracts.implementation:
export function computeInvoiceAmounts(
  lines: InvoiceLineInput[],
  vatRatePercent: number,
): ComputeInvoiceAmountsResult {
  const errors: string[] = [];
  if (!Array.isArray(lines) || lines.length === 0) {
    errors.push("at least one invoice line is required");
  }
  if (!Number.isFinite(vatRatePercent) || vatRatePercent < 0) {
    errors.push("vatRatePercent must be a number greater than or equal to 0");
  }

  const computed: ComputedInvoiceLine[] = [];
  (lines ?? []).forEach((line, index) => {
    const description = typeof line.description === "string" ? line.description.trim() : "";
    if (description.length === 0) {
      errors.push(`lines[${index}].description must not be blank`);
    }
    if (!Number.isFinite(line.quantity) || line.quantity <= 0) {
      errors.push(`lines[${index}].quantity must be a number greater than 0`);
    }
    if (!Number.isFinite(line.unitPriceExVat) || line.unitPriceExVat < 0) {
      errors.push(`lines[${index}].unitPriceExVat must be a number greater than or equal to 0`);
    }
    computed.push({
      description,
      quantity: line.quantity,
      unitPriceExVat: line.unitPriceExVat,
      lineTotalExVat: roundDkk(Number(line.quantity) * Number(line.unitPriceExVat)),
    });
  });

  if (errors.length > 0) return { ok: false, lines: computed, errors };

  const netAmount = roundDkk(computed.reduce((sum, line) => sum + line.lineTotalExVat, 0));
  const vatRate = roundRate6(vatRatePercent / 100);
  const vatAmount = roundDkk(netAmount * vatRate);
  const grossAmount = roundDkk(netAmount + vatAmount);

  return {
    ok: true,
    lines: computed,
    totals: { vatRate, netAmount, vatAmount, grossAmount },
    errors: [],
  };
}

export function resolveInvoiceMasterData(
  db: Database,
  payload: InvoicePayload,
  options: { customerId?: number | null },
): { ok: true; payload: InvoicePayload; notes?: string[] } | { ok: false; errors: string[] } {
  if (!options.customerId) return { ok: true, payload };
  const customer = getCustomerById(db, options.customerId);
  if (!customer || customer.archived) return { ok: false, errors: [`customer ${options.customerId} does not exist`] };

  // EJER-3: only an EXPLICIT kundefrist sets the due date here. A customer
  // stored with NULL has no own frist — the due date is left unset so
  // issueInvoice's enrichInvoiceFromCompany fills it from the company
  // profile's payment terms (the owner's own standard).
  const explicitDueDate = trimToNull(payload.dueDate);
  const customerTerms = customer.payment_terms_days;
  const dueDate =
    explicitDueDate ??
    (trimToNull(payload.issueDate) && customerTerms != null && customerTerms > 0
      ? addDays(payload.issueDate!, customerTerms)
      : undefined);

  // EJER-3: when the kundekort's explicit frist (not the company standard)
  // decides the due date AND deviates from the profile, say so out loud —
  // the owner must never discover a silently different betalingsfrist.
  const notes: string[] = [];
  if (!explicitDueDate && dueDate !== undefined && customerTerms != null) {
    const companyTerms = companyDefaultPaymentTermsDays(db);
    if (companyTerms != null && companyTerms !== customerTerms) {
      notes.push(
        `Betalingsfrist ${customerTerms} dage fra kundekortet — virksomhedens standard er ${companyTerms} dage.`,
      );
    }
  }

  return {
    ok: true,
    payload: {
      ...payload,
      buyer: {
        name: trimToNull(payload.buyer?.name) ?? customer.name,
        address: trimToNull(payload.buyer?.address) ?? customer.address ?? undefined,
        vatOrCvr: trimToNull(payload.buyer?.vatOrCvr) ?? customer.vat_or_cvr ?? undefined,
        eanNumber: normalizeEanNumber(payload.buyer?.eanNumber) ?? customer.ean_number ?? undefined,
        publicRecipient: payload.buyer?.publicRecipient ?? Boolean(normalizeEanNumber(payload.buyer?.eanNumber) ?? customer.ean_number),
      },
      currency: trimToNull(payload.currency) ?? customer.default_currency,
      dueDate,
    },
    ...(notes.length > 0 ? { notes } : {}),
  };
}

export function createRecurringInvoiceTemplate(
  db: Database,
  input: RecurringInvoiceTemplateInput,
): RecurringInvoiceTemplateResult {
  const appliedRules = [TEMPLATE_RULE_ID];
  const errors: string[] = [];

  const name = hasText(input.name) ? input.name.trim() : null;
  if (!name) errors.push("name is required");
  if (!(input.interval in INTERVAL_MONTHS)) {
    errors.push("interval must be one of weekly, monthly, quarterly, yearly");
  }
  const intervalCount = input.intervalCount ?? 1;
  if (!Number.isInteger(intervalCount) || intervalCount <= 0 || intervalCount > 120) {
    errors.push("intervalCount must be a positive integer no greater than 120");
  }
  const deliveryChannel = input.deliveryChannel ?? "manual";
  if (!DELIVERY_CHANNELS.has(deliveryChannel)) {
    errors.push("deliveryChannel must be one of manual, email, digisense");
  }
  if (!isValidIsoDate(input.firstIssueDate)) {
    errors.push("firstIssueDate must be a YYYY-MM-DD date");
  }
  const deliveryPeriodMode: DeliveryPeriodMode = input.deliveryPeriodMode ?? "issue_month";
  if (!DELIVERY_MODES.has(deliveryPeriodMode)) {
    errors.push("deliveryPeriodMode must be one of issue_month, interval_window, none");
  }
  const paymentTermsDays =
    input.paymentTermsDays === undefined
      ? 30
      : Number(input.paymentTermsDays);
  if (
    !Number.isInteger(paymentTermsDays) ||
    paymentTermsDays < 0 ||
    paymentTermsDays > 365
  ) {
    errors.push("paymentTermsDays must be an integer between 0 and 365 when present");
  }
  if (input.invoice === undefined || input.invoice === null || typeof input.invoice !== "object") {
    errors.push("invoice payload is required");
  }

  if (errors.length > 0) return { ok: false, appliedRules, errors };

  // The embedded payload must already be a valid invoice apart from the
  // date/number fields that generation supplies. Validate it with a sentinel
  // issueDate so a structurally broken template is rejected up front.
  const probe: InvoicePayload = {
    ...input.invoice,
    issueDate: input.invoice.issueDate ?? input.firstIssueDate,
    invoiceNumber: undefined,
    dueDate: undefined,
    deliveryDate: undefined,
    deliveryPeriodStart: undefined,
    deliveryPeriodEnd: undefined,
  };
  const validation = validateInvoice(probe);
  if (!validation.ok) {
    return { ok: false, appliedRules: [...new Set([...appliedRules, ...validation.appliedRules])], errors: validation.errors };
  }

  // Persist the payload stripped of derived date/number fields so generation
  // is the single source of truth for those.
  const storedPayload: InvoicePayload = {
    ...input.invoice,
    issueDate: undefined,
    invoiceNumber: undefined,
    dueDate: undefined,
    deliveryDate: undefined,
    deliveryPeriodStart: undefined,
    deliveryPeriodEnd: undefined,
  };

  const inserted = db.transaction(() => {
    const row = db.query(
      `INSERT INTO recurring_invoice_templates (
        name, interval, interval_count, delivery_channel, first_issue_date, next_issue_date, payment_terms_days,
        delivery_period_mode, payload_json, notes
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      RETURNING id`,
    ).get(
      name,
      input.interval,
      intervalCount,
      deliveryChannel,
      input.firstIssueDate,
      input.firstIssueDate,
      paymentTermsDays,
      deliveryPeriodMode,
      JSON.stringify(storedPayload),
      hasText(input.notes) ? input.notes!.trim() : null,
    ) as { id: number };

    insertAuditLog(db, {
      eventType: "recurring_invoice_template_create",
      entityType: "recurring_invoice_template",
      entityId: row.id,
      message: `Created recurring invoice template ${row.id} ${name} (${input.interval})`,
      createdBy: input.createdBy,
      createdByProgram: input.createdByProgram,
    });

    return row;
  }).immediate();

  return { ok: true, templateId: inserted.id, appliedRules, errors: [] };
}

