export function normalizeVatPeriodType(value?: string | null): VatPeriodType | null {
  if (typeof value !== "string") return null;
  const trimmed = value.trim();
  return VAT_PERIOD_TYPES.has(trimmed as VatPeriodType) ? (trimmed as VatPeriodType) : null;
}

export function setCompanyVatPeriodType(
  db: Database,
  type: VatPeriodType | null,
  actor: ResolveActorInput = {},
): { ok: boolean; changed: boolean; errors: string[] } {
  if (type !== null && !VAT_PERIOD_TYPES.has(type)) {
    return {
      ok: false,
      changed: false,
      errors: ["vatPeriodType must be one of month, quarter, half-year, or null"],
    };
  }
  ensureNullableVatPeriodColumn(db);
  const before = db
    .query("SELECT vat_period_type AS t FROM companies WHERE id = 1")
    .get() as { t: string | null } | null;
  if (!before) {
    return {
      ok: false,
      changed: false,
      errors: ["company has not been initialised — run 'rentemester init' first"],
    };
  }
  const changed = before.t !== type;
  // A cadence is currently stored as one company-wide value, not as an
  // effective-dated registration history. Once VAT periods or VAT-classified
  // postings exist, changing to another non-null cadence would reinterpret
  // old activity and can make immutable closed periods overlap the new
  // windows. Refuse until an explicit effective-dated migration exists.
  if (changed && type !== null) {
    const existingVatPeriods = db
      .query(
        `SELECT id, period_start, period_end
           FROM accounting_periods
          WHERE kind IN ('vat_period', 'vat_quarter')`,
      )
      .all() as Array<{ id: number; period_start: string; period_end: string }>;
    const vatAccounts = loadVatAccountSemantics(db).amountSideByAccountNo;
    const postedLines = db
      .query(
        `SELECT a.account_no, jl.vat_code
           FROM journal_lines jl
           JOIN accounts a ON a.id = jl.account_id
           JOIN journal_entries je ON je.id = jl.journal_entry_id
          WHERE je.status = 'posted'`,
      )
      .all() as Array<{ account_no: string; vat_code: string | null }>;
    const hasVatActivity = postedLines.some((line) => {
      const code = typeof line.vat_code === "string" ? line.vat_code.trim() : "";
      return vatAccounts.has(line.account_no) || VAT_LINE_CODES.has(code);
    });
    const incompatibleRecoveryPeriod =
      before.t === null
        ? existingVatPeriods.find((period) => {
            const window = vatPeriodWindowFor(period.period_start, type);
            return (
              window.start !== period.period_start ||
              window.end !== period.period_end
            );
          })
        : undefined;
    const cannotRecoverPreviousCadence =
      before.t === null
        ? incompatibleRecoveryPeriod !== undefined ||
          (existingVatPeriods.length === 0 && hasVatActivity)
        : existingVatPeriods.length > 0 || hasVatActivity;
    if (cannotRecoverPreviousCadence) {
      return {
        ok: false,
        changed: false,
        errors: [
          incompatibleRecoveryPeriod
            ? `momsregistreringen kan ikke genaktiveres med ${type}: eksisterende momsperiode #${incompatibleRecoveryPeriod.id} ${incompatibleRecoveryPeriod.period_start}..${incompatibleRecoveryPeriod.period_end} følger en anden kadence`
            : "momsperiodens kadence kan ikke ændres, efter der er bogført momsaktivitet eller oprettet momsperioder; ændringen kræver en effective-dated kadencemigration, så historiske angivelser ikke omfortolkes eller strandes",
        ],
      };
    }
  }
  // Going from registered → not-registered must not silently strand posted
  // VAT activity (output VAT on a sale, deductible input VAT on a bilag).
  // Refuse when the ledger carries any posted entry on a `vat`-type account
  // whose date is NOT inside an EFFECTIVELY closed/reported VAT period — i.e.
  // any open VAT obligation that would otherwise lose its filing path. The
  // owner must close + indberette before deregistering.
  //
  // Coverage is judged by `effectivePeriodState`, NOT the period row's stored
  // status: a period that was closed and then reopened (#247) keeps its row at
  // `closed` while being effectively `open` again, so a raw `ap.status` check
  // would let a reopen→deregister sequence strand posted VAT activity — the
  // exact failure this guard exists to prevent. This mirrors the lens
  // `closeAccountingPeriod` / `validateJournalTransactionDate` already use.
  if (type === null && before.t !== null) {
    const vatAccounts = loadVatAccountSemantics(db).amountSideByAccountNo;
    const vatEntryDates = (db
      .query(
        `SELECT DISTINCT je.transaction_date AS d, a.account_no AS account_no
           FROM journal_lines jl
           JOIN accounts a ON a.id = jl.account_id
           JOIN journal_entries je ON je.id = jl.journal_entry_id
          WHERE je.status = 'posted'`,
      )
      .all() as Array<{ d: string; account_no: string }>)
      .filter((row) => vatAccounts.has(row.account_no));
    if (vatEntryDates.length > 0) {
      const vatPeriods = db
        .query(
          `SELECT id, period_start, period_end, status
             FROM accounting_periods
            WHERE kind IN ('vat_period', 'vat_quarter')`,
        )
        .all() as Array<{
        id: number;
        period_start: string;
        period_end: string;
        status: AccountingPeriodStatus;
      }>;
      const settledPeriods = vatPeriods.filter((p) => {
        const state = effectivePeriodState(db, p.id, p.status);
        return state === "closed" || state === "reported";
      });
      const hasOpenVatActivity = vatEntryDates.some(
        (entry) =>
          !settledPeriods.some(
            (p) => entry.d >= p.period_start && entry.d <= p.period_end,
          ),
      );
      if (hasOpenVatActivity) {
        return {
          ok: false,
          changed: false,
          errors: [
            "selskabet har bogført momsaktivitet i en åben momsperiode — luk og indberet perioden før selskabet markeres som ikke-momsregistreret: kør 'period close' for at lukke momsperioden, derefter 'vat momsangivelse' for den indberetningsklare angivelse, og indberet via TastSelv",
          ],
        };
      }
    }
  }
  db.query("UPDATE companies SET vat_period_type = ? WHERE id = 1").run(type);
  if (changed) {
    // Itemize the registration-state transition in the append-only audit_log
    // so deregistering (registered → not-registered), re-registering, or a
    // cadence change is attributable and visible in the company history —
    // not a silent UPDATE. A deregistration in particular ends the company's
    // VAT obligation and must leave a trail.
    const label = (t: string | null) => (t === null ? "ikke momsregistreret" : t);
    const eventType =
      type === null
        ? "company_vat_deregistered"
        : before.t === null
          ? "company_vat_registered"
          : "company_vat_period_changed";
    insertAuditLog(db, {
      ...actor,
      eventType,
      entityType: "company",
      entityId: 1,
      message: `Momsregistrering ændret: ${label(before.t)} → ${label(type)}`,
    });
  }
  return { ok: true, changed, errors: [] };
}

export function setCompanyProfile(
  db: Database,
  options: SetCompanyProfileOptions,
): SetCompanyProfileResult {
  const errors: string[] = [];
  let cvr: string | null | undefined;
  if (options.cvr !== undefined) {
    try {
      cvr = normalizeCvr(options.cvr);
    } catch (error) {
      errors.push(error instanceof Error ? error.message : String(error));
    }
  }
  let paymentTermsDays: number | undefined;
  if (options.paymentTermsDays !== undefined && options.paymentTermsDays !== null) {
    const normalized = normalizePaymentTermsDays(options.paymentTermsDays);
    if (normalized === null) {
      errors.push("paymentTermsDays must be an integer between 0 and 365");
    } else {
      paymentTermsDays = normalized;
    }
  }
  if (errors.length > 0) return { ok: false, errors };

  const before = getCompanySettings(db);
  // A first `setCompanyProfile` before `init` ran would have no row; guard it.
  const exists = db.query("SELECT id FROM companies WHERE id = 1").get() as
    | { id: number }
    | null;
  if (!exists) {
    return {
      ok: false,
      errors: ["company has not been initialised — run 'rentemester init' first"],
    };
  }

  const result = db.transaction(() => {
    const name = options.name !== undefined ? options.name?.trim() || before.name : before.name;
    const nextCvr = options.cvr !== undefined ? cvr ?? null : before.cvr;
    const address =
      options.address !== undefined ? options.address?.trim() || null : before.address;
    const postalCode =
      options.postalCode !== undefined ? options.postalCode?.trim() || null : before.postalCode;
    const city = options.city !== undefined ? options.city?.trim() || null : before.city;
    const terms = paymentTermsDays ?? before.paymentTermsDays;

    db.query(
      `UPDATE companies SET
         name = ?, cvr = ?, address = ?, postal_code = ?, city = ?, payment_terms_days = ?
       WHERE id = 1`,
    ).run(name, nextCvr, address, postalCode, city, terms);

    if (hasPaymentInfo(options.payment)) {
      upsertPrimaryBankAccount(db, before.currency, options.payment);
    }

    insertAuditLog(db, {
      eventType: "company_profile_update",
      entityType: "company",
      entityId: 1,
      message: "Updated company profile (identity / payment details)",
    });
    return getCompanySettings(db);
  }).immediate();

  const updatedFields: string[] = [];
  const compare: Array<[string, unknown, unknown]> = [
    ["name", before.name, result.name],
    ["cvr", before.cvr, result.cvr],
    ["address", before.address, result.address],
    ["postalCode", before.postalCode, result.postalCode],
    ["city", before.city, result.city],
    ["paymentTermsDays", before.paymentTermsDays, result.paymentTermsDays],
  ];
  for (const [field, prev, next] of compare) {
    if (prev !== next) updatedFields.push(field);
  }
  if (hasPaymentInfo(options.payment)) updatedFields.push("payment");

  return { ok: true, settings: result, updatedFields, errors: [] };
}

export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

export function resolveCompanyPaymentDetails(
  db: Database,
  currency = "DKK",
): CompanyPaymentDetails | undefined {
  let rows: Array<{
    bank_name: string | null;
    registration_no: string | null;
    account_no: string | null;
    iban: string | null;
    currency: string | null;
  }> = [];
  try {
    rows = db
      .query(
        `SELECT bank_name, registration_no, account_no, iban, currency
           FROM bank_accounts
          WHERE active = 1
          ORDER BY id ASC`,
      )
      .all() as typeof rows;
  } catch {
    // The table may not exist in very old ledgers; payment block is optional.
    return undefined;
  }
  if (rows.length === 0) return undefined;
  const wanted = currency.trim().toUpperCase();
  const match =
    rows.find((row) => (row.currency ?? "").trim().toUpperCase() === wanted) ?? rows[0];
  const details: CompanyPaymentDetails = {
    bankName: match.bank_name?.trim() || null,
    registrationNo: match.registration_no?.trim() || null,
    accountNo: match.account_no?.trim() || null,
    iban: match.iban?.trim() || null,
  };
  if (!details.bankName && !details.registrationNo && !details.accountNo && !details.iban) {
    return undefined;
  }
  return details;
}

