      const created = addBankAccount(ctx.db, {
        name,
        ...(accSlug ? { slug: accSlug } : {}),
        ...(bankName ? { bankName } : {}),
        ...(registrationNo ? { registrationNo } : {}),
        ...(accountNo ? { accountNo } : {}),
        ...(iban ? { iban } : {}),
        ...(bic ? { bic } : {}),
        ...(accountOwner ? { accountOwner } : {}),
        ...(customerNo ? { customerNo } : {}),
        ...(currency ? { currency } : {}),
        ...(ledgerAccountNo ? { ledgerAccountNo } : {}),
      });
      // Marker actor på audit-log'en (write går gennem withCompanyMutation,
      // som sørger for at append-only audit-log fanger den).
      void ctx.actor;
      if (!created.ok) {
        return { ok: false, account: null, errors: created.errors };
      }
      return { ok: true, account: created.account, errors: [] as string[] };
    },
  );
  return okResponse({ bankAccount: result.account });
}

coreContracts.implementation:
export function addBankAccount(db: Database, input: AddBankAccountInput) {
  const errors: string[] = [];
  const name = input.name?.trim();
  if (!name) errors.push("name is required");
  const slug = (input.slug?.trim() ? slugify(input.slug) : slugify(name ?? "")) || "";
  if (!slug) errors.push("slug could not be derived; pass an explicit --slug");
  const currency = normalizeCurrency(input.currency);
  if (currency.length !== 3) errors.push("currency must be a 3-letter ISO currency code");
  if (errors.length > 0) return { ok: false as const, account: undefined, errors };

  if (db.query("SELECT id FROM bank_accounts WHERE slug = ?").get(slug)) {
    return { ok: false as const, account: undefined, errors: [`a bank account with slug '${slug}' already exists`] };
  }
  const ledgerAccountNo = input.ledgerAccountNo?.trim() || null;
  const ledgerError = validateBankLedgerAccount(db, ledgerAccountNo);
  if (ledgerError) return { ok: false as const, account: undefined, errors: [ledgerError] };

  const row = db.query(
    `INSERT INTO bank_accounts (slug, name, bank_name, registration_no, account_no, iban, bic, account_owner, customer_no, currency, ledger_account_no)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?) RETURNING *`,
  ).get(
    slug,
    name,
    input.bankName?.trim() || null,
    input.registrationNo?.trim() || null,
    input.accountNo?.trim() || null,
    input.iban?.trim() || null,
    input.bic?.trim() || null,
    input.accountOwner?.trim() || null,
    input.customerNo?.trim() || null,
    currency,
    ledgerAccountNo,
  );
  insertAuditLog(db, {
    eventType: "bank_account_add",
    entityType: "bank_account",
    entityId: String((row as any).id),
    message: `Added bank account '${slug}' (${name})`,
  });
  return { ok: true as const, account: mapBankAccountRow(row), errors: [] as string[] };
}

