coreContracts.implementation:
export function buildGdprSubjectExport(
  db: Database,
  key: GdprSubjectKey,
  actor: ResolveActorInput = {},
): GdprSubjectExport {
  const asOf = trim(key.asOf) ?? currentUtcIsoDate(db);
  const subject = resolveSubject(key);
  if (!subject.cvr && !subject.name) {
    return {
      ok: false,
      asOf,
      appliedRules: [EXPORT_RULE_ID],
      subject,
      records: [],
      errors: ["a GDPR subject must be identified by cvr or name"],
    };
  }
  if (!isValidIsoDate(asOf)) {
    return {
      ok: false,
      asOf,
      appliedRules: [EXPORT_RULE_ID],
      subject,
      records: [],
      errors: ["asOf must be a valid YYYY-MM-DD date"],
    };
  }
  const scopeResolution = resolveSubjectScope(db, subject);
  if (!scopeResolution.ok) {
    return {
      ok: false,
      asOf,
      appliedRules: [EXPORT_RULE_ID],
      subject,
      records: [],
      errors: [scopeResolution.error],
    };
  }

  const subjectRef = scopeResolution.scope.auditReference;
  const erasures = loadErasures(
    db,
    scopeResolution.scope.erasureSubjectKeys,
  );
  const sourceRows = collectSourceRows(db, scopeResolution.scope);
  strengthenErasureAliases(db, scopeResolution.scope, sourceRows, erasures);
  const records: GdprExportRecord[] = sourceRows.map((row) => {
    const redacted = erasures.get(`${row.source}:${row.sourceRowId}`) ?? new Set<string>();
    const underRetention = row.retainUntil !== null && row.retainUntil >= asOf;
    return {
      source: row.source,
      sourceRowId: row.sourceRowId,
      label: applyLabelRedaction(row.label, redacted),
      personalData: applyRedaction(row.personalData, redacted),
      retainUntil: row.retainUntil,
      underRetention,
      erased: redacted.size > 0,
      erasable:
        !underRetention &&
        redacted.size === 0 &&
        row.redactable,
    };
  });

  // #355 — audit-log hver indsigtssøgning så ejeren kan bevise overfor
  // Datatilsynet hvilke subject-data der er udleveret hvornår.
  insertAuditLog(db, {
    eventType: "gdpr_export",
    entityType: "gdpr_subject",
    entityId: subjectRef,
    message: `GDPR export ${subjectRef}: ${records.length} record(s) returned (as-of ${asOf})`,
    ...actor,
  });

  return {
    ok: true,
    asOf,
    appliedRules: [EXPORT_RULE_ID, RETENTION_RULE_ID],
    subject,
    records,
    errors: [],
  };
}

export function getCompanySettings(db: Database): CompanySettings {
  // #289: older ledgers (and the base schema.sql) may lack `vat_period_type`.
  // Read it only when present; absent → fall back to the quarterly default so
  // a pre-#289 company is unaffected.
  const vatColumn = hasVatPeriodColumn(db) ? "vat_period_type" : "NULL AS vat_period_type";
  const row = db.query(
    `SELECT id, name, country, currency, cvr, fiscal_year_start_month, fiscal_year_label_strategy,
            address, postal_code, city, company_form, industry_code, industry_text,
            cvr_status, audit_waived, cvr_synced_at, payment_terms_days, ${vatColumn}
       FROM companies
      ORDER BY id ASC
      LIMIT 1`
  ).get() as {
    id: number;
    name: string;
    country: string;
    currency: string;
    cvr: string | null;
    fiscal_year_start_month: number;
    fiscal_year_label_strategy: FiscalYearLabelStrategy;
    address: string | null;
    postal_code: string | null;
    city: string | null;
    company_form: string | null;
    industry_code: string | null;
    industry_text: string | null;
    cvr_status: string | null;
    audit_waived: number | null;
    cvr_synced_at: string | null;
    payment_terms_days: number | null;
    vat_period_type: string | null;
  } | null;

  if (!row) return DEFAULT_COMPANY_SETTINGS;
  return {
    id: row.id,
    name: row.name,
    country: row.country,
    currency: row.currency,
    cvr: normalizeCvr(row.cvr),
    fiscalYearStartMonth: normalizeFiscalYearStartMonth(row.fiscal_year_start_month) ?? 1,
    fiscalYearLabelStrategy: normalizeFiscalYearLabelStrategy(row.fiscal_year_label_strategy) ?? "end-year",
    address: row.address,
    postalCode: row.postal_code,
    city: row.city,
    companyForm: row.company_form,
    industryCode: row.industry_code,
    industryText: row.industry_text,
    cvrStatus: row.cvr_status,
    auditWaived: row.audit_waived === null ? null : row.audit_waived === 1,
    cvrSyncedAt: row.cvr_synced_at,
    paymentTermsDays:
      normalizePaymentTermsDays(row.payment_terms_days) ?? DEFAULT_PAYMENT_TERMS_DAYS,
    // `null` in the column = "not VAT-registered" — preserved verbatim. A
    // stored value that fails normalisation (corrupt cell) falls back to the
    // historical default so legacy ledgers stay readable.
    vatPeriodType:
      row.vat_period_type === null
        ? null
        : normalizeVatPeriodType(row.vat_period_type) ?? DEFAULT_VAT_PERIOD_TYPE,
  };
}

