coreContracts.implementation:
export function resolveDocumentMasterData(
  db: Database,
  metadata: DocumentMetadata,
  options: { vendorId?: number | null },
): { ok: true; metadata: DocumentMetadata } | { ok: false; errors: string[] } {
  if (!options.vendorId) return { ok: true, metadata };
  const vendor = getVendorById(db, options.vendorId);
  if (!vendor || vendor.archived) return { ok: false, errors: [`vendor ${options.vendorId} does not exist`] };
  return {
    ok: true,
    metadata: {
      ...metadata,
      sender: {
        name: trimToNull(metadata.sender?.name) ?? vendor.name,
        address: trimToNull(metadata.sender?.address) ?? vendor.address ?? undefined,
        vatOrCvr: trimToNull(metadata.sender?.vatOrCvr) ?? vendor.vat_or_cvr ?? undefined,
        countryCode: metadata.sender?.countryCode ?? vendor.country_code ?? undefined,
        identifierKind: metadata.sender?.identifierKind ?? vendor.identifier_kind ?? undefined,
      },
    },
  };
}

export async function ingestDocumentAsync(db: Database, companyRoot: string, filePath: string, metadata: DocumentMetadata, options: IngestDocumentOptions = {}): Promise<IngestDocumentResult> {
  const validation = validateDocumentMetadata(metadata);
  if (!validation.ok) return { ok: false, errors: validation.errors };
  let snapshot: DocumentSnapshot;
  let mimeType: string;
  try {
    snapshot = snapshotDocumentSource(filePath);
    mimeType = detectMimeType(snapshot.filename, snapshot.bytes);
  } catch (error) {
    return { ok: false, errors: [error instanceof Error ? error.message : String(error)] };
  }
  if (options.scannerPolicy === "required" && !options.scanner) {
    return { ok: false, errors: ["document scanner is required but unavailable"] };
  }
  let scanEvidence: { scannerId: string; scannerVersion?: string; evidenceRef?: string } | undefined;
  if (options.scanner) {
    const result = await scanSnapshot(options.scanner, snapshot, mimeType, scannerTimeoutMs(options.scannerTimeoutMs));
    if (!result.ok) {
      return { ok: false, errors: [result.reason === "rejected" ? "document scanner rejected the document" : "document scanner failed"] };
    }
    scanEvidence = result;
  }
  return ingestDocumentSnapshot(db, companyRoot, filePath, metadata, options, snapshot, mimeType, scanEvidence);
}

export function removePathWithRetry(path: string, options: RmOptions = { recursive: true, force: true }): void {
  retryTransientCleanup(() => rmSync(path, options));
}

