export function computeInvoiceAmounts(
  lines: InvoiceLineInput[],
  vatRatePercent: number,
): ComputeInvoiceAmountsResult {
  const errors: string[] = [];
  if (!Array.isArray(lines) || lines.length === 0) {
    errors.push("at least one invoice line is required");
  }
  if (!Number.isFinite(vatRatePercent) || vatRatePercent < 0) {
    errors.push("vatRatePercent must be a number greater than or equal to 0");
  }

  const computed: ComputedInvoiceLine[] = [];
  (lines ?? []).forEach((line, index) => {
    const description = typeof line.description === "string" ? line.description.trim() : "";
    if (description.length === 0) {
      errors.push(`lines[${index}].description must not be blank`);
    }
    if (!Number.isFinite(line.quantity) || line.quantity <= 0) {
      errors.push(`lines[${index}].quantity must be a number greater than 0`);
    }
    if (!Number.isFinite(line.unitPriceExVat) || line.unitPriceExVat < 0) {
      errors.push(`lines[${index}].unitPriceExVat must be a number greater than or equal to 0`);
    }
    computed.push({
      description,
      quantity: line.quantity,
      unitPriceExVat: line.unitPriceExVat,
      lineTotalExVat: roundDkk(Number(line.quantity) * Number(line.unitPriceExVat)),
    });
  });

  if (errors.length > 0) return { ok: false, lines: computed, errors };

  const netAmount = roundDkk(computed.reduce((sum, line) => sum + line.lineTotalExVat, 0));
  const vatRate = roundRate6(vatRatePercent / 100);
  const vatAmount = roundDkk(netAmount * vatRate);
  const grossAmount = roundDkk(netAmount + vatAmount);

  return {
    ok: true,
    lines: computed,
    totals: { vatRate, netAmount, vatAmount, grossAmount },
    errors: [],
  };
}

export function resolveInvoiceMasterData(
  db: Database,
  payload: InvoicePayload,
  options: { customerId?: number | null },
): { ok: true; payload: InvoicePayload; notes?: string[] } | { ok: false; errors: string[] } {
  if (!options.customerId) return { ok: true, payload };
  const customer = getCustomerById(db, options.customerId);
  if (!customer || customer.archived) return { ok: false, errors: [`customer ${options.customerId} does not exist`] };

  // EJER-3: only an EXPLICIT kundefrist sets the due date here. A customer
  // stored with NULL has no own frist — the due date is left unset so
  // issueInvoice's enrichInvoiceFromCompany fills it from the company
  // profile's payment terms (the owner's own standard).
  const explicitDueDate = trimToNull(payload.dueDate);
  const customerTerms = customer.payment_terms_days;
  const dueDate =
    explicitDueDate ??
    (trimToNull(payload.issueDate) && customerTerms != null && customerTerms > 0
      ? addDays(payload.issueDate!, customerTerms)
      : undefined);

  // EJER-3: when the kundekort's explicit frist (not the company standard)
  // decides the due date AND deviates from the profile, say so out loud —
  // the owner must never discover a silently different betalingsfrist.
  const notes: string[] = [];
  if (!explicitDueDate && dueDate !== undefined && customerTerms != null) {
    const companyTerms = companyDefaultPaymentTermsDays(db);
    if (companyTerms != null && companyTerms !== customerTerms) {
      notes.push(
        `Betalingsfrist ${customerTerms} dage fra kundekortet — virksomhedens standard er ${companyTerms} dage.`,
      );
    }
  }

  return {
    ok: true,
    payload: {
      ...payload,
      buyer: {
        name: trimToNull(payload.buyer?.name) ?? customer.name,
        address: trimToNull(payload.buyer?.address) ?? customer.address ?? undefined,
        vatOrCvr: trimToNull(payload.buyer?.vatOrCvr) ?? customer.vat_or_cvr ?? undefined,
        eanNumber: normalizeEanNumber(payload.buyer?.eanNumber) ?? customer.ean_number ?? undefined,
        publicRecipient: payload.buyer?.publicRecipient ?? Boolean(normalizeEanNumber(payload.buyer?.eanNumber) ?? customer.ean_number),
      },
      currency: trimToNull(payload.currency) ?? customer.default_currency,
      dueDate,
    },
    ...(notes.length > 0 ? { notes } : {}),
  };
}

export function previewIssuedInvoicePdf(
  db: Database,
  rawPayload: InvoicePayload,
): PreviewIssuedInvoicePdfResult {
  const PREVIEW_RULE_ID = "DK-INVOICE-PREVIEW-001";
  const payload = enrichInvoiceFromCompany(db, rawPayload);
  const validation = validateInvoice(payload);
  const appliedRules = [...new Set([...(validation.appliedRules ?? []), PREVIEW_RULE_ID])];
  if (!validation.ok) {
    return { ok: false, appliedRules, errors: validation.errors };
  }

  // Compute the preview fakturanummer placeholder. The scope is the current
  // fiscal-year label, exactly as `issueInvoice` would use, so the preview's
  // header reads `<scope>-UDKAST` — clearly NOT a finalised number. Falls back
  // to a plain "UDKAST" if the fiscal-year scope cannot be resolved (older
  // ledgers / missing companies row).
  let previewNumber = payload.invoiceNumber?.trim() || "UDKAST";
  if (!payload.invoiceNumber?.trim()) {
    try {
      if (payload.issueDate) {
        const scope = fiscalYearLabelFromDate(db, payload.issueDate);
        previewNumber = `${scope}-UDKAST`;
      }
    } catch {
      // keep "UDKAST" fallback
    }
  }

  const invoiceCurrency = (payload.currency ?? "DKK").trim().toUpperCase();
  let paymentDetails: ReturnType<typeof resolveCompanyPaymentDetails> | undefined;
  try {
    paymentDetails = resolveCompanyPaymentDetails(db, invoiceCurrency);
  } catch {
    paymentDetails = undefined;
  }

  const pdfBytes = buildIssuedInvoicePdf({
    ...payload,
    invoiceNumber: previewNumber,
    status: "preview",
    ...(paymentDetails ? { payment: paymentDetails } : {}),
  });

  return {
    ok: true,
    pdfBytes,
    invoiceNumber: previewNumber,
    appliedRules,
    errors: [],
  };
}

