      if (amount > claimOpenBalance) {
        throw new TransactionRejectionError({ appliedRules: [isCombined ? COMBINED_RULE_ID : RULE_ID], errors: [`settlement amount ${amount} exceeds invoice claim open balance ${claimOpenBalance}`] });
