            appliedRules: [COMBINED_RULE_ID],
            errors: [`invoice ${invoice.invoice_no} domain claim balance ${domainClaimOnly} DKK does not match ledger-backed claim receivables ${claimBalances.totalDkk} DKK`],
          });
