            {
              kind: "claim",
              invoiceDocumentId: input.invoiceDocumentId,
              bankTransactionId: bank.id,
              journalEntryId,
              effectiveDate: paymentDate,
              amount: claimAmount,
              currency: invoiceCurrency,
            },
          ],
        });
