      const smtp = loadConfiguredSmtp(ctx.companyRoot);
      const smtpErrors = validateSmtpConfig(smtp);
      if (smtpErrors.length > 0) {
        throw ApiError.badRequest(smtpErrors[0] ?? "SMTP er ikke konfigureret korrekt");
      }
      if (!looksLikeEmail(to)) {
        throw ApiError.badRequest(
          "modtagerens e-mailadresse er ugyldig — rykkeren kan ikke sendes",
        );
      }
      const transport = createSmtpTransport(smtp);

      // Reminder date is "today" — the calendar date in Danish time (KODE-11),
      // not the UTC date — the core enforces the "10 days since previous
      // reminder" rule and refuses anything that would breach the statutory
      // series.
      const reminderDate = todayIsoDate();

      // (1) Register the reminder + fee. The core enforces:
      //     - the invoice must exist and be an issued_invoice,
      //     - currency must be DKK,
      //     - the invoice must be overdue with a positive open balance,
      //     - fee <= 100 kr,
      //     - <= 3 reminders per invoice,
      //     - >= 10 days since the previous reminder.
      const registered = registerInvoiceReminder(ctx.db, {
        invoiceDocumentId,
        reminderDate,
        feeAmount,
      });
      if (!registered.ok) {
        throw ApiError.badRequest(
          registered.errors[0] ?? "rykkeren kunne ikke registreres",
        );
      }

      // (2) Optionally journal the fee — the standard owner intent. The
      //     core uses the same receivable/income accounts as the CLI's
      //     `invoice post-reminder` command, so the journal entry is
      //     byte-identical no matter which surface the owner uses.
      let journalEntryNo: string | null = null;
      let feeBooked = false;
      if (bookFee) {
        const posted = postInvoiceReminderToLedger(ctx.db, {
          invoiceDocumentId,
          reminderId: registered.reminderId,
        });
        if (!posted.ok) {
          throw ApiError.badRequest(
            posted.errors?.[0] ?? "rykkergebyret kunne ikke bogføres",
          );
        }
        journalEntryNo = posted.entryNo ?? null;
        feeBooked = true;
      }

      // (3) Send the reminder e-mail. SAME core function as "Send på mail"
      //     (#429), with `kind: 'reminder'` so the subject + body match
      //     what `invoice send --kind reminder` produces from the CLI. The
      //     SMTP config + transport were already loaded in step (0).
      const sent = sendInvoiceEmail(ctx.db, ctx.companyRoot, {
        invoiceDocumentId,
        kind: "reminder",
        to,
        smtp,
        transport,
      });
      if (!sent.ok) {
        throw ApiError.badRequest(
          sent.errors?.[0] ?? "rykkermailen kunne ikke sendes",
        );
      }

      return {
        ok: true as const,
        invoiceNumber: registered.invoiceNumber ?? sent.invoiceNumber ?? null,
        recipient: sent.recipient ?? to,
        reminderSequence: registered.reminderSequence ?? null,
        feeAmount: registered.feeAmount ?? null,
        feeBooked,
        journalEntryNo,
        messageId: sent.messageId ?? null,
        duplicate: Boolean(sent.duplicate),
      };
    },
    { requireConfirm: true },
  );

  return okResponse({
    reminder: {
      invoiceNumber: result.invoiceNumber ?? null,
      recipient: result.recipient ?? null,
      reminderSequence: result.reminderSequence ?? null,
      feeAmount: result.feeAmount ?? null,
      feeBooked: Boolean(result.feeBooked),
      journalEntryNo: result.journalEntryNo ?? null,
      messageId: result.messageId ?? null,
      duplicate: Boolean(result.duplicate),
    },
  });
}

coreContracts.implementation:
export function validateSmtpConfig(smtp: SmtpConfig | undefined): string[] {
  const errors: string[] = [];
  if (!smtp) {
    errors.push("SMTP config is required (host, port, fromAddress)");
    return errors;
  }
  if (!hasText(smtp.host)) errors.push("SMTP config requires a non-empty host");
  if (!Number.isInteger(smtp.port) || smtp.port <= 0) {
    errors.push("SMTP config requires a positive integer port");
  }
  if (!hasText(smtp.fromAddress)) {
    errors.push("SMTP config requires a non-empty fromAddress");
  } else if (!looksLikeEmail(smtp.fromAddress)) {
    errors.push("SMTP config fromAddress must be a valid email address");
  }
  return errors;
}

export function looksLikeEmail(value: string): boolean {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim());
}

export function createSmtpTransport(config: SmtpConfig): EmailTransport {
  return {
    send(message: EmailMessage): EmailTransportResult {
      if (config.dryRun) {
        return { ok: true, messageId: message.messageId };
      }
      // A real network send is intentionally out of scope for this slice —
      // the injected transport is the supported production seam. Callers that
      // need live delivery wire their own transport against `EmailTransport`.
      return {
        ok: false,
        error:
          "the built-in SMTP transport runs in dryRun only; inject a live EmailTransport for real delivery",
      };
    },
  };
}

export function todayIsoDate(): string {
  const override = process.env.RENTEMESTER_TODAY;
  if (isValidIsoDate(override)) return override.trim();
  return isoDateInTimeZone(new Date());
}

export function registerInvoiceReminder(db: Database, input: RegisterInvoiceReminderInput): RegisterInvoiceReminderResult {
  const errors: string[] = [];
  if (!Number.isInteger(input.invoiceDocumentId) || input.invoiceDocumentId <= 0) errors.push("invoiceDocumentId must be a positive integer");
  if (!looksLikeIsoDate(input.reminderDate)) errors.push("reminderDate must be YYYY-MM-DD");
  if (input.feeAmount !== undefined && (!Number.isFinite(input.feeAmount) || input.feeAmount <= 0)) errors.push("feeAmount must be a positive number when present");
  if (errors.length > 0) return { ok: false, appliedRules: [RULE_ID], errors };

  const invoice = db.query(`SELECT id, invoice_no, currency, document_type FROM documents WHERE id = ?`).get(input.invoiceDocumentId) as { id: number; invoice_no: string; currency: string | null; document_type: string } | null;
  if (!invoice) return { ok: false, appliedRules: [RULE_ID], errors: [`invoice document ${input.invoiceDocumentId} does not exist`] };
  if (invoice.document_type !== "issued_invoice") return { ok: false, appliedRules: [RULE_ID], errors: [`document ${input.invoiceDocumentId} is not an issued invoice`] };
  if ((invoice.currency ?? "DKK") !== "DKK") return { ok: false, appliedRules: [RULE_ID], errors: ["only DKK issued invoices are supported in the current reminder flow"] };

  const feeAmount = roundDkk(input.feeAmount ?? MAX_REMINDER_FEE_DKK);
  if (feeAmount > MAX_REMINDER_FEE_DKK) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`reminder fee ${feeAmount} exceeds statutory maximum ${MAX_REMINDER_FEE_DKK}`] };
  }

  const status = getInvoiceStatus(db, input.invoiceDocumentId, input.reminderDate);
  if (!status.ok) return { ok: false, appliedRules: [RULE_ID], errors: status.errors };
  if (!status.isOverdue || !(Number(status.openBalance ?? 0) > 0)) {
    return { ok: false, appliedRules: [RULE_ID], errors: ["invoice must be overdue with positive open balance on reminderDate"] };
  }

  const reminders = db.query(
    `SELECT id, reminder_date, fee_amount
     FROM invoice_reminders
     WHERE invoice_document_id = ?
     ORDER BY reminder_date ASC, id ASC`
  ).all(input.invoiceDocumentId) as Array<{ id: number; reminder_date: string; fee_amount: number }>;

  if (reminders.length >= MAX_REMINDERS_PER_CLAIM) {
    return { ok: false, appliedRules: [RULE_ID], errors: [`cannot register more than ${MAX_REMINDERS_PER_CLAIM} reminder fees for the same invoice claim`] };
  }

  const latestReminder = reminders.at(-1);
  if (latestReminder) {
    const daysSinceLatest = diffDays(latestReminder.reminder_date, input.reminderDate);
    if (daysSinceLatest < MIN_DAYS_BETWEEN_REMINDERS) {
      return { ok: false, appliedRules: [RULE_ID], errors: [`reminderDate must be at least ${MIN_DAYS_BETWEEN_REMINDERS} days after the previous reminder on ${latestReminder.reminder_date}`] };
    }
  }

  const inserted = db.query(
    `INSERT INTO invoice_reminders (invoice_document_id, reminder_date, fee_amount, currency, note)
     VALUES (?, ?, ?, 'DKK', ?)
     RETURNING id`
  ).get(input.invoiceDocumentId, input.reminderDate, feeAmount, input.note ?? null) as { id: number };

  insertAuditLog(db, {
    eventType: "invoice_reminder_register",
    entityType: "invoice_reminder",
    entityId: inserted.id,
    message: `Registered reminder fee ${feeAmount} on invoice ${invoice.invoice_no}`,
    createdBy: input.createdBy,
    createdByProgram: input.createdByProgram,
  });

  const totalReminderFees = roundDkk(reminders.reduce((sum, reminder) => sum + Number(reminder.fee_amount), 0) + feeAmount);
  return {
    ok: true,
    reminderId: inserted.id,
    reminderSequence: reminders.length + 1,
    invoiceDocumentId: input.invoiceDocumentId,
    invoiceNumber: invoice.invoice_no,
    reminderDate: input.reminderDate,
    feeAmount,
    totalReminderFees,
    appliedRules: [RULE_ID],
    errors: [],
  };
}

export function postInvoiceReminderToLedger(db: Database, input: PostInvoiceReminderToLedgerInput): PostInvoiceReminderToLedgerResult {
  if (!Number.isInteger(input.invoiceDocumentId) || input.invoiceDocumentId <= 0) {
    return { ok: false, appliedRules: [BOOKKEEPING_RULE_ID], errors: ["invoiceDocumentId must be a positive integer"] };
  }
  if (input.transactionDate !== undefined && !looksLikeIsoDate(input.transactionDate)) {
    return { ok: false, appliedRules: [BOOKKEEPING_RULE_ID], errors: ["transactionDate must be YYYY-MM-DD when present"] };
  }

  const reminder = db.query(
    `SELECT r.id, r.invoice_document_id, r.reminder_date, r.fee_amount, d.invoice_no
     FROM invoice_reminders r
     JOIN documents d ON d.id = r.invoice_document_id
     WHERE r.invoice_document_id = ?
       AND (? IS NULL OR r.id = ?)
     ORDER BY r.reminder_date ASC, r.id ASC
     LIMIT 1`
  ).get(input.invoiceDocumentId, input.reminderId ?? null, input.reminderId ?? null) as {
    id: number;
    invoice_document_id: number;
    reminder_date: string;
    fee_amount: number;
    invoice_no: string;
  } | null;

  if (!reminder) {
    return { ok: false, appliedRules: [BOOKKEEPING_RULE_ID], errors: [input.reminderId ? `reminder ${input.reminderId} does not exist for invoice ${input.invoiceDocumentId}` : `invoice ${input.invoiceDocumentId} has no registered reminder fee`] };
  }

  const existing = db.query(
    `SELECT p.id, p.journal_entry_id, j.entry_no
     FROM invoice_reminder_postings p
     JOIN journal_entries j ON j.id = p.journal_entry_id
     WHERE p.reminder_id = ?`
  ).get(reminder.id) as { id: number; journal_entry_id: number; entry_no: string } | null;

  if (existing) {
    return {
      ok: false,
      reminderId: reminder.id,
      invoiceDocumentId: reminder.invoice_document_id,
      invoiceNumber: reminder.invoice_no,
      reminderDate: reminder.reminder_date,
      feeAmount: roundDkk(Number(reminder.fee_amount)),
      appliedRules: [BOOKKEEPING_RULE_ID],
      errors: [`reminder ${reminder.id} is already posted in journal entry ${existing.entry_no}`],
    };
  }

  const amount = roundDkk(Number(reminder.fee_amount));
  const receivable = input.receivableAccountNo
    ? (accountRoleCompatibility(db, "debtors", input.receivableAccountNo).ok
      ? { ok: true as const, accountNo: input.receivableAccountNo }
      : { ok: false as const, error: `account ${input.receivableAccountNo} is not compatible with role 'debtors'` })
    : resolveAccountRole(db, "debtors");
  if (!receivable.ok) {
    return { ok: false, reminderId: reminder.id, invoiceDocumentId: reminder.invoice_document_id, invoiceNumber: reminder.invoice_no, reminderDate: reminder.reminder_date, feeAmount: amount, appliedRules: [BOOKKEEPING_RULE_ID], errors: [receivable.error] };
  }
  const income = resolveClaimIncomeAccount(db, input.reminderIncomeAccountNo ?? "1010");
  if (!income.ok) {
    return { ok: false, reminderId: reminder.id, invoiceDocumentId: reminder.invoice_document_id, invoiceNumber: reminder.invoice_no, reminderDate: reminder.reminder_date, feeAmount: amount, appliedRules: [BOOKKEEPING_RULE_ID], errors: [income.error] };
  }
  const transactionDate = input.transactionDate ?? reminder.reminder_date;
  if (transactionDate < reminder.reminder_date) {
    return { ok: false, reminderId: reminder.id, invoiceDocumentId: reminder.invoice_document_id, invoiceNumber: reminder.invoice_no, reminderDate: reminder.reminder_date, feeAmount: amount, appliedRules: [BOOKKEEPING_RULE_ID], errors: [`reminder posting date ${transactionDate} cannot predate reminder date ${reminder.reminder_date}`] };
  }
  try {
    return db.transaction(() => {
      const journal = postJournalEntry(db, {
        transactionDate,
        text: `Reminder fee ${reminder.invoice_no}`,
        documentId: reminder.invoice_document_id,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
        lines: [
          { accountNo: receivable.accountNo, debitAmount: amount, text: `Reminder receivable ${reminder.invoice_no}` },
          { accountNo: income.accountNo, creditAmount: amount, text: `Reminder income ${reminder.invoice_no}` },
        ],
      });
      if (!journal.ok) {
        return { ...journal, reminderId: reminder.id, invoiceDocumentId: reminder.invoice_document_id, invoiceNumber: reminder.invoice_no, reminderDate: reminder.reminder_date, feeAmount: amount, appliedRules: [...new Set([...(journal.appliedRules ?? []), BOOKKEEPING_RULE_ID])] };
      }

      runSql(db,
        `INSERT INTO invoice_reminder_postings (reminder_id, journal_entry_id) VALUES (?, ?)`,
        reminder.id,
        journal.entryId ?? null,
      );

      insertAuditLog(db, {
        eventType: "invoice_reminder_post",
        entityType: "invoice_reminder",
        entityId: reminder.id,
        message: `Posted reminder fee ${amount} for invoice ${reminder.invoice_no} in journal entry ${journal.entryNo}`,
        createdBy: input.createdBy,
        createdByProgram: input.createdByProgram,
      });

      const statusAfter = getInvoiceStatus(db, reminder.invoice_document_id, transactionDate);
      return {
        ...journal,
        reminderId: reminder.id,
        invoiceDocumentId: reminder.invoice_document_id,
        invoiceNumber: reminder.invoice_no,
        reminderDate: reminder.reminder_date,
        feeAmount: amount,
        claimOpenBalance: statusAfter.ok ? statusAfter.claimOpenBalance : undefined,
        appliedRules: [...new Set([...(journal.appliedRules ?? []), BOOKKEEPING_RULE_ID])],
      };
    })();
  } catch (error) {
    return {
      ok: false,
      reminderId: reminder.id,
      invoiceDocumentId: reminder.invoice_document_id,
      invoiceNumber: reminder.invoice_no,
      reminderDate: reminder.reminder_date,
      feeAmount: amount,
      appliedRules: [BOOKKEEPING_RULE_ID],
      errors: [String(error)],
    };
  }
}

export function sendInvoiceEmail(
  db: Database,
  _companyRoot: string,
  input: SendInvoiceEmailInput,
): SendInvoiceEmailResult {
  if (input.kind !== "invoice" && input.kind !== "reminder") {
    return { ok: false, appliedRules: [RULE_ID], errors: ["kind must be 'invoice' or 'reminder'"] };
  }
  if (!Number.isInteger(input.invoiceDocumentId) || input.invoiceDocumentId <= 0) {
    return { ok: false, appliedRules: [RULE_ID], errors: ["invoiceDocumentId must be a positive integer"] };
  }

  const configErrors = validateSmtpConfig(input.smtp);
  if (configErrors.length > 0) {
    return { ok: false, appliedRules: [RULE_ID], errors: configErrors };
  }

  const invoice = db
    .query(
      `SELECT id, invoice_no, payload_json, status, recipient_name
       FROM documents WHERE id = ? AND document_type = 'issued_invoice'`,
    )
    .get(input.invoiceDocumentId) as IssuedInvoiceRow | null;
  if (!invoice) {
    return {
      ok: false,
      appliedRules: [RULE_ID],
      errors: [`invoice document ${input.invoiceDocumentId} does not exist or is not an issued invoice`],
    };
  }
  if (!hasText(invoice.payload_json)) {
    return {
      ok: false,
      appliedRules: [RULE_ID],
      errors: [`invoice ${invoice.invoice_no ?? input.invoiceDocumentId} is missing payload_json`],
    };
  }

  const payload = JSON.parse(invoice.payload_json) as InvoicePayload & {
    invoiceNumber?: string;
    status?: string;
  };
  const invoiceNumber = hasText(invoice.invoice_no)
    ? invoice.invoice_no.trim()
    : hasText(payload.invoiceNumber)
      ? payload.invoiceNumber.trim()
      : null;
  if (!invoiceNumber) {
    return { ok: false, appliedRules: [RULE_ID], errors: ["issued invoice is missing invoice number"] };
  }

  const recipient = resolveRecipientEmail(
    db,
    input.to,
    invoice.recipient_name ?? payload.buyer?.name ?? null,
  );
  if (!recipient) {
    return {
      ok: false,
      appliedRules: [RULE_ID],
      errors: [
        `no recipient email for invoice ${invoiceNumber}: pass an explicit recipient or set the customer email`,
      ],
    };
  }
  if (!looksLikeEmail(recipient)) {
    return {
      ok: false,
      appliedRules: [RULE_ID],
      errors: [`recipient email '${recipient}' is not a valid email address`],
    };
  }

  const pdfBytes = buildIssuedInvoicePdf({
    ...payload,
    invoiceNumber,
    status: payload.status ?? invoice.status ?? "issued",
  });
  const message = buildInvoiceEmailMessage({
    smtp: input.smtp,
    to: recipient,
    kind: input.kind,
    invoiceNumber,
    pdfBytes,
    pdfFilename: `${invoiceNumber}.pdf`,
  });

  // Idempotent fast-path: an identical send already exists in the log.
  const existing = db
    .query(
      `SELECT id, recipient, subject FROM email_send_log WHERE message_id = ? LIMIT 1`,
    )
    .get(message.messageId) as { id: number; recipient: string; subject: string } | null;
  if (existing) {
    return {
      ok: true,
      invoiceNumber,
      kind: input.kind,
      recipient: existing.recipient,
      subject: existing.subject,
      messageId: message.messageId,
      duplicate: true,
      appliedRules: [RULE_ID],
      errors: [],
    };
  }

  const transportResult = input.transport.send(message);
  if (!transportResult.ok) {
    return {
      ok: false,
      invoiceNumber,
      kind: input.kind,
      recipient,
      subject: message.subject,
      messageId: message.messageId,
      duplicate: false,
      appliedRules: [RULE_ID],
      errors: [`SMTP transport failed: ${transportResult.error ?? "unknown error"}`],
    };
  }

  const bodySha256 = createHash("sha256").update(message.rawMessage).digest("hex");
  runSql(db,
    `INSERT INTO email_send_log
       (invoice_document_id, invoice_no, kind, recipient, sender, subject,
        message_id, body_sha256, smtp_host)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    input.invoiceDocumentId,
    invoiceNumber,
    input.kind,
    recipient,
    input.smtp.fromAddress.trim(),
    message.subject,
    message.messageId,
    bodySha256,
    input.smtp.host.trim(),
  );

  insertAuditLog(db, {
    eventType: "invoice_email_send",
    entityType: "document",
    entityId: input.invoiceDocumentId,
    message:
      `Sent ${input.kind} email for invoice ${invoiceNumber} to ${recipient} ` +
      `via ${input.smtp.host.trim()} (message-id ${message.messageId})`,
  });

  return {
    ok: true,
    invoiceNumber,
    kind: input.kind,
    recipient,
    subject: message.subject,
    messageId: message.messageId,
    duplicate: false,
    appliedRules: [RULE_ID],
    errors: [],
  };
}

