        </section>
      )}

      {cf.archived ? (
        <ArchivedNotice year={cf.selectedYear} />
      ) : !cf.hasTransactions ? (
        <div className="card archived-notice">
          <h3>Ingen pengestrøm</h3>
          <p className="muted">
