              </p>
            </div>
            <div className="card status-card">
              <h3>Indbetalinger</h3>
              <div className="status-figure status-in">
                {formatKroner(cf.totalIn, currency)}
              </div>
              <p className="muted status-note">Penge ind i året</p>
            </div>
            <div className="card status-card">
              <h3>Udbetalinger</h3>
              <div className="status-figure status-out">
