import { ButtonLink, Button, Input, PageHeader } from "../components/ui";
// Moms — the per-company VAT return (cockpit-redesign iteration 3).
//
// Renders `/api/companies/:slug/vat?year=` for the registered VAT cadence —
// output VAT (salgsmoms), input VAT (købsmoms), the resulting payable amount,
// AND the full SKAT TastSelv momsangivelse rubrics (rubrik A/B/C, foreign
// goods/services VAT) so the owner can file straight from the cockpit instead
// of dropping to the terminal (#257). All money fields are kroner —
// `formatKroner` is used throughout.

import { useState } from "react";
import { Link, useParams } from "react-router-dom";
import { api } from "../lib/api";
import { formatDateDa, formatKroner, tastSelvNumber, todayIso } from "../lib/format";
import { useAsync } from "../lib/useAsync";
import type { CompanyVat, CompanyVatRegistered, VatRubrikker } from "../lib/types";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { CompanyNav, useCompanyYear } from "../components/CompanyNav";
import { ConfirmDialog } from "../components/ConfirmDialog";
import { useOptionalAuth } from "../lib/auth-context";
import { OssReportPanel } from "./OssReportPanel";
import { VatTaskPanel } from "./VatTaskPanel";

export function VatView() {
  const { slug = "" } = useParams();
  const native = useOptionalAuth()?.backend === "rust";
  const { year, setYear } = useCompanyYear();
  const state = useAsync<CompanyVat>((signal) => api.vat(slug, year, { signal }), [slug, year]);
  // True while the close-period ConfirmDialog is open (#287).
  const [closing, setClosing] = useState(false);
  // True while the reopen-period ConfirmDialog is open (#301).
  const [reopening, setReopening] = useState(false);
  // #301: the second, explicit confirmation a future-end period close needs.
  const [futureEndAcknowledged, setFutureEndAcknowledged] = useState(false);
  // Set after a successful period close / reopen — surfaced as a success banner.
  const [closedNotice, setClosedNotice] = useState<string | null>(null);

  if (state.loading && !state.data) return <Loading label="Henter moms…" />;
  if (state.error && !state.data)
    return <ErrorState message={state.error} onRetry={state.reload} />;

  const v = state.data!;
  const currency = v.company.currency || "DKK";

  // A non-VAT-registered company has nothing to show on the moms-tab —
  // surface an explanation card instead of an empty rubrikker table. Render
  // early so none of the period-related controls below execute against the
  // missing period fields, and TypeScript narrows v to CompanyVatRegistered
  // below.
  if (!v.vatRegistered) {
    return (
      <section className="statement">
      {state.error && <div className="banner warning" role="alert">Status kunne ikke opdateres. De tidligere hentede oplysninger vises fortsat.</div>}
        <PageHeader title="Moms">
          <div>

            <p className="muted">
              {v.company.cvr ? `CVR ${v.company.cvr} · ` : ""}
              {v.company.country} · {currency} · Moms
            </p>
          </div>
        </PageHeader>
        <CompanyNav
          slug={slug}
          years={v.fiscalYears}
          selectedYear={v.selectedYear}
          onYearChange={setYear}
        />
        {native && <VatTaskPanel slug={slug} vat={v} verified={!state.loading && !state.error} onRefresh={state.reload} />}
        <Banner kind="warning">
          Denne virksomhed er ikke momsregistreret. Der er derfor ingen momsperiode,
          ingen momsangivelse og ingen SKAT-frist. Tilkøb af bilag med moms bogføres
          som ikke fradragsberettigede, så momsen indgår i udgiften. Skal selskabet alligevel momsregistreres, så sæt en
          momsperiode under <Link to={`/companies/${slug}/manage`}>Indstillinger</Link>.
        </Banner>
      </section>
    );
  }

  // TypeScript narrows v to CompanyVatRegistered after the !v.vatRegistered
  // early return above — every period/deadline/rubrikker field is non-null
  // from here on. No `!` or `?? ""` shims needed.
  const payablePositive = v.payable >= 0;
  // #301: a period whose end date is still in the future has not ended yet —
  // closing it now is almost always a mistake, so the confirm dialog warns.
  const periodEndsInFuture = v.periodEnd > todayIso();
  // #301: a closed (not reported) period can be reopened from the cockpit.
  const canReopen = v.periodActionsAvailable !== false && !v.archived && v.periodStatus === "closed";
  // #303: a momsangivelse is only filing-ready for a closed/reported period.
  const provisional = !v.archived && !v.momsangivelseReady;

  return (
    <section className="statement">
      {state.error && <div className="banner warning" role="alert">Status kunne ikke opdateres. De tidligere hentede oplysninger vises fortsat.</div>}
      <PageHeader title="Moms" actions={<><div className="row-actions">
          {/* #287: closing the VAT period is the prerequisite for a
              momsangivelse — hidden for an archived (read-only) year. Once the
              period is closed the action becomes a reopen instead (#301). */}
          {v.periodActionsAvailable !== false && !v.archived &&
            v.periodStatus === "open" &&
            v.vatReportErrors.length === 0 && (
            <Button requiredPermission="company.review"
              type="button"
              className="btn"
              onClick={() => {
                setFutureEndAcknowledged(false);
                setClosing(true);
              }}
            >
              Luk momsperiode
            </Button>
          )}
          {canReopen && (
            <Button requiredPermission="company.review" variant="secondary"
              type="button"
              className="btn secondary"
              onClick={() => setReopening(true)}
            >
              Genåbn momsperiode
            </Button>
          )}
          {/* #464 — moms-rapport som printbar PDF inkl. SKAT-rubrikker + frist. */}
          <a
            className="btn secondary"
            href={api.vatPdfUrl(slug, v.selectedYear)}
            download
          >
            Hent PDF
          </a>
          <ButtonLink className="btn secondary" to={`/companies/${slug}/manage`}>
            Administrér
          </ButtonLink>
        </div></>}>
        <div>

          <p className="muted">
            {v.company.cvr ? `CVR ${v.company.cvr} · ` : ""}
            {v.company.country} · {currency} · Moms
          </p>
        </div>

      </PageHeader>

      <CompanyNav
        slug={slug}
        years={v.fiscalYears}
        selectedYear={v.selectedYear}
        onYearChange={setYear}
      />

      {native && <VatTaskPanel slug={slug} vat={v} verified={!state.loading && !state.error} onRefresh={state.reload} />}
      {native && <OssReportPanel key={slug} slug={slug} />}

      {closedNotice && <Banner kind="success">{closedNotice}</Banner>}
      {v.periodActionsAvailable === false && <Banner kind="warning">Momsoverblikket kan vises og hentes som PDF. Periodelukning og indberetning er endnu ikke tilgængelige.</Banner>}

      {v.vatReportErrors.length > 0 && (
        <Banner kind="error">
          Momsrapporten kan ikke indberettes endnu: {v.vatReportErrors.join(" ")}
        </Banner>
      )}

      {v.vatReportWarnings.length > 0 && (
        <Banner kind="warning">
          Kontrollér før indberetning: {v.vatReportWarnings.join(" ")}
        </Banner>
      )}

      {closing && (
        <ConfirmDialog
          title="Luk momsperiode"
          body={
            <>
              <p>
                Luk momsperioden <strong>{v.periodLabel}</strong> (
                {v.periodStart} – {v.periodEnd}). En lukket periode er en
                forudsætning for at indberette momsangivelsen, og bogføring i
                perioden låses bagefter.
              </p>
              {/* #301: a future period-end means the period is not over yet.
                  Warn clearly and require a second, explicit acknowledgement
                  before the close can go through. */}
              {periodEndsInFuture && (
                <>
                  <Banner kind="warning">
                    Denne momsperiode er <strong>ikke afsluttet endnu</strong> —
                    slutdatoen {v.periodEnd} ligger i fremtiden. Lukker du nu,
                    blokeres bogføring med dato i perioden, og tallene i
                    momsangivelsen kan stadig nå at ændre sig. Luk normalt først
                    perioden, når den er forbi.
                  </Banner>
                  <label className="confirm-ack">
                    <Input
                      type="checkbox"
                      checked={futureEndAcknowledged}
                      onChange={(e) =>
                        setFutureEndAcknowledged(e.target.checked)
                      }
                    />
                    Jeg forstår at perioden ikke er afsluttet, og vil lukke den
                    alligevel.
                  </label>
                  <p className="muted">
                    Lukker du ved en fejl, kan perioden genåbnes igen herfra
                    (Genåbn momsperiode).
                  </p>
                </>
              )}
            </>
          }
          confirmLabel="Luk perioden"
          confirmKind="danger"
          onConfirm={async () => {
            // #301: a future-end period close requires the explicit extra
            // acknowledgement. Without it the close is blocked with a clear
            // message rather than going through silently.
            if (periodEndsInFuture && !futureEndAcknowledged) {
              throw {
                code: "bad_request",
                status: 400,
                message:
                  "Bekræft først at du vil lukke en periode der ikke er afsluttet endnu — sæt flueben i feltet ovenfor.",
              };
            }
            const packet = await api.closeReadiness(slug, v.periodStart, v.periodEnd);
            if (packet.blockers > 0) {
              throw { code: "bad_request", message: "Momsperioden har blokerende close-kontroller. Åbn Periodelås for at gennemgå dem." };
            }
            const review = await api.reviewCloseReadiness(slug, v.periodStart, v.periodEnd);
            if (review.packet.hash !== packet.hash) {
              throw { code: "conflict", message: "Grundlaget ændrede sig under review. Kontrollér momsperioden igen før lukning." };
            }
            await api.closePeriod(slug, {
              periodStart: v.periodStart,
              periodEnd: v.periodEnd,
              kind: "vat_period",
              packetHash: review.packet.hash,
              reviewId: review.id,
            });
            setClosedNotice(`Momsperioden er lukket — tallene genindlæses nu.`);
            state.reload();
          }}
          onClose={() => setClosing(false)} onRefresh={state.reload}
        />
      )}

      {reopening && (
        <ReopenDialog
          vat={v}
          onRefresh={state.reload}
          onReopened={(label) => {
            setClosedNotice(
              `Momsperioden ${label} er genåbnet — bogføring i perioden er tilladt igen.`,
            );
            state.reload();
          }}
          onClose={() => setReopening(false)}
        />
      )}

      {v.archived ? (
        <ArchivedNotice year={v.selectedYear} />
      ) : (
        <>
          <p className="statement-asof muted">
            {v.periodLabel} · {v.periodStart} – {v.periodEnd}
          </p>

          {/* #303: for an OPEN period the figures are not final — say so,
              honestly, instead of presenting a ready-to-file momsangivelse. */}
          {provisional && (
            <Banner kind="warning">
              Åben periode — foreløbige tal. Momsperioden {v.periodLabel} er
              ikke lukket endnu, så tallene kan stadig ændre sig og udgør ikke
              en indberetningsklar momsangivelse. Luk perioden, når den er
              forbi, for at få de endelige tal.
            </Banner>
          )}
          <div className="card statement-card">
            <div className="table-scroll"><table className="data statement-table">
              <tbody>
                <tr>
                  <td>Udgående moms før tab (kontrol)</td>
                  <td className="num">
                    {formatKroner(v.outputVat, currency)}
                  </td>
                </tr>
                {/* A bad-debt write-off (debitortab) claims back the output
                    VAT on a receivable that will never be paid. It is shown
                    on its own line so it never silently turns the salgsmoms
                    headline above negative (#271). */}
                {v.outputVatAdjustment !== 0 && (
                  <tr>
                    <td>Regulering for tab på debitorer (debitortab)</td>
                    <td className="num">
                      {formatKroner(v.outputVatAdjustment, currency)}
                    </td>
                  </tr>
                )}
                <tr>
                  <td>Købsmoms (indgående moms)</td>
                  <td className="num">
                    {formatKroner(v.inputVat, currency)}
                  </td>
                </tr>
                <tr
                  className={`statement-result ${
                    payablePositive ? "positive" : "negative"
                  }`}
                >
                  <td>{payablePositive ? "Moms at betale" : "Moms tilgode"}</td>
                  <td className="num">{formatKroner(v.payable, currency)}</td>
                </tr>
              </tbody>
            </table></div>
          </div>

          <div className="card statement-card vat-deadline">
            <div>
              <span className="vat-deadline-label">Angives og betales senest</span>
              <span className="vat-deadline-date">{formatDateDa(v.deadline)}</span>
            </div>
            <DeadlineCountdown days={v.daysRemaining} />
          </div>

          <RubrikkerCard
            rubrikker={v.rubrikker}
            currency={currency}
            provisional={provisional}
          />

          <p className="statement-check ok">
            {payablePositive
              ? "Momstilsvaret nedenfor er det samlede beløb, der skal afregnes til SKAT."
              : "Momstilsvaret nedenfor er det samlede beløb, der udbetales fra SKAT."}
          </p>
        </>
      )}
    </section>
  );
}

/**
 * The full SKAT TastSelv momsangivelse rubrics — the exact numbers an owner
 * types into the momsangivelse on skat.dk. Surfacing these (#257) means the
 * cockpit's VAT view is filing-complete: rubrik A/B/C and the foreign
 * goods/services VAT no longer force a trip to the terminal's
 * `vat momsangivelse`.
 *
 * #303: for an OPEN period the terminal `vat momsangivelse` refuses to produce
 * a momsangivelse at all (it requires a closed/reported VAT period).
 * The card must therefore NOT claim its figures match that command — instead
 * it marks them provisional and says a closed period is the prerequisite.
 */
/** All rubrikker as label/raw-number pairs, in the order shown in the UI. */
function rubrikkerCsvRows(
  rubrikker: VatRubrikker,
): Array<[string, string]> {
  const owedPositive = rubrikker.momstilsvar >= 0;
  return [
    ["Salgsmoms", tastSelvNumber(rubrikker.salgsmoms)],
    [
      "Moms af varekøb i udlandet",
      tastSelvNumber(rubrikker.momsAfVarekobUdland),
    ],
    [
      "Moms af ydelseskøb i udlandet",
      tastSelvNumber(rubrikker.momsAfYdelseskobUdland),
    ],
    ["Købsmoms", tastSelvNumber(rubrikker.kobsmoms)],
    [
      owedPositive ? "Momstilsvar" : "Negativt momstilsvar",
      tastSelvNumber(rubrikker.momstilsvar),
    ],
    [
      "Rubrik A - varer og ydelser købt i udlandet",
      tastSelvNumber(rubrikker.rubrikA),
    ],
    [
      "Rubrik B - varer og ydelser solgt til udlandet",
      tastSelvNumber(rubrikker.rubrikB),
    ],
    ["Rubrik C - øvrige momsfrie salg", tastSelvNumber(rubrikker.rubrikC)],
  ];
}

/**
 * One row's Kopier-button. Copies ONLY the raw TastSelv-format number (no
 * thousand separator, no "kr.") to the clipboard, then briefly shows
 * "Kopieret" without stealing focus. For a provisional (open-period) row the
 * button is disabled with a title explaining why — the owner must not paste
 * foreløbige tal into a real momsangivelse.
 */
function CopyRubrikButton({
  rawValue,
  label,
  provisional,
  onCopied,
  copied,
}: {
  rawValue: string;
  label: string;
  provisional: boolean;
  onCopied: () => void;
  copied: boolean;
}) {
  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(rawValue);
      onCopied();
    } catch {
      // Clipboard write can fail (insecure context, permission denied) —
      // silently ignore: the owner can still read the figure on screen.
    }
  }
  return (
    <span className="rubrik-copy">
      {copied && (
        <span className="rubrik-copy-feedback" aria-live="polite">
          Kopieret
        </span>
      )}
      <Button
        type="button"
        className="rubrik-copy-btn"
        onClick={handleCopy}
        disabled={provisional}
        aria-label={`Kopier ${label}`}
        title={
          provisional
            ? "Periode ikke lukket — luk først for at få endelige tal"
            : `Kopier ${label} til udklipsholderen`
        }
      >
        Kopier
      </Button>
    </span>
  );
}

function RubrikkerCard({
  rubrikker,
  currency,
  provisional,
}: {
  rubrikker: VatRubrikker;
  currency: string;
  provisional: boolean;
}) {
  const owedPositive = rubrikker.momstilsvar >= 0;
  // The label of the row most recently copied — drives the "Kopieret"
  // confirmation, scoped per row so two adjacent buttons don't share state.
  const [copiedLabel, setCopiedLabel] = useState<string | null>(null);
  // Cleared after a short interval so the confirmation does not linger.
  function markCopied(label: string) {
    setCopiedLabel(label);
    setTimeout(() => {
      setCopiedLabel((current) => (current === label ? null : current));
    }, 1500);
  }
  async function copyAllAsCsv() {
    const rows = rubrikkerCsvRows(rubrikker);
    const csv = rows.map(([label, value]) => `${label};${value}`).join("\n");
    try {
      await navigator.clipboard.writeText(csv);
      markCopied("__csv__");
    } catch {
      // ignore — see CopyRubrikButton.
    }
  }
  function rubrikRow(label: string, value: number, extraClass?: string) {
    return (
      <tr className={extraClass}>
        <td>{label}</td>
        <td className="num">
          <span className="rubrik-num">{formatKroner(value, currency)}</span>
          <CopyRubrikButton
            rawValue={tastSelvNumber(value)}
            label={label}
            provisional={provisional}
            onCopied={() => markCopied(label)}
            copied={copiedLabel === label}
          />
        </td>
      </tr>
    );
  }
  return (
    <div className="card statement-card">
      <div className="statement-card-head">
        <h3 className="statement-subhead">
          {provisional
            ? "SKAT-rubrikker (foreløbige — åben periode)"
            : "SKAT-rubrikker (momsangivelse)"}
        </h3>
        <Button
          type="button"
          className="rubrik-copy-csv"
          onClick={copyAllAsCsv}
          disabled={provisional}
          title={
            provisional
              ? "Periode ikke lukket — luk først for at få endelige tal"
              : "Kopier alle rubrikker som CSV (label;beløb) til regneark"
          }
        >
          {copiedLabel === "__csv__" ? "Kopieret" : "Kopier alle som CSV"}
        </Button>
      </div>
      <p className="muted statement-note">
        {provisional ? (
          <>
            De felter der hører til momsangivelsen på skat.dk (TastSelv
            Erhverv). Momsperioden er <strong>ikke lukket endnu</strong>, så
            tallene er foreløbige og kan stadig ændre sig. Når perioden er
            forbi og lukket, bliver tallene endelige og kan indberettes.
          </>
        ) : (
          <>
            Disse felter svarer 1:1 til momsangivelsen på skat.dk (TastSelv
            Erhverv) — udfyld dem som vist. Perioden er lukket, så tallene er
            endelige.
          </>
        )}
      </p>
      <div className="table-scroll"><table className="data statement-table">
        <tbody>
          {rubrikRow("Salgsmoms", rubrikker.salgsmoms)}
          {rubrikRow(
            "Moms af varekøb i udlandet (både EU og lande uden for EU)",
            rubrikker.momsAfVarekobUdland,
          )}
          {rubrikRow(
            "Moms af ydelseskøb i udlandet med omvendt betalingspligt",
            rubrikker.momsAfYdelseskobUdland,
          )}
          {rubrikRow("Købsmoms", rubrikker.kobsmoms)}
          {rubrikRow(
            owedPositive ? "Momstilsvar" : "Negativt momstilsvar",
            rubrikker.momstilsvar,
            `statement-result ${owedPositive ? "positive" : "negative"}`,
          )}
        </tbody>
      </table></div>
      <div className="table-scroll"><table className="data statement-table">
        <tbody>
          {rubrikRow(
            "Rubrik A — varer og ydelser købt i udlandet",
            rubrikker.rubrikA,
          )}
          {rubrikRow(
            "Rubrik B — varer og ydelser solgt til udlandet",
            rubrikker.rubrikB,
          )}
          {rubrikRow("Rubrik C — øvrige momsfrie salg", rubrikker.rubrikC)}
        </tbody>
      </table></div>
    </div>
  );
}

/**
 * The reopen-period confirm dialog (#301). Reopening is a controlled,
 * audit-logged action — it requires a free-text reason, recorded verbatim in
 * the audit log. The dialog reuses `ConfirmDialog`'s note field for that
 * reason and blocks the action until a reason is given.
 */
function ReopenDialog({
  vat,
  onReopened,
  onRefresh,
  onClose,
}: {
  vat: CompanyVatRegistered;
  onReopened: (label: string) => void;
  onRefresh: () => void;
  onClose: () => void;
}) {
  return (
    <ConfirmDialog
      title="Genåbn momsperiode"
      body={
        <>
          <p>
            Genåbn momsperioden <strong>{vat.periodLabel}</strong> (
            {vat.periodStart} – {vat.periodEnd}). Bogføring med dato i perioden
            bliver tilladt igen.
          </p>
          <p className="muted">
            Genåbningen er en kontrolleret, fuldt revisionssporet handling — den
            tilføjes som en ny linje i revisionssporet med din begrundelse.
            Selve periode-rækken ændres aldrig. En allerede indberettet
            (reported) periode kan ikke genåbnes.
          </p>
        </>
      }
      confirmLabel="Genåbn perioden"
      confirmKind="danger"
      noteLabel="Begrundelse (påkrævet)"
      notePlaceholder="Hvorfor genåbnes perioden? (fx 'bilag bogført for sent')"
      onConfirm={async (reason) => {
        if (reason.trim().length === 0) {
          throw {
            code: "bad_request",
            message:
              "Angiv en begrundelse — en genåbning skal kunne spores i revisionssporet.",
          };
        }
        await api.reopenPeriod(vat.slug, {
          periodStart: vat.periodStart,
          periodEnd: vat.periodEnd,
          kind: "vat_period",
          reason: reason.trim(),
        });
        onReopened(vat.periodLabel);
      }}
      onClose={onClose} onRefresh={onRefresh}
    />
  );
}

/**
 * The "X dage tilbage" countdown to the VAT filing deadline. Turns critical
 * once the deadline is near or passed, so an owner sees the urgency at a
 * glance — the momsangivelse is easy to forget.
 */
function DeadlineCountdown({ days }: { days: number }) {
  if (days < 0) {
    return (
      <span className="flag critical">
        Fristen er overskredet {Math.abs(days)}{" "}
        {Math.abs(days) === 1 ? "dag" : "dage"}
      </span>
    );
  }
  if (days === 0) return <span className="flag critical">Frist i dag</span>;
  const tone = days <= 30 ? "warning" : "ok";
  return (
    <span className={`flag ${tone}`}>
      {days} {days === 1 ? "dag" : "dage"} tilbage
    </span>
  );
}

function ArchivedNotice({ year }: { year: string }) {
  return (
    <div className="card archived-notice">
      <h3>Moms er ikke tilgængelig for {year}</h3>
      <p className="muted">
        {year} er et arkiveret regnskabsår. Momsopgørelsen beregnes fra den
        aktive ledgers bogførte momskonti, og en momsangivelse kan ikke
        rekonstrueres for et arkiveret år — den vises derfor ikke.
        Resultatopgørelse, balance, saldobalance og posteringer for {year} er
        tilgængelige.
      </p>
    </div>
  );
}

serverRequests.requestAndResultTypeScript:
vat: (slug: string, year?: string, options?: ReadRequestOptions) =>
    request<VatResponse>(
      `/api/companies/${encodeURIComponent(slug)}/vat${
        year ? `?year=${encodeURIComponent(year)}` : ""
      }`, options,
    ).then((r) => r.vat)

vatPdfUrl: (slug: string, year?: string) => {
    const params = new URLSearchParams({ format: "pdf" });
    if (year) params.set("year", year);
    return `/api/companies/${encodeURIComponent(slug)}/vat/export?${params.toString()}`;
  }

reopenPeriod: (slug: string, input: ReopenPeriodInput) =>
    request<ReopenPeriodResponse>(
      `/api/companies/${encodeURIComponent(slug)}/periods/reopen`,
      {
        method: "POST",
        body: JSON.stringify({
          periodStart: input.periodStart,
          periodEnd: input.periodEnd,
          ...(input.kind ? { kind: input.kind } : {}),
          reason: input.reason,
          confirm: true,
        }),
      },
    ).then((r) => r.period)

renderingAndEffects.viewTypeScript:
import { ButtonLink, Button, Input, PageHeader } from "../components/ui";
// Moms — the per-company VAT return (cockpit-redesign iteration 3).
//
// Renders `/api/companies/:slug/vat?year=` for the registered VAT cadence —
// output VAT (salgsmoms), input VAT (købsmoms), the resulting payable amount,
// AND the full SKAT TastSelv momsangivelse rubrics (rubrik A/B/C, foreign
// goods/services VAT) so the owner can file straight from the cockpit instead
// of dropping to the terminal (#257). All money fields are kroner —
// `formatKroner` is used throughout.

import { useState } from "react";
import { Link, useParams } from "react-router-dom";
import { api } from "../lib/api";
import { formatDateDa, formatKroner, tastSelvNumber, todayIso } from "../lib/format";
import { useAsync } from "../lib/useAsync";
import type { CompanyVat, CompanyVatRegistered, VatRubrikker } from "../lib/types";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { CompanyNav, useCompanyYear } from "../components/CompanyNav";
import { ConfirmDialog } from "../components/ConfirmDialog";
import { useOptionalAuth } from "../lib/auth-context";
import { OssReportPanel } from "./OssReportPanel";
import { VatTaskPanel } from "./VatTaskPanel";

export function VatView() {
  const { slug = "" } = useParams();
  const native = useOptionalAuth()?.backend === "rust";
  const { year, setYear } = useCompanyYear();
  const state = useAsync<CompanyVat>((signal) => api.vat(slug, year, { signal }), [slug, year]);
  // True while the close-period ConfirmDialog is open (#287).
  const [closing, setClosing] = useState(false);
  // True while the reopen-period ConfirmDialog is open (#301).
  const [reopening, setReopening] = useState(false);
  // #301: the second, explicit confirmation a future-end period close needs.
  const [futureEndAcknowledged, setFutureEndAcknowledged] = useState(false);
  // Set after a successful period close / reopen — surfaced as a success banner.
  const [closedNotice, setClosedNotice] = useState<string | null>(null);

  if (state.loading && !state.data) return <Loading label="Henter moms…" />;
  if (state.error && !state.data)
    return <ErrorState message={state.error} onRetry={state.reload} />;

  const v = state.data!;
  const currency = v.company.currency || "DKK";

  // A non-VAT-registered company has nothing to show on the moms-tab —
  // surface an explanation card instead of an empty rubrikker table. Render
  // early so none of the period-related controls below execute against the
  // missing period fields, and TypeScript narrows v to CompanyVatRegistered
  // below.
  if (!v.vatRegistered) {
    return (
      <section className="statement">
      {state.error && <div className="banner warning" role="alert">Status kunne ikke opdateres. De tidligere hentede oplysninger vises fortsat.</div>}
        <PageHeader title="Moms">
          <div>

            <p className="muted">
              {v.company.cvr ? `CVR ${v.company.cvr} · ` : ""}
              {v.company.country} · {currency} · Moms
            </p>
          </div>
        </PageHeader>
        <CompanyNav
          slug={slug}
          years={v.fiscalYears}
          selectedYear={v.selectedYear}
          onYearChange={setYear}
        />
        {native && <VatTaskPanel slug={slug} vat={v} verified={!state.loading && !state.error} onRefresh={state.reload} />}
        <Banner kind="warning">
          Denne virksomhed er ikke momsregistreret. Der er derfor ingen momsperiode,
          ingen momsangivelse og ingen SKAT-frist. Tilkøb af bilag med moms bogføres
          som ikke fradragsberettigede, så momsen indgår i udgiften. Skal selskabet alligevel momsregistreres, så sæt en
          momsperiode under <Link to={`/companies/${slug}/manage`}>Indstillinger</Link>.
        </Banner>
      </section>
    );
  }

  // TypeScript narrows v to CompanyVatRegistered after the !v.vatRegistered
  // early return above — every period/deadline/rubrikker field is non-null
  // from here on. No `!` or `?? ""` shims needed.
  const payablePositive = v.payable >= 0;
  // #301: a period whose end date is still in the future has not ended yet —
  // closing it now is almost always a mistake, so the confirm dialog warns.
  const periodEndsInFuture = v.periodEnd > todayIso();
  // #301: a closed (not reported) period can be reopened from the cockpit.
  const canReopen = v.periodActionsAvailable !== false && !v.archived && v.periodStatus === "closed";
  // #303: a momsangivelse is only filing-ready for a closed/reported period.
  const provisional = !v.archived && !v.momsangivelseReady;

  return (
    <section className="statement">
      {state.error && <div className="banner warning" role="alert">Status kunne ikke opdateres. De tidligere hentede oplysninger vises fortsat.</div>}
      <PageHeader title="Moms" actions={<><div className="row-actions">
          {/* #287: closing the VAT period is the prerequisite for a
              momsangivelse — hidden for an archived (read-only) year. Once the
              period is closed the action becomes a reopen instead (#301). */}
          {v.periodActionsAvailable !== false && !v.archived &&
            v.periodStatus === "open" &&
            v.vatReportErrors.length === 0 && (
            <Button requiredPermission="company.review"
              type="button"
              className="btn"
              onClick={() => {
                setFutureEndAcknowledged(false);
                setClosing(true);
              }}
            >
              Luk momsperiode
            </Button>
          )}
          {canReopen && (
            <Button requiredPermission="company.review" variant="secondary"
              type="button"
              className="btn secondary"
              onClick={() => setReopening(true)}
            >
              Genåbn momsperiode
            </Button>
          )}
          {/* #464 — moms-rapport som printbar PDF inkl. SKAT-rubrikker + frist. */}
          <a
            className="btn secondary"
            href={api.vatPdfUrl(slug, v.selectedYear)}
            download
          >
            Hent PDF
          </a>
          <ButtonLink className="btn secondary" to={`/companies/${slug}/manage`}>
            Administrér
          </ButtonLink>
        </div></>}>
        <div>

          <p className="muted">
            {v.company.cvr ? `CVR ${v.company.cvr} · ` : ""}
            {v.company.country} · {currency} · Moms
          </p>
        </div>

      </PageHeader>

      <CompanyNav
        slug={slug}
        years={v.fiscalYears}
        selectedYear={v.selectedYear}
        onYearChange={setYear}
      />

      {native && <VatTaskPanel slug={slug} vat={v} verified={!state.loading && !state.error} onRefresh={state.reload} />}
      {native && <OssReportPanel key={slug} slug={slug} />}

      {closedNotice && <Banner kind="success">{closedNotice}</Banner>}
      {v.periodActionsAvailable === false && <Banner kind="warning">Momsoverblikket kan vises og hentes som PDF. Periodelukning og indberetning er endnu ikke tilgængelige.</Banner>}

      {v.vatReportErrors.length > 0 && (
        <Banner kind="error">
          Momsrapporten kan ikke indberettes endnu: {v.vatReportErrors.join(" ")}
        </Banner>
      )}

      {v.vatReportWarnings.length > 0 && (
        <Banner kind="warning">
          Kontrollér før indberetning: {v.vatReportWarnings.join(" ")}
        </Banner>
      )}

      {closing && (
        <ConfirmDialog
          title="Luk momsperiode"
          body={
            <>
              <p>
                Luk momsperioden <strong>{v.periodLabel}</strong> (
                {v.periodStart} – {v.periodEnd}). En lukket periode er en
                forudsætning for at indberette momsangivelsen, og bogføring i
                perioden låses bagefter.
              </p>
              {/* #301: a future period-end means the period is not over yet.
                  Warn clearly and require a second, explicit acknowledgement
                  before the close can go through. */}
              {periodEndsInFuture && (
                <>
                  <Banner kind="warning">
                    Denne momsperiode er <strong>ikke afsluttet endnu</strong> —
                    slutdatoen {v.periodEnd} ligger i fremtiden. Lukker du nu,
                    blokeres bogføring med dato i perioden, og tallene i
                    momsangivelsen kan stadig nå at ændre sig. Luk normalt først
                    perioden, når den er forbi.
                  </Banner>
                  <label className="confirm-ack">
                    <Input
                      type="checkbox"
                      checked={futureEndAcknowledged}
                      onChange={(e) =>
                        setFutureEndAcknowledged(e.target.checked)
                      }
                    />
                    Jeg forstår at perioden ikke er afsluttet, og vil lukke den
                    alligevel.
                  </label>
                  <p className="muted">
                    Lukker du ved en fejl, kan perioden genåbnes igen herfra
                    (Genåbn momsperiode).
                  </p>
                </>
              )}
            </>
          }
          confirmLabel="Luk perioden"
          confirmKind="danger"
          onConfirm={async () => {
            // #301: a future-end period close requires the explicit extra
            // acknowledgement. Without it the close is blocked with a clear
            // message rather than going through silently.
            if (periodEndsInFuture && !futureEndAcknowledged) {
              throw {
                code: "bad_request",
                status: 400,
                message:
                  "Bekræft først at du vil lukke en periode der ikke er afsluttet endnu — sæt flueben i feltet ovenfor.",
              };
            }
            const packet = await api.closeReadiness(slug, v.periodStart, v.periodEnd);
            if (packet.blockers > 0) {
              throw { code: "bad_request", message: "Momsperioden har blokerende close-kontroller. Åbn Periodelås for at gennemgå dem." };
            }
            const review = await api.reviewCloseReadiness(slug, v.periodStart, v.periodEnd);
            if (review.packet.hash !== packet.hash) {
              throw { code: "conflict", message: "Grundlaget ændrede sig under review. Kontrollér momsperioden igen før lukning." };
            }
            await api.closePeriod(slug, {
              periodStart: v.periodStart,
              periodEnd: v.periodEnd,
              kind: "vat_period",
              packetHash: review.packet.hash,
              reviewId: review.id,
            });
            setClosedNotice(`Momsperioden er lukket — tallene genindlæses nu.`);
            state.reload();
          }}
          onClose={() => setClosing(false)} onRefresh={state.reload}
        />
      )}

      {reopening && (
        <ReopenDialog
          vat={v}
          onRefresh={state.reload}
          onReopened={(label) => {
            setClosedNotice(
              `Momsperioden ${label} er genåbnet — bogføring i perioden er tilladt igen.`,
            );
            state.reload();
          }}
          onClose={() => setReopening(false)}
        />
      )}

      {v.archived ? (
        <ArchivedNotice year={v.selectedYear} />
      ) : (
        <>
          <p className="statement-asof muted">
            {v.periodLabel} · {v.periodStart} – {v.periodEnd}
          </p>

          {/* #303: for an OPEN period the figures are not final — say so,
              honestly, instead of presenting a ready-to-file momsangivelse. */}
          {provisional && (
            <Banner kind="warning">
              Åben periode — foreløbige tal. Momsperioden {v.periodLabel} er
              ikke lukket endnu, så tallene kan stadig ændre sig og udgør ikke
              en indberetningsklar momsangivelse. Luk perioden, når den er
              forbi, for at få de endelige tal.
            </Banner>
          )}
          <div className="card statement-card">
            <div className="table-scroll"><table className="data statement-table">
              <tbody>
                <tr>
                  <td>Udgående moms før tab (kontrol)</td>
                  <td className="num">
                    {formatKroner(v.outputVat, currency)}
                  </td>
                </tr>
                {/* A bad-debt write-off (debitortab) claims back the output
                    VAT on a receivable that will never be paid. It is shown
                    on its own line so it never silently turns the salgsmoms
                    headline above negative (#271). */}
                {v.outputVatAdjustment !== 0 && (
                  <tr>
                    <td>Regulering for tab på debitorer (debitortab)</td>
                    <td className="num">
                      {formatKroner(v.outputVatAdjustment, currency)}
                    </td>
                  </tr>
                )}
                <tr>
                  <td>Købsmoms (indgående moms)</td>
                  <td className="num">
                    {formatKroner(v.inputVat, currency)}
                  </td>
                </tr>
                <tr
                  className={`statement-result ${
                    payablePositive ? "positive" : "negative"
                  }`}
                >
                  <td>{payablePositive ? "Moms at betale" : "Moms tilgode"}</td>
                  <td className="num">{formatKroner(v.payable, currency)}</td>
                </tr>
              </tbody>
            </table></div>
          </div>

          <div className="card statement-card vat-deadline">
            <div>
              <span className="vat-deadline-label">Angives og betales senest</span>
              <span className="vat-deadline-date">{formatDateDa(v.deadline)}</span>
            </div>
            <DeadlineCountdown days={v.daysRemaining} />
          </div>

          <RubrikkerCard
            rubrikker={v.rubrikker}
            currency={currency}
            provisional={provisional}
          />

          <p className="statement-check ok">
            {payablePositive
              ? "Momstilsvaret nedenfor er det samlede beløb, der skal afregnes til SKAT."
              : "Momstilsvaret nedenfor er det samlede beløb, der udbetales fra SKAT."}
          </p>
        </>
      )}
    </section>
  );
}

/**
 * The full SKAT TastSelv momsangivelse rubrics — the exact numbers an owner
 * types into the momsangivelse on skat.dk. Surfacing these (#257) means the
 * cockpit's VAT view is filing-complete: rubrik A/B/C and the foreign
 * goods/services VAT no longer force a trip to the terminal's
 * `vat momsangivelse`.
 *
 * #303: for an OPEN period the terminal `vat momsangivelse` refuses to produce
 * a momsangivelse at all (it requires a closed/reported VAT period).
 * The card must therefore NOT claim its figures match that command — instead
 * it marks them provisional and says a closed period is the prerequisite.
 */
/** All rubrikker as label/raw-number pairs, in the order shown in the UI. */
function rubrikkerCsvRows(
  rubrikker: VatRubrikker,
): Array<[string, string]> {
  const owedPositive = rubrikker.momstilsvar >= 0;
  return [
    ["Salgsmoms", tastSelvNumber(rubrikker.salgsmoms)],
    [
      "Moms af varekøb i udlandet",
      tastSelvNumber(rubrikker.momsAfVarekobUdland),
    ],
    [
      "Moms af ydelseskøb i udlandet",
      tastSelvNumber(rubrikker.momsAfYdelseskobUdland),
    ],
    ["Købsmoms", tastSelvNumber(rubrikker.kobsmoms)],
    [
      owedPositive ? "Momstilsvar" : "Negativt momstilsvar",
      tastSelvNumber(rubrikker.momstilsvar),
    ],
    [
      "Rubrik A - varer og ydelser købt i udlandet",
      tastSelvNumber(rubrikker.rubrikA),
    ],
    [
      "Rubrik B - varer og ydelser solgt til udlandet",
      tastSelvNumber(rubrikker.rubrikB),
    ],
    ["Rubrik C - øvrige momsfrie salg", tastSelvNumber(rubrikker.rubrikC)],
  ];
}

/**
 * One row's Kopier-button. Copies ONLY the raw TastSelv-format number (no
 * thousand separator, no "kr.") to the clipboard, then briefly shows
 * "Kopieret" without stealing focus. For a provisional (open-period) row the
 * button is disabled with a title explaining why — the owner must not paste
 * foreløbige tal into a real momsangivelse.
 */
function CopyRubrikButton({
  rawValue,
  label,
  provisional,
  onCopied,
  copied,
}: {
  rawValue: string;
  label: string;
  provisional: boolean;
  onCopied: () => void;
  copied: boolean;
}) {
  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(rawValue);
      onCopied();
    } catch {
      // Clipboard write can fail (insecure context, permission denied) —
      // silently ignore: the owner can still read the figure on screen.
    }
  }
  return (
    <span className="rubrik-copy">
      {copied && (
        <span className="rubrik-copy-feedback" aria-live="polite">
          Kopieret
        </span>
      )}
      <Button
        type="button"
        className="rubrik-copy-btn"
        onClick={handleCopy}
        disabled={provisional}
        aria-label={`Kopier ${label}`}
        title={
          provisional
            ? "Periode ikke lukket — luk først for at få endelige tal"
            : `Kopier ${label} til udklipsholderen`
        }
      >
        Kopier
      </Button>
    </span>
  );
}

function RubrikkerCard({
  rubrikker,
  currency,
  provisional,
}: {
  rubrikker: VatRubrikker;
  currency: string;
  provisional: boolean;
}) {
  const owedPositive = rubrikker.momstilsvar >= 0;
  // The label of the row most recently copied — drives the "Kopieret"
  // confirmation, scoped per row so two adjacent buttons don't share state.
  const [copiedLabel, setCopiedLabel] = useState<string | null>(null);
  // Cleared after a short interval so the confirmation does not linger.
  function markCopied(label: string) {
    setCopiedLabel(label);
    setTimeout(() => {
      setCopiedLabel((current) => (current === label ? null : current));
    }, 1500);
  }
  async function copyAllAsCsv() {
    const rows = rubrikkerCsvRows(rubrikker);
    const csv = rows.map(([label, value]) => `${label};${value}`).join("\n");
    try {
      await navigator.clipboard.writeText(csv);
      markCopied("__csv__");
    } catch {
      // ignore — see CopyRubrikButton.
    }
  }
  function rubrikRow(label: string, value: number, extraClass?: string) {
    return (
      <tr className={extraClass}>
        <td>{label}</td>
        <td className="num">
          <span className="rubrik-num">{formatKroner(value, currency)}</span>
          <CopyRubrikButton
            rawValue={tastSelvNumber(value)}
            label={label}
            provisional={provisional}
            onCopied={() => markCopied(label)}
            copied={copiedLabel === label}
          />
        </td>
      </tr>
    );
  }
  return (
    <div className="card statement-card">
      <div className="statement-card-head">
        <h3 className="statement-subhead">
          {provisional
            ? "SKAT-rubrikker (foreløbige — åben periode)"
            : "SKAT-rubrikker (momsangivelse)"}
        </h3>
        <Button
          type="button"
          className="rubrik-copy-csv"
          onClick={copyAllAsCsv}
          disabled={provisional}
          title={
            provisional
              ? "Periode ikke lukket — luk først for at få endelige tal"
              : "Kopier alle rubrikker som CSV (label;beløb) til regneark"
          }
        >
          {copiedLabel === "__csv__" ? "Kopieret" : "Kopier alle som CSV"}
        </Button>
      </div>
      <p className="muted statement-note">
        {provisional ? (
          <>
            De felter der hører til momsangivelsen på skat.dk (TastSelv
            Erhverv). Momsperioden er <strong>ikke lukket endnu</strong>, så
            tallene er foreløbige og kan stadig ændre sig. Når perioden er
            forbi og lukket, bliver tallene endelige og kan indberettes.
          </>
        ) : (
          <>
            Disse felter svarer 1:1 til momsangivelsen på skat.dk (TastSelv
            Erhverv) — udfyld dem som vist. Perioden er lukket, så tallene er
            endelige.
          </>
        )}
      </p>
      <div className="table-scroll"><table className="data statement-table">
        <tbody>
          {rubrikRow("Salgsmoms", rubrikker.salgsmoms)}
          {rubrikRow(
            "Moms af varekøb i udlandet (både EU og lande uden for EU)",
            rubrikker.momsAfVarekobUdland,
          )}
          {rubrikRow(
            "Moms af ydelseskøb i udlandet med omvendt betalingspligt",
            rubrikker.momsAfYdelseskobUdland,
          )}
          {rubrikRow("Købsmoms", rubrikker.kobsmoms)}
          {rubrikRow(
            owedPositive ? "Momstilsvar" : "Negativt momstilsvar",
            rubrikker.momstilsvar,
            `statement-result ${owedPositive ? "positive" : "negative"}`,
          )}
        </tbody>
      </table></div>
      <div className="table-scroll"><table className="data statement-table">
        <tbody>
          {rubrikRow(
            "Rubrik A — varer og ydelser købt i udlandet",
            rubrikker.rubrikA,
          )}
          {rubrikRow(
            "Rubrik B — varer og ydelser solgt til udlandet",
            rubrikker.rubrikB,
          )}
          {rubrikRow("Rubrik C — øvrige momsfrie salg", rubrikker.rubrikC)}
        </tbody>
      </table></div>
    </div>
  );
}

/**
 * The reopen-period confirm dialog (#301). Reopening is a controlled,
 * audit-logged action — it requires a free-text reason, recorded verbatim in
 * the audit log. The dialog reuses `ConfirmDialog`'s note field for that
 * reason and blocks the action until a reason is given.
 */
function ReopenDialog({
  vat,
  onReopened,
  onRefresh,
  onClose,
}: {
  vat: CompanyVatRegistered;
  onReopened: (label: string) => void;
  onRefresh: () => void;
  onClose: () => void;
}) {
  return (
    <ConfirmDialog
      title="Genåbn momsperiode"
      body={
        <>
          <p>
            Genåbn momsperioden <strong>{vat.periodLabel}</strong> (
            {vat.periodStart} – {vat.periodEnd}). Bogføring med dato i perioden
            bliver tilladt igen.
          </p>
          <p className="muted">
            Genåbningen er en kontrolleret, fuldt revisionssporet handling — den
            tilføjes som en ny linje i revisionssporet med din begrundelse.
            Selve periode-rækken ændres aldrig. En allerede indberettet
            (reported) periode kan ikke genåbnes.
          </p>
        </>
      }
      confirmLabel="Genåbn perioden"
      confirmKind="danger"
      noteLabel="Begrundelse (påkrævet)"
      notePlaceholder="Hvorfor genåbnes perioden? (fx 'bilag bogført for sent')"
      onConfirm={async (reason) => {
        if (reason.trim().length === 0) {
          throw {
            code: "bad_request",
            message:
              "Angiv en begrundelse — en genåbning skal kunne spores i revisionssporet.",
          };
        }
        await api.reopenPeriod(vat.slug, {
          periodStart: vat.periodStart,
          periodEnd: vat.periodEnd,
          kind: "vat_period",
          reason: reason.trim(),
        });
        onReopened(vat.periodLabel);
      }}
      onClose={onClose} onRefresh={onRefresh}
    />
  );
}

/**
 * The "X dage tilbage" countdown to the VAT filing deadline. Turns critical
 * once the deadline is near or passed, so an owner sees the urgency at a
 * glance — the momsangivelse is easy to forget.
 */
function DeadlineCountdown({ days }: { days: number }) {
  if (days < 0) {
    return (
      <span className="flag critical">
        Fristen er overskredet {Math.abs(days)}{" "}
        {Math.abs(days) === 1 ? "dag" : "dage"}
      </span>
    );
  }
  if (days === 0) return <span className="flag critical">Frist i dag</span>;
  const tone = days <= 30 ? "warning" : "ok";
  return (
    <span className={`flag ${tone}`}>
      {days} {days === 1 ? "dag" : "dage"} tilbage
    </span>
  );
}

function ArchivedNotice({ year }: { year: string }) {
  return (
    <div className="card archived-notice">
      <h3>Moms er ikke tilgængelig for {year}</h3>
      <p className="muted">
        {year} er et arkiveret regnskabsår. Momsopgørelsen beregnes fra den
        aktive ledgers bogførte momskonti, og en momsangivelse kan ikke
        rekonstrueres for et arkiveret år — den vises derfor ikke.
        Resultatopgørelse, balance, saldobalance og posteringer for {year} er
        tilgængelige.
      </p>
    </div>
  );
}

definition.viewSpecificRefusals:
import { ButtonLink, Button, Input, PageHeader } from "../components/ui";
// Moms — the per-company VAT return (cockpit-redesign iteration 3).
//
// Renders `/api/companies/:slug/vat?year=` for the registered VAT cadence —
// output VAT (salgsmoms), input VAT (købsmoms), the resulting payable amount,
// AND the full SKAT TastSelv momsangivelse rubrics (rubrik A/B/C, foreign
// goods/services VAT) so the owner can file straight from the cockpit instead
// of dropping to the terminal (#257). All money fields are kroner —
// `formatKroner` is used throughout.

import { useState } from "react";
import { Link, useParams } from "react-router-dom";
import { api } from "../lib/api";
import { formatDateDa, formatKroner, tastSelvNumber, todayIso } from "../lib/format";
import { useAsync } from "../lib/useAsync";
import type { CompanyVat, CompanyVatRegistered, VatRubrikker } from "../lib/types";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { CompanyNav, useCompanyYear } from "../components/CompanyNav";
import { ConfirmDialog } from "../components/ConfirmDialog";
import { useOptionalAuth } from "../lib/auth-context";
import { OssReportPanel } from "./OssReportPanel";
import { VatTaskPanel } from "./VatTaskPanel";

export function VatView() {
  const { slug = "" } = useParams();
  const native = useOptionalAuth()?.backend === "rust";
  const { year, setYear } = useCompanyYear();
  const state = useAsync<CompanyVat>((signal) => api.vat(slug, year, { signal }), [slug, year]);
  // True while the close-period ConfirmDialog is open (#287).
  const [closing, setClosing] = useState(false);
  // True while the reopen-period ConfirmDialog is open (#301).
  const [reopening, setReopening] = useState(false);
  // #301: the second, explicit confirmation a future-end period close needs.
  const [futureEndAcknowledged, setFutureEndAcknowledged] = useState(false);
  // Set after a successful period close / reopen — surfaced as a success banner.
  const [closedNotice, setClosedNotice] = useState<string | null>(null);

  if (state.loading && !state.data) return <Loading label="Henter moms…" />;
  if (state.error && !state.data)
    return <ErrorState message={state.error} onRetry={state.reload} />;

  const v = state.data!;
  const currency = v.company.currency || "DKK";

  // A non-VAT-registered company has nothing to show on the moms-tab —
  // surface an explanation card instead of an empty rubrikker table. Render
  // early so none of the period-related controls below execute against the
  // missing period fields, and TypeScript narrows v to CompanyVatRegistered
  // below.
  if (!v.vatRegistered) {
    return (
      <section className="statement">
      {state.error && <div className="banner warning" role="alert">Status kunne ikke opdateres. De tidligere hentede oplysninger vises fortsat.</div>}
        <PageHeader title="Moms">
          <div>

            <p className="muted">
              {v.company.cvr ? `CVR ${v.company.cvr} · ` : ""}
              {v.company.country} · {currency} · Moms
            </p>
          </div>
        </PageHeader>
        <CompanyNav
          slug={slug}
          years={v.fiscalYears}
          selectedYear={v.selectedYear}
          onYearChange={setYear}
        />
        {native && <VatTaskPanel slug={slug} vat={v} verified={!state.loading && !state.error} onRefresh={state.reload} />}
        <Banner kind="warning">
          Denne virksomhed er ikke momsregistreret. Der er derfor ingen momsperiode,
          ingen momsangivelse og ingen SKAT-frist. Tilkøb af bilag med moms bogføres
          som ikke fradragsberettigede, så momsen indgår i udgiften. Skal selskabet alligevel momsregistreres, så sæt en
          momsperiode under <Link to={`/companies/${slug}/manage`}>Indstillinger</Link>.
        </Banner>
      </section>
    );
  }

  // TypeScript narrows v to CompanyVatRegistered after the !v.vatRegistered
  // early return above — every period/deadline/rubrikker field is non-null
  // from here on. No `!` or `?? ""` shims needed.
  const payablePositive = v.payable >= 0;
  // #301: a period whose end date is still in the future has not ended yet —
  // closing it now is almost always a mistake, so the confirm dialog warns.
  const periodEndsInFuture = v.periodEnd > todayIso();
  // #301: a closed (not reported) period can be reopened from the cockpit.
  const canReopen = v.periodActionsAvailable !== false && !v.archived && v.periodStatus === "closed";
  // #303: a momsangivelse is only filing-ready for a closed/reported period.
  const provisional = !v.archived && !v.momsangivelseReady;

  return (
    <section className="statement">
      {state.error && <div className="banner warning" role="alert">Status kunne ikke opdateres. De tidligere hentede oplysninger vises fortsat.</div>}
      <PageHeader title="Moms" actions={<><div className="row-actions">
          {/* #287: closing the VAT period is the prerequisite for a
              momsangivelse — hidden for an archived (read-only) year. Once the
              period is closed the action becomes a reopen instead (#301). */}
          {v.periodActionsAvailable !== false && !v.archived &&
            v.periodStatus === "open" &&
            v.vatReportErrors.length === 0 && (
            <Button requiredPermission="company.review"
              type="button"
              className="btn"
              onClick={() => {
                setFutureEndAcknowledged(false);
                setClosing(true);
              }}
            >
              Luk momsperiode
            </Button>
          )}
          {canReopen && (
            <Button requiredPermission="company.review" variant="secondary"
              type="button"
              className="btn secondary"
              onClick={() => setReopening(true)}
            >
              Genåbn momsperiode
            </Button>
          )}
          {/* #464 — moms-rapport som printbar PDF inkl. SKAT-rubrikker + frist. */}
          <a
            className="btn secondary"
            href={api.vatPdfUrl(slug, v.selectedYear)}
            download
          >
            Hent PDF
          </a>
          <ButtonLink className="btn secondary" to={`/companies/${slug}/manage`}>
            Administrér
          </ButtonLink>
        </div></>}>
        <div>

          <p className="muted">
            {v.company.cvr ? `CVR ${v.company.cvr} · ` : ""}
            {v.company.country} · {currency} · Moms
          </p>
        </div>

      </PageHeader>

      <CompanyNav
        slug={slug}
        years={v.fiscalYears}
        selectedYear={v.selectedYear}
        onYearChange={setYear}
      />

      {native && <VatTaskPanel slug={slug} vat={v} verified={!state.loading && !state.error} onRefresh={state.reload} />}
      {native && <OssReportPanel key={slug} slug={slug} />}

      {closedNotice && <Banner kind="success">{closedNotice}</Banner>}
      {v.periodActionsAvailable === false && <Banner kind="warning">Momsoverblikket kan vises og hentes som PDF. Periodelukning og indberetning er endnu ikke tilgængelige.</Banner>}

      {v.vatReportErrors.length > 0 && (
        <Banner kind="error">
          Momsrapporten kan ikke indberettes endnu: {v.vatReportErrors.join(" ")}
        </Banner>
      )}

      {v.vatReportWarnings.length > 0 && (
        <Banner kind="warning">
          Kontrollér før indberetning: {v.vatReportWarnings.join(" ")}
        </Banner>
      )}

      {closing && (
        <ConfirmDialog
          title="Luk momsperiode"
          body={
            <>
              <p>
                Luk momsperioden <strong>{v.periodLabel}</strong> (
                {v.periodStart} – {v.periodEnd}). En lukket periode er en
                forudsætning for at indberette momsangivelsen, og bogføring i
                perioden låses bagefter.
              </p>
              {/* #301: a future period-end means the period is not over yet.
                  Warn clearly and require a second, explicit acknowledgement
                  before the close can go through. */}
              {periodEndsInFuture && (
                <>
                  <Banner kind="warning">
                    Denne momsperiode er <strong>ikke afsluttet endnu</strong> —
                    slutdatoen {v.periodEnd} ligger i fremtiden. Lukker du nu,
                    blokeres bogføring med dato i perioden, og tallene i
                    momsangivelsen kan stadig nå at ændre sig. Luk normalt først
                    perioden, når den er forbi.
                  </Banner>
                  <label className="confirm-ack">
                    <Input
                      type="checkbox"
                      checked={futureEndAcknowledged}
                      onChange={(e) =>
                        setFutureEndAcknowledged(e.target.checked)
                      }
                    />
                    Jeg forstår at perioden ikke er afsluttet, og vil lukke den
                    alligevel.
                  </label>
                  <p className="muted">
                    Lukker du ved en fejl, kan perioden genåbnes igen herfra
                    (Genåbn momsperiode).
                  </p>
                </>
              )}
            </>
          }
          confirmLabel="Luk perioden"
          confirmKind="danger"
          onConfirm={async () => {
            // #301: a future-end period close requires the explicit extra
            // acknowledgement. Without it the close is blocked with a clear
            // message rather than going through silently.
            if (periodEndsInFuture && !futureEndAcknowledged) {
              throw {
                code: "bad_request",
                status: 400,
                message:
                  "Bekræft først at du vil lukke en periode der ikke er afsluttet endnu — sæt flueben i feltet ovenfor.",
              };
            }
            const packet = await api.closeReadiness(slug, v.periodStart, v.periodEnd);
            if (packet.blockers > 0) {
              throw { code: "bad_request", message: "Momsperioden har blokerende close-kontroller. Åbn Periodelås for at gennemgå dem." };
            }
            const review = await api.reviewCloseReadiness(slug, v.periodStart, v.periodEnd);
            if (review.packet.hash !== packet.hash) {
              throw { code: "conflict", message: "Grundlaget ændrede sig under review. Kontrollér momsperioden igen før lukning." };
            }
            await api.closePeriod(slug, {
              periodStart: v.periodStart,
              periodEnd: v.periodEnd,
              kind: "vat_period",
              packetHash: review.packet.hash,
              reviewId: review.id,
            });
            setClosedNotice(`Momsperioden er lukket — tallene genindlæses nu.`);
            state.reload();
          }}
          onClose={() => setClosing(false)} onRefresh={state.reload}
        />
      )}

      {reopening && (
        <ReopenDialog
          vat={v}
          onRefresh={state.reload}
          onReopened={(label) => {
            setClosedNotice(
              `Momsperioden ${label} er genåbnet — bogføring i perioden er tilladt igen.`,
            );
            state.reload();
          }}
          onClose={() => setReopening(false)}
        />
      )}

      {v.archived ? (
        <ArchivedNotice year={v.selectedYear} />
      ) : (
        <>
          <p className="statement-asof muted">
            {v.periodLabel} · {v.periodStart} – {v.periodEnd}
          </p>

          {/* #303: for an OPEN period the figures are not final — say so,
              honestly, instead of presenting a ready-to-file momsangivelse. */}
          {provisional && (
            <Banner kind="warning">
              Åben periode — foreløbige tal. Momsperioden {v.periodLabel} er
              ikke lukket endnu, så tallene kan stadig ændre sig og udgør ikke
              en indberetningsklar momsangivelse. Luk perioden, når den er
              forbi, for at få de endelige tal.
            </Banner>
          )}
          <div className="card statement-card">
            <div className="table-scroll"><table className="data statement-table">
              <tbody>
                <tr>
                  <td>Udgående moms før tab (kontrol)</td>
                  <td className="num">
                    {formatKroner(v.outputVat, currency)}
                  </td>
                </tr>
                {/* A bad-debt write-off (debitortab) claims back the output
                    VAT on a receivable that will never be paid. It is shown
                    on its own line so it never silently turns the salgsmoms
                    headline above negative (#271). */}
                {v.outputVatAdjustment !== 0 && (
                  <tr>
                    <td>Regulering for tab på debitorer (debitortab)</td>
                    <td className="num">
                      {formatKroner(v.outputVatAdjustment, currency)}
                    </td>
                  </tr>
                )}
                <tr>
                  <td>Købsmoms (indgående moms)</td>
                  <td className="num">
                    {formatKroner(v.inputVat, currency)}
                  </td>
                </tr>
                <tr
                  className={`statement-result ${
                    payablePositive ? "positive" : "negative"
                  }`}
                >
                  <td>{payablePositive ? "Moms at betale" : "Moms tilgode"}</td>
                  <td className="num">{formatKroner(v.payable, currency)}</td>
                </tr>
              </tbody>
            </table></div>
          </div>

          <div className="card statement-card vat-deadline">
            <div>
              <span className="vat-deadline-label">Angives og betales senest</span>
              <span className="vat-deadline-date">{formatDateDa(v.deadline)}</span>
            </div>
            <DeadlineCountdown days={v.daysRemaining} />
          </div>

          <RubrikkerCard
            rubrikker={v.rubrikker}
            currency={currency}
            provisional={provisional}
          />

          <p className="statement-check ok">
            {payablePositive
              ? "Momstilsvaret nedenfor er det samlede beløb, der skal afregnes til SKAT."
              : "Momstilsvaret nedenfor er det samlede beløb, der udbetales fra SKAT."}
          </p>
        </>
      )}
    </section>
  );
}

/**
 * The full SKAT TastSelv momsangivelse rubrics — the exact numbers an owner
 * types into the momsangivelse on skat.dk. Surfacing these (#257) means the
 * cockpit's VAT view is filing-complete: rubrik A/B/C and the foreign
 * goods/services VAT no longer force a trip to the terminal's
 * `vat momsangivelse`.
 *
 * #303: for an OPEN period the terminal `vat momsangivelse` refuses to produce
 * a momsangivelse at all (it requires a closed/reported VAT period).
 * The card must therefore NOT claim its figures match that command — instead
 * it marks them provisional and says a closed period is the prerequisite.
 */
/** All rubrikker as label/raw-number pairs, in the order shown in the UI. */
function rubrikkerCsvRows(
  rubrikker: VatRubrikker,
): Array<[string, string]> {
  const owedPositive = rubrikker.momstilsvar >= 0;
  return [
    ["Salgsmoms", tastSelvNumber(rubrikker.salgsmoms)],
    [
      "Moms af varekøb i udlandet",
      tastSelvNumber(rubrikker.momsAfVarekobUdland),
    ],
    [
      "Moms af ydelseskøb i udlandet",
      tastSelvNumber(rubrikker.momsAfYdelseskobUdland),
    ],
    ["Købsmoms", tastSelvNumber(rubrikker.kobsmoms)],
    [
      owedPositive ? "Momstilsvar" : "Negativt momstilsvar",
      tastSelvNumber(rubrikker.momstilsvar),
    ],
    [
      "Rubrik A - varer og ydelser købt i udlandet",
      tastSelvNumber(rubrikker.rubrikA),
    ],
    [
      "Rubrik B - varer og ydelser solgt til udlandet",
      tastSelvNumber(rubrikker.rubrikB),
    ],
    ["Rubrik C - øvrige momsfrie salg", tastSelvNumber(rubrikker.rubrikC)],
  ];
}

/**
 * One row's Kopier-button. Copies ONLY the raw TastSelv-format number (no
 * thousand separator, no "kr.") to the clipboard, then briefly shows
 * "Kopieret" without stealing focus. For a provisional (open-period) row the
 * button is disabled with a title explaining why — the owner must not paste
 * foreløbige tal into a real momsangivelse.
 */
function CopyRubrikButton({
  rawValue,
  label,
  provisional,
  onCopied,
  copied,
}: {
  rawValue: string;
  label: string;
  provisional: boolean;
  onCopied: () => void;
  copied: boolean;
}) {
  async function handleCopy() {
    try {
      await navigator.clipboard.writeText(rawValue);
      onCopied();
    } catch {
      // Clipboard write can fail (insecure context, permission denied) —
      // silently ignore: the owner can still read the figure on screen.
    }
  }
  return (
    <span className="rubrik-copy">
      {copied && (
        <span className="rubrik-copy-feedback" aria-live="polite">
          Kopieret
        </span>
      )}
      <Button
        type="button"
        className="rubrik-copy-btn"
        onClick={handleCopy}
        disabled={provisional}
        aria-label={`Kopier ${label}`}
        title={
          provisional
            ? "Periode ikke lukket — luk først for at få endelige tal"
            : `Kopier ${label} til udklipsholderen`
        }
      >
        Kopier
      </Button>
    </span>
  );
}

function RubrikkerCard({
  rubrikker,
  currency,
  provisional,
}: {
  rubrikker: VatRubrikker;
  currency: string;
  provisional: boolean;
}) {
  const owedPositive = rubrikker.momstilsvar >= 0;
  // The label of the row most recently copied — drives the "Kopieret"
  // confirmation, scoped per row so two adjacent buttons don't share state.
  const [copiedLabel, setCopiedLabel] = useState<string | null>(null);
  // Cleared after a short interval so the confirmation does not linger.
  function markCopied(label: string) {
    setCopiedLabel(label);
    setTimeout(() => {
      setCopiedLabel((current) => (current === label ? null : current));
    }, 1500);
  }
  async function copyAllAsCsv() {
    const rows = rubrikkerCsvRows(rubrikker);
    const csv = rows.map(([label, value]) => `${label};${value}`).join("\n");
    try {
      await navigator.clipboard.writeText(csv);
      markCopied("__csv__");
    } catch {
      // ignore — see CopyRubrikButton.
    }
  }
  function rubrikRow(label: string, value: number, extraClass?: string) {
    return (
      <tr className={extraClass}>
        <td>{label}</td>
        <td className="num">
          <span className="rubrik-num">{formatKroner(value, currency)}</span>
          <CopyRubrikButton
            rawValue={tastSelvNumber(value)}
            label={label}
            provisional={provisional}
            onCopied={() => markCopied(label)}
            copied={copiedLabel === label}
          />
        </td>
      </tr>
    );
  }
  return (
    <div className="card statement-card">
      <div className="statement-card-head">
        <h3 className="statement-subhead">
          {provisional
            ? "SKAT-rubrikker (foreløbige — åben periode)"
            : "SKAT-rubrikker (momsangivelse)"}
        </h3>
        <Button
          type="button"
          className="rubrik-copy-csv"
          onClick={copyAllAsCsv}
          disabled={provisional}
          title={
            provisional
              ? "Periode ikke lukket — luk først for at få endelige tal"
              : "Kopier alle rubrikker som CSV (label;beløb) til regneark"
          }
        >
          {copiedLabel === "__csv__" ? "Kopieret" : "Kopier alle som CSV"}
        </Button>
      </div>
      <p className="muted statement-note">
        {provisional ? (
          <>
            De felter der hører til momsangivelsen på skat.dk (TastSelv
            Erhverv). Momsperioden er <strong>ikke lukket endnu</strong>, så
            tallene er foreløbige og kan stadig ændre sig. Når perioden er
            forbi og lukket, bliver tallene endelige og kan indberettes.
          </>
        ) : (
          <>
            Disse felter svarer 1:1 til momsangivelsen på skat.dk (TastSelv
            Erhverv) — udfyld dem som vist. Perioden er lukket, så tallene er
            endelige.
          </>
        )}
      </p>
      <div className="table-scroll"><table className="data statement-table">
        <tbody>
          {rubrikRow("Salgsmoms", rubrikker.salgsmoms)}
          {rubrikRow(
            "Moms af varekøb i udlandet (både EU og lande uden for EU)",
            rubrikker.momsAfVarekobUdland,
          )}
          {rubrikRow(
            "Moms af ydelseskøb i udlandet med omvendt betalingspligt",
            rubrikker.momsAfYdelseskobUdland,
          )}
          {rubrikRow("Købsmoms", rubrikker.kobsmoms)}
          {rubrikRow(
            owedPositive ? "Momstilsvar" : "Negativt momstilsvar",
            rubrikker.momstilsvar,
            `statement-result ${owedPositive ? "positive" : "negative"}`,
          )}
        </tbody>
      </table></div>
      <div className="table-scroll"><table className="data statement-table">
        <tbody>
          {rubrikRow(
            "Rubrik A — varer og ydelser købt i udlandet",
            rubrikker.rubrikA,
          )}
          {rubrikRow(
            "Rubrik B — varer og ydelser solgt til udlandet",
            rubrikker.rubrikB,
          )}
          {rubrikRow("Rubrik C — øvrige momsfrie salg", rubrikker.rubrikC)}
        </tbody>
      </table></div>
    </div>
  );
}

/**
 * The reopen-period confirm dialog (#301). Reopening is a controlled,
 * audit-logged action — it requires a free-text reason, recorded verbatim in
 * the audit log. The dialog reuses `ConfirmDialog`'s note field for that
 * reason and blocks the action until a reason is given.
 */
function ReopenDialog({
  vat,
  onReopened,
  onRefresh,
  onClose,
}: {
  vat: CompanyVatRegistered;
  onReopened: (label: string) => void;
  onRefresh: () => void;
  onClose: () => void;
}) {
  return (
    <ConfirmDialog
      title="Genåbn momsperiode"
      body={
        <>
          <p>
            Genåbn momsperioden <strong>{vat.periodLabel}</strong> (
            {vat.periodStart} – {vat.periodEnd}). Bogføring med dato i perioden
            bliver tilladt igen.
          </p>
          <p className="muted">
            Genåbningen er en kontrolleret, fuldt revisionssporet handling — den
            tilføjes som en ny linje i revisionssporet med din begrundelse.
            Selve periode-rækken ændres aldrig. En allerede indberettet
            (reported) periode kan ikke genåbnes.
          </p>
        </>
      }
      confirmLabel="Genåbn perioden"
      confirmKind="danger"
      noteLabel="Begrundelse (påkrævet)"
      notePlaceholder="Hvorfor genåbnes perioden? (fx 'bilag bogført for sent')"
      onConfirm={async (reason) => {
        if (reason.trim().length === 0) {
          throw {
            code: "bad_request",
            message:
              "Angiv en begrundelse — en genåbning skal kunne spores i revisionssporet.",
          };
        }
        await api.reopenPeriod(vat.slug, {
          periodStart: vat.periodStart,
          periodEnd: vat.periodEnd,
          kind: "vat_period",
          reason: reason.trim(),
        });
        onReopened(vat.periodLabel);
      }}
      onClose={onClose} onRefresh={onRefresh}
    />
  );
}

/**
 * The "X dage tilbage" countdown to the VAT filing deadline. Turns critical
 * once the deadline is near or passed, so an owner sees the urgency at a
 * glance — the momsangivelse is easy to forget.
 */
function DeadlineCountdown({ days }: { days: number }) {
  if (days < 0) {
    return (
      <span className="flag critical">
        Fristen er overskredet {Math.abs(days)}{" "}
        {Math.abs(days) === 1 ? "dag" : "dage"}
      </span>
    );
  }
  if (days === 0) return <span className="flag critical">Frist i dag</span>;
  const tone = days <= 30 ? "warning" : "ok";
  return (
    <span className={`flag ${tone}`}>
      {days} {days === 1 ? "dag" : "dage"} tilbage
    </span>
  );
}

function ArchivedNotice({ year }: { year: string }) {
  return (
    <div className="card archived-notice">
      <h3>Moms er ikke tilgængelig for {year}</h3>
      <p className="muted">
        {year} er et arkiveret regnskabsår. Momsopgørelsen beregnes fra den
        aktive ledgers bogførte momskonti, og en momsangivelse kan ikke
        rekonstrueres for et arkiveret år — den vises derfor ikke.
        Resultatopgørelse, balance, saldobalance og posteringer for {year} er
        tilgængelige.
      </p>
    </div>
  );
}

definition.api:
import { ordinaryWorkspaceWriteAllowed } from "../workspace-write-mode";
// Shared primitives for the cockpit API client.
//
// `ApiError` is the canonical error class every per-domain module throws via
// `request<T>(...)`. Re-exported from `app/src/lib/api.ts` so external callers
// keep importing it from the barrel.

/** Optional cancellation belongs to one read request, never shared state. */
export type ReadRequestOptions = Pick<RequestInit, "signal">;

function isAborted(cause: unknown, signal: AbortSignal | null | undefined): boolean {
  return signal?.aborted === true || (cause instanceof Error && cause.name === "AbortError");
}

/** A failed API call — carries the backend error code for precise handling. */
export class ApiError extends Error {
  readonly code: string;
  readonly status: number;
  constructor(code: string, message: string, status: number) {
    super(message);
    this.name = "ApiError";
    this.code = code;
    this.status = status;
  }
}

/** Raised once for an expired hosted browser session.  The app shell listens
 * for this event so an old view is never left visible after a 401. */
function signalAuthExpired(): void {
  if (typeof window !== "undefined") {
    window.dispatchEvent(new Event("rentemester:auth-expired"));
  }
}

type ApiRequestOptions = RequestInit & { readOnly?: boolean };

function isWrite(init?: ApiRequestOptions): boolean {
  return !init?.readOnly && init?.method !== undefined && !["GET", "HEAD"].includes(init.method.toUpperCase());
}

async function fetchResponse(path: string, init?: ApiRequestOptions): Promise<Response> {
  if (!ordinaryWorkspaceWriteAllowed(path, init?.method ?? "GET", init?.readOnly)) throw new ApiError("workspace_not_active", "Workspace er skrivebeskyttet. Kontrollér flytningens aktuelle tilstand.", 423);
  const { readOnly, ...fetchOptions } = init ?? {};
  try {
    return await fetch(path, {
      ...fetchOptions,
      credentials: "same-origin",
      headers: { "content-type": "application/json", ...(init?.headers ?? {}) },
    });
  } catch (cause) {
    if (isAborted(cause, init?.signal)) throw cause;
    throw new ApiError(
      "network",
      isWrite(init) ? "Handlingen kan være gennemført, men serverens resultat kunne ikke bekræftes. Kontrollér status, før du starter en ny handling." : "Kunne ikke nå serveren. Kontrollér forbindelsen og prøv igen.",
      0,
    );
  }
}

/** Decode the same server envelope for JSON responses and binary failures. */
function responseError(res: Response, body: unknown, fallback: string): ApiError {
  const env = body && typeof body === "object" ? body as { errors?: unknown; code?: unknown } : undefined;
  const errors = Array.isArray(env?.errors) ? env.errors.map(String) : [];
  const code = res.status === 401 ? "unauthorized" : typeof env?.code === "string" ? env.code : "internal";
  if (code === "unauthorized") signalAuthExpired();
  const message = res.status === 403 && ["access_denied", "forbidden", "internal"].includes(code)
    ? "Du har ikke adgang til denne handling. Bed workspace-ejeren kontrollere dine rettigheder."
    : errors[0] ?? (res.status === 401 ? "Din session er udløbet. Log ind igen." : fallback);
  return new ApiError(code, message, res.status);
}

function bodyReadError(res: Response, cause: unknown, init?: ApiRequestOptions): unknown {
  if (isAborted(cause, init?.signal)) return cause;
  return responseError(res, undefined, isWrite(init)
    ? "Serverens svar på handlingen kunne ikke læses. Kontrollér status, før du starter en ny handling."
    : "Serveren gav et ugyldigt svar.");
}

export async function request<T>(path: string, init?: ApiRequestOptions): Promise<T> {
  const res = await fetchResponse(path, init);
  let body: unknown;
  try {
    body = await res.json();
  } catch (cause) {
    throw bodyReadError(res, cause, init);
  }
  // A superseded auth read must not expire the newer session via its old 401.
  init?.signal?.throwIfAborted();
  if (body && typeof body === "object" && (body as { ok?: unknown }).ok === false) throw responseError(res, body, "Ukendt serverfejl.");
  if (!res.ok) throw responseError(res, undefined, `HTTP ${res.status}`);
  return body as T;
}

/** Binary success keeps domain headers; transport failures use the canonical seam. */
export async function requestBlob(path: string, init?: ApiRequestOptions): Promise<{ blob: Blob; headers: Headers }> {
  const res = await fetchResponse(path, init);
  if (!res.ok) {
    let body: unknown;
    try { body = await res.json(); } catch (cause) {
      if (isAborted(cause, init?.signal)) throw cause;
    }
    throw responseError(res, body, `HTTP ${res.status}`);
  }
  try {
    return { blob: await res.blob(), headers: res.headers };
  } catch (cause) {
    throw bodyReadError(res, cause, init);
  }
}

/** Picks the filename from a `filename*=UTF-8''…` content-disposition header. */
export function parseFilenameFromContentDisposition(cd: string | null): string | null {
  if (!cd) return null;
  const m = cd.match(/filename\*=UTF-8''([^;]+)/i);
  if (!m || !m[1]) return null;
  try {
    return decodeURIComponent(m[1]);
  } catch {
    return null;
  }
}

definition.viewTypeScript:
import { useEffect, useMemo, useState } from "react";
import { Link, useParams, useSearchParams } from "react-router-dom";
import { api } from "../lib/api";
import { useCapabilities } from "../lib/useCapabilities";
import { useAsync } from "../lib/useAsync";
import { useMutationOutcome } from "../lib/useMutationOutcome";
import { useUnsavedChanges } from "../lib/useUnsavedChanges";
import type {
  CompanyDocuments,
  DocumentRow,
  FiscalYearEntry,
} from "../lib/types";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { CompanyNav, useCompanyYear } from "../components/CompanyNav";
import { DocumentIngestModal } from "../components/DocumentIngestModal";
import { ConfirmDialog } from "../components/ConfirmDialog";
import { ButtonLink, Button, Input, Select, Amount, PageHeader, Pagination, FilterBar } from "../components/ui";
import { listPagination, listReturnTo, workflowTo } from "./workflow-navigation";

export type DocumentsPage = {
  documents: CompanyDocuments;
  fiscalYears: FiscalYearEntry[];
};

const DOC_TYPE_LABELS: Record<string, string> = {
  purchase_sale: "Køb/salg",
  cash_register_receipt: "Kassebon",
  internal_voucher: "Internt bilag",
  issued_invoice: "Udstedt faktura",
  issued_invoice_pdf: "PDF af udstedt faktura",
};

// #433 — the keys we own in the URL. Listed once so "Ryd filtre" can clear
// them all without touching other params (e.g. `?year=`).
const FILTER_PARAM_KEYS = ["q", "from", "to", "status", "type", "party"] as const;

type StatusFilter = "all" | "booked" | "unbooked";
type TypeFilter = "all" | "purchase_sale" | "cash_register_receipt" | "internal_voucher";

type SortKey = "date" | "amount";
type SortDir = "asc" | "desc";
type PartyFilter = "all" | "linked" | "unlinked" | "internal_no_external_party" | "ambiguous";
type PartyCandidate = { partyId: string; name: string };
type PartyPlan = {
  planHash: string;
  documentSha256?: string;
  documentPayloadSha256?: string;
  evidence?: { kind?: string; jurisdiction?: string; identifierKind?: string; identifier?: string };
  partySnapshot?: { name?: string };
};

function isStatusFilter(v: string): v is StatusFilter {
  return v === "all" || v === "booked" || v === "unbooked";
}
function isTypeFilter(v: string): v is TypeFilter {
  return (
    v === "all" ||
    v === "purchase_sale" ||
    v === "cash_register_receipt" ||
    v === "internal_voucher"
  );
}

export function documentAmount(doc: DocumentRow & { associations?: DocumentRow[] }): number | null {
  if (doc.amountIncVat !== null) return doc.amountIncVat;
  if (doc.associations && doc.associations.filter((entry) => entry.journalEntryNo).length > 1) return null;
  if (doc.journalEntryTotal !== null) return doc.journalEntryTotal;
  return null;
}

function documentMatchesText(doc: DocumentRow, needle: string): boolean {
  if (doc.supplierName && doc.supplierName.toLowerCase().includes(needle))
    return true;
  if (doc.documentNo && doc.documentNo.toLowerCase().includes(needle))
    return true;
  if (doc.invoiceNo && doc.invoiceNo.toLowerCase().includes(needle))
    return true;
  if (
    doc.accountingRationale &&
    doc.accountingRationale.toLowerCase().includes(needle)
  )
    return true;
  if (
    doc.sourceBankTransactionId !== null &&
    String(doc.sourceBankTransactionId).includes(needle)
  )
    return true;
  if (
    doc.journalEntryText &&
    doc.journalEntryText.toLowerCase().includes(needle)
  )
    return true;
  if (
    doc.journalEntryNo &&
    doc.journalEntryNo.toLowerCase().includes(needle)
  )
    return true;
  return false;
}

export type GroupedDocument = DocumentRow & { associations: DocumentRow[] };

/** One row per original document; each linked posting remains available. */
export function groupDocuments(rows: DocumentRow[]): GroupedDocument[] {
  const groups = new Map<number, GroupedDocument>();
  for (const row of rows) {
    const existing = groups.get(row.id);
    if (!existing) {
      groups.set(row.id, { ...row, associations: [row] });
      continue;
    }
    if (!existing.associations.some((entry) => entry.journalEntryId === row.journalEntryId && entry.journalEntryNo === row.journalEntryNo && entry.voucherRef === row.voucherRef)) existing.associations.push(row);
    // Representative posting identifies booked documents without summing relations.
    if (!existing.journalEntryNo && row.journalEntryNo) {
      existing.journalEntryNo = row.journalEntryNo;
      existing.journalEntryId = row.journalEntryId;
      existing.journalEntryText = row.journalEntryText;
      existing.journalEntryTotal = row.journalEntryTotal;
      existing.voucherRef = row.voucherRef;
    }
    existing.hasFile ||= row.hasFile;
  }
  return [...groups.values()];
}

export function DocumentsView({ detail = false }: { detail?: boolean } = {}) {
  const { slug = "", documentId: routeDocumentId } = useParams();
  const { can } = useCapabilities(slug);
  const { year, setYear } = useCompanyYear();
  const [params, setParams] = useSearchParams();
  const parsedDocumentId = Number(detail ? routeDocumentId : params.get("documentId"));
  const documentId = Number.isSafeInteger(parsedDocumentId) && parsedDocumentId > 0 ? parsedDocumentId : null;
  const state = useAsync<DocumentsPage>(
    async (signal) => {
      const [documents, fiscalYears] = await Promise.all([
        api.documents(slug, { signal }),
        api.fiscalYears(slug, { signal }),
      ]);
      return { documents, fiscalYears };
    },
    [slug],
  );
  const partyLinks = useAsync((signal) => api.documentPartyLinks(slug, undefined, { signal }), [slug]);
  // True while the document-intake modal (#213, slice 3) is open.
  const [ingesting, setIngesting] = useState(false);
  const [confirmingInternal, setConfirmingInternal] = useState(false);
  // #588: a deliberately small, reviewed flow. A person selects a document,
  // sees its recorded identity, then selects a visible canonical party. Names
  // only help find a candidate; the server still requires exact evidence.
  const [partyReviewId, setPartyReviewId] = useState<number | null>(null);
  const [partyCandidates, setPartyCandidates] = useState<PartyCandidate[]>([]);
  const [selectedPartyId, setSelectedPartyId] = useState("");
  const [partyRole, setPartyRole] = useState<"vendor" | "customer">("vendor");
  const [partyPlan, setPartyPlan] = useState<PartyPlan | null>(null);
  const [partyError, setPartyError] = useState<string | null>(null);
  const [partyBusy, setPartyBusy] = useState(false);
  const [partyConfirmed, setPartyConfirmed] = useState(false);
  const [reviewScope, setReviewScope] = useState<string | null>(null);
  const currentScope = `${slug}:${year ?? "default"}`;
  const partyOutcome = useMutationOutcome(() => { partyLinks.reload(); state.reload(); });
  const markPartySaved = useUnsavedChanges(partyReviewId !== null && selectedPartyId !== "" && reviewScope === currentScope);
  useEffect(() => {
    setReviewScope(currentScope);
    setPartyReviewId(null); setPartyPlan(null); setPartyConfirmed(false); setConfirmingInternal(false); setIngesting(false);
  }, [currentScope]);

  // --- #433 filter-bar params (client-side; reflected in URL) ---------------
  const q = params.get("q") ?? "";
  const fromDate = params.get("from") ?? "";
  const toDate = params.get("to") ?? "";
  const statusRaw = params.get("status") ?? "all";
  const typeRaw = params.get("type") ?? "all";
  const partyRaw = params.get("party") ?? "all";
  const status: StatusFilter = isStatusFilter(statusRaw) ? statusRaw : "all";
  const type: TypeFilter = isTypeFilter(typeRaw) ? typeRaw : "all";
  const party: PartyFilter = partyRaw === "linked" || partyRaw === "unlinked" || partyRaw === "internal_no_external_party" || partyRaw === "ambiguous" ? partyRaw : "all";

  // #433 — sorter for the date/amount columns. Default is the order returned
  // by the server (the document id), which is what the page used to do; only
  // after the owner clicks a column-header do we override that order.
  const sortKey = params.get("sort");
  const sort: { key: SortKey; dir: SortDir } | null = sortKey === "date" || sortKey === "amount" ? { key: sortKey, dir: params.get("dir") === "desc" ? "desc" : "asc" } : null;

  function setFilter(key: (typeof FILTER_PARAM_KEYS)[number], value: string) {
    const next = new URLSearchParams(params);
    if (value === "" || value === "all") {
      next.delete(key);
    } else {
      next.set(key, value);
    }
    next.delete("page");
    setParams(next, { replace: true });
  }

  function clearAllFilters() {
    const next = new URLSearchParams(params);
    for (const k of [...FILTER_PARAM_KEYS, "documentId", "page"]) next.delete(k);
    setParams(next, { replace: true });
  }

  const hasActiveFilter =
    q !== "" ||
    fromDate !== "" ||
    toDate !== "" ||
    status !== "all" ||
    type !== "all" ||
    party !== "all" ||
    documentId !== null;

  function toggleSort(key: SortKey) {
    const next = new URLSearchParams(params);
    if (sort?.key === key && sort.dir === "desc") { next.delete("sort"); next.delete("dir"); }
    else { next.set("sort", key); next.set("dir", sort?.key === key ? "desc" : "asc"); }
    next.delete("page");
    setParams(next, { replace: true });
  }

  function setSorting(key: string, direction?: string) {
    const next = new URLSearchParams(params);
    if (key === "default") { next.delete("sort"); next.delete("dir"); }
    else { next.set("sort", key); next.set("dir", direction ?? sort?.dir ?? "asc"); }
    next.delete("page");
    setParams(next, { replace: true });
  }

  function sortIndicator(key: SortKey): string {
    if (!sort || sort.key !== key) return "";
    return sort.dir === "asc" ? " ▲" : " ▼";
  }

  const allDocuments = useMemo(() => groupDocuments(state.data?.documents.documents ?? []), [state.data?.documents.documents]);
  const linkedIds = useMemo(() => new Set((partyLinks.data ?? []).filter((link) => link.linked === 1).map((link) => link.id)), [partyLinks.data]);
  const internalNoPartyIds = useMemo(() => new Set((partyLinks.data ?? []).filter((link) => link.resolution_state === "internal_no_external_party").map((link) => link.id)), [partyLinks.data]);

  const filteredDocuments = useMemo(() => {
    if (detail && documentId === null) return [];
    if (!hasActiveFilter) return allDocuments;
    const needle = q.trim().toLowerCase();
    return allDocuments.filter((doc) => {
      if (documentId !== null && doc.id !== documentId) return false;
      if (!detail && needle !== "" && !doc.associations.some((association) => documentMatchesText(association, needle))) return false;
      if (!detail && fromDate !== "") {
        if (!doc.invoiceDate || doc.invoiceDate < fromDate) return false;
      }
      if (!detail && toDate !== "") {
        if (!doc.invoiceDate || doc.invoiceDate > toDate) return false;
      }
      if (!detail && status === "booked" && doc.journalEntryNo === null) return false;
      if (!detail && status === "unbooked" && doc.journalEntryNo !== null) return false;
      if (!detail && type !== "all" && doc.documentType !== type) return false;
      if (!detail && party === "linked" && !linkedIds.has(doc.id)) return false;
      if (!detail && party === "unlinked" && (linkedIds.has(doc.id) || internalNoPartyIds.has(doc.id))) return false;
      if (!detail && party === "internal_no_external_party" && !internalNoPartyIds.has(doc.id)) return false;
      // Ambiguity is intentionally not inferred: it needs an explicit reviewed
      // plan conflict, so this view offers the bounded unlinked review queue.
      if (!detail && party === "ambiguous") return false;
      return true;
    });
  }, [allDocuments, hasActiveFilter, q, fromDate, toDate, status, type, party, documentId, linkedIds, internalNoPartyIds, detail]);

  const sortedDocuments = useMemo(() => {
    if (!sort) return filteredDocuments;
    const out = [...filteredDocuments];
    out.sort((a, b) => {
      let cmp = 0;
      if (sort.key === "date") {
        const ad = a.invoiceDate ?? "";
        const bd = b.invoiceDate ?? "";
        cmp = ad < bd ? -1 : ad > bd ? 1 : 0;
      } else {
        const av = documentAmount(a);
        const bv = documentAmount(b);
        if (av === null && bv === null) cmp = 0;
        else if (av === null) cmp = 1;
        else if (bv === null) cmp = -1;
        else cmp = av - bv;
      }
      return sort.dir === "asc" ? cmp : -cmp;
    });
    return out;
  }, [filteredDocuments, sort]);

  if (state.loading && !state.data) return <Loading label="Henter bilag…" />;
  if (state.error && !state.data)
    return <ErrorState message={state.error} onRetry={state.reload} />;

  const { documents: d, fiscalYears } = state.data!;
  const currency = d.company.currency || "DKK";
  const selectedYear =
    year ??
    fiscalYears.find((y) => y.source === "live")?.label ??
    fiscalYears[0]?.label ??
    String(new Date().getFullYear());
  // The intake action is hidden when the selected year is an archived
  // (pre-cut-over, read-only) year — there is no live ledger to ingest into.
  const selectedYearArchived =
    fiscalYears.find((y) => y.label === selectedYear)?.source === "archive";

  const totalCount = allDocuments.length;
  const bookedCount = allDocuments.filter((doc) => doc.journalEntryNo !== null).length;
  const pagination = listPagination(params, sortedDocuments.length);
  const visibleDocuments = detail ? sortedDocuments : sortedDocuments.slice(pagination.offset, pagination.offset + pagination.pageSize);
  const returnTo = listReturnTo(slug, "bilag", params.get("returnTo"), year);
  function setPageParam(key: "page" | "pageSize", value: number) {
    const next = new URLSearchParams(params); next.set(key, String(value));
    if (key === "pageSize") next.delete("page");
    setParams(next, { replace: true });
  }
  const matchCount = sortedDocuments.length;
  const reviewedDocument = partyReviewId === null || reviewScope !== currentScope ? null : allDocuments.find((doc) => doc.id === partyReviewId) ?? null;

  async function beginPartyReview(doc: DocumentRow) {
    if (partyOutcome.isBlocked()) return;
    setReviewScope(currentScope);
    setPartyReviewId(doc.id);
    setSelectedPartyId("");
    setPartyRole("vendor");
    setPartyPlan(null);
    setPartyError(null);
    setPartyConfirmed(false);
    setPartyBusy(true);
    try {
      // This is a membership-scoped search. It is not a match decision.
      const result = await api.searchCanonicalParties(slug, doc.supplierName ?? "");
      setPartyCandidates(result.rows);
    } catch (error) {
      setPartyCandidates([]);
      setPartyError(error instanceof Error ? error.message : "Kunne ikke hente synlige parter.");
    } finally {
      setPartyBusy(false);
    }
  }

  function identityInput(doc: DocumentRow) {
    return {
      documentId: doc.id,
      partyId: selectedPartyId,
      role: partyRole,
      jurisdiction: doc.supplierCountryCode ?? undefined,
      identifierKind: doc.supplierIdentifierKind ?? undefined,
      identifier: doc.supplierVatOrCvr ?? undefined,
    };
  }

  async function planPartyLink() {
    if (partyOutcome.isBlocked()) return;
    if (!reviewedDocument || !selectedPartyId) return;
    setPartyBusy(true);
    setPartyError(null);
    setPartyPlan(null);
    setPartyConfirmed(false);
    try {
      const result = await api.planDocumentPartyLink(slug, identityInput(reviewedDocument));
      if (!result.ok || !result.plan) {
        setPartyError(result.errors?.join(", ") ?? "Planen kunne ikke godkendes.");
        return;
      }
      setPartyPlan(result.plan as PartyPlan);
    } catch (error) {
      setPartyError(error instanceof Error ? error.message : "Kunne ikke planlægge koblingen.");
    } finally {
      setPartyBusy(false);
    }
  }

  async function applyPartyLink() {
    if (partyOutcome.isBlocked() || partyBusy || !reviewedDocument || !partyPlan || !partyConfirmed) return;
    setPartyBusy(true);
    setPartyError(null);
    try {
      const result = await api.applyDocumentPartyLink(slug, {
        ...identityInput(reviewedDocument),
        planHash: partyPlan.planHash,
        confirm: true,
        // A UI retry remains safe for this exact reviewed plan.
        idempotencyKey: `document-party-link-${reviewedDocument.id}-${partyPlan.planHash}`,
      }).catch(partyOutcome.reject);
      if (!result.ok) {
        setPartyError(result.errors?.join(", ") ?? "Koblingen kunne ikke gemmes.");
        return;
      }
      await Promise.all([partyLinks.reload(), state.reload()]);
      // Inspect after the write so the visible status/history is current.
      await api.documentPartyLinkHistory(slug, reviewedDocument.id);
      markPartySaved();
      setPartyReviewId(null);
    } catch (error) {
      setPartyError(error instanceof Error ? error.message : "Koblingen kunne ikke gemmes.");
    } finally {
      setPartyBusy(false);
    }
  }

  async function confirmInternalNoParty() {
    if (partyOutcome.isBlocked() || !reviewedDocument || reviewedDocument.documentType !== "internal_voucher") return;
    const result = await api.confirmInternalNoExternalParty(slug, {
      documentId: reviewedDocument.id,
      reason: "Bekræftet via bilagsgennemgang.",
      idempotencyKey: `internal-no-party-${reviewedDocument.id}`,
      confirm: true,
    }).catch(partyOutcome.reject);
    if (!result.ok) throw new Error(result.errors?.join(", ") ?? "Beslutningen kunne ikke gemmes.");
    await partyLinks.reload();
    setPartyReviewId(null);
  }

  return (
    <section className="statement">
      {state.error && <Banner kind="warning">Status kunne ikke opdateres: {state.error} De tidligere hentede bilag vises fortsat.</Banner>}
      {partyOutcome.feedback}
      <PageHeader title={detail ? `Bilag ${sortedDocuments[0]?.documentNo ?? documentId ?? ""}` : "Bilag"}
        description={`${d.company.name} · ${currency} · Alle bilag på tværs af regnskabsår`}
        actions={detail ? <ButtonLink className="btn secondary" to={returnTo}>Tilbage til bilag</ButtonLink> : !selectedYearArchived && can("company.documents.upload") ? <Button onClick={() => setIngesting(true)}>Indlæs bilag</Button> : undefined} />

      <CompanyNav
        slug={slug}
        years={fiscalYears}
        selectedYear={selectedYear}
        onYearChange={setYear}
      />

      {ingesting && (
        <DocumentIngestModal
          slug={slug}
          onIngested={state.reload}
          onClose={() => setIngesting(false)}
        />
      )}

      {confirmingInternal && reviewedDocument && !selectedYearArchived && can("company.master-data") && <ConfirmDialog
        title="Bekræft internt bilag uden ekstern part"
        body={<p>Bekræft at bilag {reviewedDocument.documentNo ?? reviewedDocument.id} bevidst ikke har en ekstern part. Beslutningen registreres i revisionssporet.</p>}
        confirmLabel="Bekræft ingen ekstern part"
        onConfirm={confirmInternalNoParty}
        onRefresh={() => { partyLinks.reload(); state.reload(); }}
        onClose={() => setConfirmingInternal(false)} />}

      {!detail && <FilterBar activeCount={[q, fromDate, toDate, status === "all" ? "" : status, type === "all" ? "" : type, party === "all" ? "" : party].filter(Boolean).length} onReset={clearAllFilters}>
        <label className="journal-filter-field journal-filter-field--search">
          <span className="muted">Søg</span>
          <Input
            type="search"
            value={q}
            placeholder="Søg på leverandør, bilagsnr., faktura eller posteringstekst…"
            onChange={(e) => setFilter("q", e.target.value)}
          />
        </label>
        <label className="journal-filter-field">
          <span className="muted">Fra</span>
          <Input
            type="date"
            value={fromDate}
            onChange={(e) => setFilter("from", e.target.value)}
          />
        </label>
        <label className="journal-filter-field">
          <span className="muted">Registreret modpart</span>
          <Select value={party} onChange={(e) => setFilter("party", e.target.value)}>
            <option value="all">Alle</option>
            <option value="linked">Koblet</option>
            <option value="unlinked">Mangler review</option>
            <option value="internal_no_external_party">Internt uden ekstern part</option>
            <option value="ambiguous">Tvetydige (kræver review)</option>
          </Select>
        </label>
        <label className="journal-filter-field">
          <span className="muted">Til</span>
          <Input
            type="date"
            value={toDate}
            onChange={(e) => setFilter("to", e.target.value)}
          />
        </label>
        <label className="journal-filter-field">
          <span className="muted">Status</span>
          <Select
            value={status}
            onChange={(e) => setFilter("status", e.target.value)}
          >
            <option value="all">Alle</option>
            <option value="booked">Bogført</option>
            <option value="unbooked">Kun ubehandlede</option>
          </Select>
        </label>
        <label className="journal-filter-field">
          <span className="muted">Type</span>
          <Select
            value={type}
            onChange={(e) => setFilter("type", e.target.value)}
          >
            <option value="all">Alle</option>
            <option value="purchase_sale">Køb/salg</option>
            <option value="cash_register_receipt">Kassebon</option>
            <option value="internal_voucher">Internt bilag</option>
          </Select>
        </label>

        <label className="journal-filter-field">Sortering<Select value={sort?.key ?? "default"} onChange={(event) => setSorting(event.target.value)}><option value="default">Nyeste indlæsning</option><option value="date">Fakturadato</option><option value="amount">Beløb</option></Select></label>
        {sort && <label className="journal-filter-field">Rækkefølge<Select value={sort.dir} onChange={(event) => setSorting(sort.key, event.target.value)}><option value="asc">Stigende</option><option value="desc">Faldende</option></Select></label>}
      </FilterBar>}

      <p className="statement-asof muted">
        {hasActiveFilter
          ? `${matchCount} af ${totalCount} bilag matcher`
          : `${totalCount} bilag`}
        {" · "}
        {bookedCount} bogført · {totalCount - bookedCount} ubehandlet
      </p>

      {reviewedDocument && !selectedYearArchived && can("company.master-data") && (
        <section className="card" aria-label="Gennemgå registreret modpart">
          <div className="page-head">
            <div>
              <h3>Gennemgå registreret modpart</h3>
              <p className="muted">Bilag {reviewedDocument.documentNo ?? `#${reviewedDocument.id}`}. Navne er kun søgehjælp — koblingen kræver den uforanderlige identitet nedenfor.</p>
            </div>
            <Button type="button" className="btn secondary" onClick={() => setPartyReviewId(null)}>Luk</Button>
          </div>
          <dl className="key-value-list">
            <div><dt>Identitet på bilaget</dt><dd>{reviewedDocument.supplierCountryCode ?? "—"} · {reviewedDocument.supplierIdentifierKind ?? "—"} · {reviewedDocument.supplierVatOrCvr ?? "Ingen verificerbar identifikator"}</dd></div>
            <div><dt>Bevis</dt><dd>Originalfilen og bogføringen ændres ikke. Planen binder bilagets hash til den valgte part.</dd></div>
          </dl>
          <div className="row-actions">
            <label>Rolle <Select value={partyRole} onChange={(event) => { setPartyRole(event.target.value as "vendor" | "customer"); setPartyPlan(null); setPartyConfirmed(false); }}><option value="vendor">Leverandør</option><option value="customer">Kunde</option></Select></label>
            <label>Vælg registreret modpart <Select aria-label="Vælg registreret modpart" value={selectedPartyId} onChange={(event) => { setSelectedPartyId(event.target.value); setPartyPlan(null); setPartyConfirmed(false); }} disabled={partyBusy || partyOutcome.blocked}><option value="">Vælg en synlig part…</option>{partyCandidates.map((candidate) => <option key={candidate.partyId} value={candidate.partyId}>{candidate.name}</option>)}</Select></label>
            <Button type="button" className="btn secondary" disabled={partyOutcome.blocked || partyBusy || !selectedPartyId || !reviewedDocument.supplierVatOrCvr} onClick={planPartyLink}>Vis plan</Button>
          </div>
          {!reviewedDocument.supplierVatOrCvr && <p className="flag warning">Bilaget har ingen verificerbar identifikator. Navne alene kan ikke kobles.</p>}
          {partyError && <p className="flag warning" role="alert">{partyError}</p>}
          {partyPlan && <div className="card"><p><strong>Plan klar</strong> — {partyPlan.partySnapshot?.name ?? "Valgt part"}; bevis: {partyPlan.evidence?.kind ?? "exact_identifier"}.</p><p className="muted">Plan-hash: <code>{partyPlan.planHash}</code></p><label><Input type="checkbox" disabled={partyBusy || partyOutcome.blocked} checked={partyConfirmed} onChange={(event) => setPartyConfirmed(event.target.checked)} /> Jeg har gennemgået planen og vil oprette den append-only kobling.</label><div className="row-actions"><Button type="button" className="btn" disabled={partyOutcome.blocked || partyBusy || !partyConfirmed} onClick={applyPartyLink}>Bekræft og anvend</Button></div></div>}
          {reviewedDocument.documentType === "internal_voucher" && <div className="card"><p className="muted">Interne bilag kan bekræftes uden ekstern part. Beslutningen er append-only og ændrer ikke bilag, moms eller journal.</p><Button type="button" className="btn secondary" disabled={partyBusy || partyOutcome.blocked} onClick={() => setConfirmingInternal(true)}>Bekræft ingen ekstern part</Button></div>}
        </section>
      )}

      {detail && sortedDocuments.length === 0 && <div className="card" role="status"><h2>Bilaget findes ikke</h2><p>Gå tilbage til bilagslisten og vælg et eksisterende bilag.</p></div>}
      <div className="card statement-card table-scroll">
        <table className="data statement-table daily-table" role="table">
          <thead role="rowgroup">
            <tr role="row">
              <th>Bilagsnr.</th>
              <th>Type</th>
              <th>Modpart / grundlag</th>
              <th>Faktura</th>
              <th>
                <Button
                  type="button"
                  className="th-sort"
                  onClick={() => toggleSort("date")}
                  aria-label="Sortér efter dato"
                >
                  Dato{sortIndicator("date")}
                </Button>
              </th>
              <th className="num">
                <Button
                  type="button"
                  className="th-sort"
                  onClick={() => toggleSort("amount")}
                  aria-label="Sortér efter beløb"
                >
                  Beløb inkl. moms{sortIndicator("amount")}
                </Button>
              </th>
              <th>Postering</th>
              <th>Bilagsfil</th>
            </tr>
          </thead>
          <tbody role="rowgroup">
            {sortedDocuments.length === 0 ? (
              <tr role="row">
                <td colSpan={8} className="empty-inline">
                  {hasActiveFilter
                    ? "Ingen bilag matcher filtrene."
                    : "Ingen bilag indlæst endnu."}
                </td>
              </tr>
            ) : (
              visibleDocuments.map((doc) => (
                <tr role="row" key={doc.id}>
                  <td role="cell" data-label="Bilag" className="account-no">
                    <Link to={workflowTo(slug, "bilag", String(doc.id), params, selectedYear)}>{doc.documentNo ?? `#${doc.id}`}</Link>
                  </td>
                  <td role="cell" data-label="Type">
                    {DOC_TYPE_LABELS[doc.documentType] ?? doc.documentType}
                  </td>
                  <td role="cell" data-label="Modpart / grundlag">
                    <div>
                      {doc.documentType === "internal_voucher"
                        ? `Bankpost #${doc.sourceBankTransactionId ?? "—"}`
                        : doc.supplierName ?? "—"}
                    </div>
                    {doc.documentType === "internal_voucher" && doc.accountingRationale ? (
                      <div className="muted">{doc.accountingRationale}</div>
                    ) : null}
                    {(doc.supplierCountryCode || doc.supplierIdentifierKind || doc.supplierIdentityStatus) && (
                      <div className="muted">
                        {doc.supplierCountryCode ?? "—"} · {doc.supplierIdentifierKind ?? "—"} · {doc.supplierIdentityStatus === "resolved" ? "Identitet bekræftet" : doc.supplierIdentityStatus ? "Identitet kræver gennemgang" : "—"}
                      </div>
                    )}
                    <div className="muted">{internalNoPartyIds.has(doc.id) ? "Bekræftet internt bilag uden ekstern part" : linkedIds.has(doc.id) ? "Registreret modpart koblet" : "Registreret modpart ikke koblet — gennemgå før anvendelse"}</div>
                    {!selectedYearArchived && can("company.master-data") && !linkedIds.has(doc.id) && !internalNoPartyIds.has(doc.id) && <Button type="button" className="btn small secondary" disabled={partyBusy || partyOutcome.blocked} onClick={() => beginPartyReview(doc)}>Gennemgå part</Button>}
                  </td>
                  <td role="cell" data-label="Faktura">{doc.invoiceNo ?? "—"}</td>
                  <td role="cell" data-label="Dato" className="entry-date">{doc.invoiceDate ?? "—"}</td>
                  <td role="cell" data-label="Beløb inkl. moms" className="num"><Amount value={documentAmount(doc)} currency={doc.amountIncVat !== null ? doc.currency : "DKK"} />{doc.amountIncVat === null && doc.associations.filter((entry) => entry.journalEntryNo).length > 1 && <span className="muted">Se de tilknyttede posteringer</span>}</td>
                  <td role="cell" data-label="Postering">
                    {doc.journalEntryNo ? doc.associations.filter((association) => association.journalEntryNo).map((association) => (
                      <div className="doc-posting" key={`${association.journalEntryId}-${association.voucherRef}`}>
                        <span className="flag ok">{association.journalEntryNo}{association.voucherRef ? ` · bilag ${association.voucherRef}` : ""}</span>
                        {association.journalEntryText && <span className="doc-posting-text muted">{association.journalEntryText}</span>}
                        {detail && <Amount value={association.journalEntryTotal} currency="DKK" />}
                      </div>
                    )) : ["purchase_sale", "cash_register_receipt", "internal_voucher"].includes(doc.documentType) ? <div className="doc-posting"><span className="flag warning">Ikke bogført</span>
                      {!selectedYearArchived && can("company.ledger.post") && <ButtonLink className="btn small" to={workflowTo(slug, "bilag", `${doc.id}/bogfoer`, params, selectedYear)}>Bogfør bilag</ButtonLink>}
                    </div> : <span className="muted">{doc.documentType === "issued_invoice_pdf" ? "PDF af udstedt faktura" : doc.documentType === "issued_invoice" ? "Bogføres fra Fakturaer" : "—"}</span>}

                  </td>
                  <td>
                    {doc.hasFile ? (
                      <a
                        href={api.documentFileUrl(slug, doc.id)}
                        target="_blank"
                        rel="noreferrer"
                      >
                        Åbn bilag
                      </a>
                    ) : (
                      <span className="muted">—</span>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      {!detail && <Pagination total={matchCount} {...pagination} onPageChange={(page) => setPageParam("page", page)} onPageSizeChange={(size) => setPageParam("pageSize", size)} />}
    </section>
  );
}

export function DocumentDetailView() { return <DocumentsView detail />; }

renderingAndEffects.viewTypeScript:
import { useEffect, useMemo, useState } from "react";
import { Link, useParams, useSearchParams } from "react-router-dom";
import { api } from "../lib/api";
import { useCapabilities } from "../lib/useCapabilities";
import { useAsync } from "../lib/useAsync";
import { useMutationOutcome } from "../lib/useMutationOutcome";
import { useUnsavedChanges } from "../lib/useUnsavedChanges";
import type {
  CompanyDocuments,
  DocumentRow,
  FiscalYearEntry,
} from "../lib/types";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { CompanyNav, useCompanyYear } from "../components/CompanyNav";
import { DocumentIngestModal } from "../components/DocumentIngestModal";
import { ConfirmDialog } from "../components/ConfirmDialog";
import { ButtonLink, Button, Input, Select, Amount, PageHeader, Pagination, FilterBar } from "../components/ui";
import { listPagination, listReturnTo, workflowTo } from "./workflow-navigation";

export type DocumentsPage = {
  documents: CompanyDocuments;
  fiscalYears: FiscalYearEntry[];
};

const DOC_TYPE_LABELS: Record<string, string> = {
  purchase_sale: "Køb/salg",
  cash_register_receipt: "Kassebon",
  internal_voucher: "Internt bilag",
  issued_invoice: "Udstedt faktura",
  issued_invoice_pdf: "PDF af udstedt faktura",
};

// #433 — the keys we own in the URL. Listed once so "Ryd filtre" can clear
// them all without touching other params (e.g. `?year=`).
const FILTER_PARAM_KEYS = ["q", "from", "to", "status", "type", "party"] as const;

type StatusFilter = "all" | "booked" | "unbooked";
type TypeFilter = "all" | "purchase_sale" | "cash_register_receipt" | "internal_voucher";

type SortKey = "date" | "amount";
type SortDir = "asc" | "desc";
type PartyFilter = "all" | "linked" | "unlinked" | "internal_no_external_party" | "ambiguous";
type PartyCandidate = { partyId: string; name: string };
type PartyPlan = {
  planHash: string;
  documentSha256?: string;
  documentPayloadSha256?: string;
  evidence?: { kind?: string; jurisdiction?: string; identifierKind?: string; identifier?: string };
  partySnapshot?: { name?: string };
};

function isStatusFilter(v: string): v is StatusFilter {
  return v === "all" || v === "booked" || v === "unbooked";
}
function isTypeFilter(v: string): v is TypeFilter {
  return (
    v === "all" ||
    v === "purchase_sale" ||
    v === "cash_register_receipt" ||
    v === "internal_voucher"
  );
}

export function documentAmount(doc: DocumentRow & { associations?: DocumentRow[] }): number | null {
  if (doc.amountIncVat !== null) return doc.amountIncVat;
  if (doc.associations && doc.associations.filter((entry) => entry.journalEntryNo).length > 1) return null;
  if (doc.journalEntryTotal !== null) return doc.journalEntryTotal;
  return null;
}

function documentMatchesText(doc: DocumentRow, needle: string): boolean {
  if (doc.supplierName && doc.supplierName.toLowerCase().includes(needle))
    return true;
  if (doc.documentNo && doc.documentNo.toLowerCase().includes(needle))
    return true;
  if (doc.invoiceNo && doc.invoiceNo.toLowerCase().includes(needle))
    return true;
  if (
    doc.accountingRationale &&
    doc.accountingRationale.toLowerCase().includes(needle)
  )
    return true;
  if (
    doc.sourceBankTransactionId !== null &&
    String(doc.sourceBankTransactionId).includes(needle)
  )
    return true;
  if (
    doc.journalEntryText &&
    doc.journalEntryText.toLowerCase().includes(needle)
  )
    return true;
  if (
    doc.journalEntryNo &&
    doc.journalEntryNo.toLowerCase().includes(needle)
  )
    return true;
  return false;
}

export type GroupedDocument = DocumentRow & { associations: DocumentRow[] };

/** One row per original document; each linked posting remains available. */
export function groupDocuments(rows: DocumentRow[]): GroupedDocument[] {
  const groups = new Map<number, GroupedDocument>();
  for (const row of rows) {
    const existing = groups.get(row.id);
    if (!existing) {
      groups.set(row.id, { ...row, associations: [row] });
      continue;
    }
    if (!existing.associations.some((entry) => entry.journalEntryId === row.journalEntryId && entry.journalEntryNo === row.journalEntryNo && entry.voucherRef === row.voucherRef)) existing.associations.push(row);
    // Representative posting identifies booked documents without summing relations.
    if (!existing.journalEntryNo && row.journalEntryNo) {
      existing.journalEntryNo = row.journalEntryNo;
      existing.journalEntryId = row.journalEntryId;
      existing.journalEntryText = row.journalEntryText;
      existing.journalEntryTotal = row.journalEntryTotal;
      existing.voucherRef = row.voucherRef;
    }
    existing.hasFile ||= row.hasFile;
  }
  return [...groups.values()];
}

export function DocumentsView({ detail = false }: { detail?: boolean } = {}) {
  const { slug = "", documentId: routeDocumentId } = useParams();
  const { can } = useCapabilities(slug);
  const { year, setYear } = useCompanyYear();
  const [params, setParams] = useSearchParams();
  const parsedDocumentId = Number(detail ? routeDocumentId : params.get("documentId"));
  const documentId = Number.isSafeInteger(parsedDocumentId) && parsedDocumentId > 0 ? parsedDocumentId : null;
  const state = useAsync<DocumentsPage>(
    async (signal) => {
      const [documents, fiscalYears] = await Promise.all([
        api.documents(slug, { signal }),
        api.fiscalYears(slug, { signal }),
      ]);
      return { documents, fiscalYears };
    },
    [slug],
  );
  const partyLinks = useAsync((signal) => api.documentPartyLinks(slug, undefined, { signal }), [slug]);
  // True while the document-intake modal (#213, slice 3) is open.
  const [ingesting, setIngesting] = useState(false);
  const [confirmingInternal, setConfirmingInternal] = useState(false);
  // #588: a deliberately small, reviewed flow. A person selects a document,
  // sees its recorded identity, then selects a visible canonical party. Names
  // only help find a candidate; the server still requires exact evidence.
  const [partyReviewId, setPartyReviewId] = useState<number | null>(null);
  const [partyCandidates, setPartyCandidates] = useState<PartyCandidate[]>([]);
  const [selectedPartyId, setSelectedPartyId] = useState("");
  const [partyRole, setPartyRole] = useState<"vendor" | "customer">("vendor");
  const [partyPlan, setPartyPlan] = useState<PartyPlan | null>(null);
  const [partyError, setPartyError] = useState<string | null>(null);
  const [partyBusy, setPartyBusy] = useState(false);
  const [partyConfirmed, setPartyConfirmed] = useState(false);
  const [reviewScope, setReviewScope] = useState<string | null>(null);
  const currentScope = `${slug}:${year ?? "default"}`;
  const partyOutcome = useMutationOutcome(() => { partyLinks.reload(); state.reload(); });
  const markPartySaved = useUnsavedChanges(partyReviewId !== null && selectedPartyId !== "" && reviewScope === currentScope);
  useEffect(() => {
    setReviewScope(currentScope);
    setPartyReviewId(null); setPartyPlan(null); setPartyConfirmed(false); setConfirmingInternal(false); setIngesting(false);
  }, [currentScope]);

  // --- #433 filter-bar params (client-side; reflected in URL) ---------------
  const q = params.get("q") ?? "";
  const fromDate = params.get("from") ?? "";
  const toDate = params.get("to") ?? "";
  const statusRaw = params.get("status") ?? "all";
  const typeRaw = params.get("type") ?? "all";
  const partyRaw = params.get("party") ?? "all";
  const status: StatusFilter = isStatusFilter(statusRaw) ? statusRaw : "all";
  const type: TypeFilter = isTypeFilter(typeRaw) ? typeRaw : "all";
  const party: PartyFilter = partyRaw === "linked" || partyRaw === "unlinked" || partyRaw === "internal_no_external_party" || partyRaw === "ambiguous" ? partyRaw : "all";

  // #433 — sorter for the date/amount columns. Default is the order returned
  // by the server (the document id), which is what the page used to do; only
  // after the owner clicks a column-header do we override that order.
  const sortKey = params.get("sort");
  const sort: { key: SortKey; dir: SortDir } | null = sortKey === "date" || sortKey === "amount" ? { key: sortKey, dir: params.get("dir") === "desc" ? "desc" : "asc" } : null;

  function setFilter(key: (typeof FILTER_PARAM_KEYS)[number], value: string) {
    const next = new URLSearchParams(params);
    if (value === "" || value === "all") {
      next.delete(key);
    } else {
      next.set(key, value);
    }
    next.delete("page");
    setParams(next, { replace: true });
  }

  function clearAllFilters() {
    const next = new URLSearchParams(params);
    for (const k of [...FILTER_PARAM_KEYS, "documentId", "page"]) next.delete(k);
    setParams(next, { replace: true });
  }

  const hasActiveFilter =
    q !== "" ||
    fromDate !== "" ||
    toDate !== "" ||
    status !== "all" ||
    type !== "all" ||
    party !== "all" ||
    documentId !== null;

  function toggleSort(key: SortKey) {
    const next = new URLSearchParams(params);
    if (sort?.key === key && sort.dir === "desc") { next.delete("sort"); next.delete("dir"); }
    else { next.set("sort", key); next.set("dir", sort?.key === key ? "desc" : "asc"); }
    next.delete("page");
    setParams(next, { replace: true });
  }

  function setSorting(key: string, direction?: string) {
    const next = new URLSearchParams(params);
    if (key === "default") { next.delete("sort"); next.delete("dir"); }
    else { next.set("sort", key); next.set("dir", direction ?? sort?.dir ?? "asc"); }
    next.delete("page");
    setParams(next, { replace: true });
  }

  function sortIndicator(key: SortKey): string {
    if (!sort || sort.key !== key) return "";
    return sort.dir === "asc" ? " ▲" : " ▼";
  }

  const allDocuments = useMemo(() => groupDocuments(state.data?.documents.documents ?? []), [state.data?.documents.documents]);
  const linkedIds = useMemo(() => new Set((partyLinks.data ?? []).filter((link) => link.linked === 1).map((link) => link.id)), [partyLinks.data]);
  const internalNoPartyIds = useMemo(() => new Set((partyLinks.data ?? []).filter((link) => link.resolution_state === "internal_no_external_party").map((link) => link.id)), [partyLinks.data]);

  const filteredDocuments = useMemo(() => {
    if (detail && documentId === null) return [];
    if (!hasActiveFilter) return allDocuments;
    const needle = q.trim().toLowerCase();
    return allDocuments.filter((doc) => {
      if (documentId !== null && doc.id !== documentId) return false;
      if (!detail && needle !== "" && !doc.associations.some((association) => documentMatchesText(association, needle))) return false;
      if (!detail && fromDate !== "") {
        if (!doc.invoiceDate || doc.invoiceDate < fromDate) return false;
      }
      if (!detail && toDate !== "") {
        if (!doc.invoiceDate || doc.invoiceDate > toDate) return false;
      }
      if (!detail && status === "booked" && doc.journalEntryNo === null) return false;
      if (!detail && status === "unbooked" && doc.journalEntryNo !== null) return false;
      if (!detail && type !== "all" && doc.documentType !== type) return false;
      if (!detail && party === "linked" && !linkedIds.has(doc.id)) return false;
      if (!detail && party === "unlinked" && (linkedIds.has(doc.id) || internalNoPartyIds.has(doc.id))) return false;
      if (!detail && party === "internal_no_external_party" && !internalNoPartyIds.has(doc.id)) return false;
      // Ambiguity is intentionally not inferred: it needs an explicit reviewed
      // plan conflict, so this view offers the bounded unlinked review queue.
      if (!detail && party === "ambiguous") return false;
      return true;
    });
  }, [allDocuments, hasActiveFilter, q, fromDate, toDate, status, type, party, documentId, linkedIds, internalNoPartyIds, detail]);

  const sortedDocuments = useMemo(() => {
    if (!sort) return filteredDocuments;
    const out = [...filteredDocuments];
    out.sort((a, b) => {
      let cmp = 0;
      if (sort.key === "date") {
        const ad = a.invoiceDate ?? "";
        const bd = b.invoiceDate ?? "";
        cmp = ad < bd ? -1 : ad > bd ? 1 : 0;
      } else {
        const av = documentAmount(a);
        const bv = documentAmount(b);
        if (av === null && bv === null) cmp = 0;
        else if (av === null) cmp = 1;
        else if (bv === null) cmp = -1;
        else cmp = av - bv;
      }
      return sort.dir === "asc" ? cmp : -cmp;
    });
    return out;
  }, [filteredDocuments, sort]);

  if (state.loading && !state.data) return <Loading label="Henter bilag…" />;
  if (state.error && !state.data)
    return <ErrorState message={state.error} onRetry={state.reload} />;

  const { documents: d, fiscalYears } = state.data!;
  const currency = d.company.currency || "DKK";
  const selectedYear =
    year ??
    fiscalYears.find((y) => y.source === "live")?.label ??
    fiscalYears[0]?.label ??
    String(new Date().getFullYear());
  // The intake action is hidden when the selected year is an archived
  // (pre-cut-over, read-only) year — there is no live ledger to ingest into.
  const selectedYearArchived =
    fiscalYears.find((y) => y.label === selectedYear)?.source === "archive";

  const totalCount = allDocuments.length;
  const bookedCount = allDocuments.filter((doc) => doc.journalEntryNo !== null).length;
  const pagination = listPagination(params, sortedDocuments.length);
  const visibleDocuments = detail ? sortedDocuments : sortedDocuments.slice(pagination.offset, pagination.offset + pagination.pageSize);
  const returnTo = listReturnTo(slug, "bilag", params.get("returnTo"), year);
  function setPageParam(key: "page" | "pageSize", value: number) {
    const next = new URLSearchParams(params); next.set(key, String(value));
    if (key === "pageSize") next.delete("page");
    setParams(next, { replace: true });
  }
  const matchCount = sortedDocuments.length;
  const reviewedDocument = partyReviewId === null || reviewScope !== currentScope ? null : allDocuments.find((doc) => doc.id === partyReviewId) ?? null;

  async function beginPartyReview(doc: DocumentRow) {
    if (partyOutcome.isBlocked()) return;
    setReviewScope(currentScope);
    setPartyReviewId(doc.id);
    setSelectedPartyId("");
    setPartyRole("vendor");
    setPartyPlan(null);
    setPartyError(null);
    setPartyConfirmed(false);
    setPartyBusy(true);
    try {
      // This is a membership-scoped search. It is not a match decision.
      const result = await api.searchCanonicalParties(slug, doc.supplierName ?? "");
      setPartyCandidates(result.rows);
    } catch (error) {
      setPartyCandidates([]);
      setPartyError(error instanceof Error ? error.message : "Kunne ikke hente synlige parter.");
    } finally {
      setPartyBusy(false);
    }
  }

  function identityInput(doc: DocumentRow) {
    return {
      documentId: doc.id,
      partyId: selectedPartyId,
      role: partyRole,
      jurisdiction: doc.supplierCountryCode ?? undefined,
      identifierKind: doc.supplierIdentifierKind ?? undefined,
      identifier: doc.supplierVatOrCvr ?? undefined,
    };
  }

  async function planPartyLink() {
    if (partyOutcome.isBlocked()) return;
    if (!reviewedDocument || !selectedPartyId) return;
    setPartyBusy(true);
    setPartyError(null);
    setPartyPlan(null);
    setPartyConfirmed(false);
    try {
      const result = await api.planDocumentPartyLink(slug, identityInput(reviewedDocument));
      if (!result.ok || !result.plan) {
        setPartyError(result.errors?.join(", ") ?? "Planen kunne ikke godkendes.");
        return;
      }
      setPartyPlan(result.plan as PartyPlan);
    } catch (error) {
      setPartyError(error instanceof Error ? error.message : "Kunne ikke planlægge koblingen.");
    } finally {
      setPartyBusy(false);
    }
  }

  async function applyPartyLink() {
    if (partyOutcome.isBlocked() || partyBusy || !reviewedDocument || !partyPlan || !partyConfirmed) return;
    setPartyBusy(true);
    setPartyError(null);
    try {
      const result = await api.applyDocumentPartyLink(slug, {
        ...identityInput(reviewedDocument),
        planHash: partyPlan.planHash,
        confirm: true,
        // A UI retry remains safe for this exact reviewed plan.
        idempotencyKey: `document-party-link-${reviewedDocument.id}-${partyPlan.planHash}`,
      }).catch(partyOutcome.reject);
      if (!result.ok) {
        setPartyError(result.errors?.join(", ") ?? "Koblingen kunne ikke gemmes.");
        return;
      }
      await Promise.all([partyLinks.reload(), state.reload()]);
      // Inspect after the write so the visible status/history is current.
      await api.documentPartyLinkHistory(slug, reviewedDocument.id);
      markPartySaved();
      setPartyReviewId(null);
    } catch (error) {
      setPartyError(error instanceof Error ? error.message : "Koblingen kunne ikke gemmes.");
    } finally {
      setPartyBusy(false);
    }
  }

  async function confirmInternalNoParty() {
    if (partyOutcome.isBlocked() || !reviewedDocument || reviewedDocument.documentType !== "internal_voucher") return;
    const result = await api.confirmInternalNoExternalParty(slug, {
      documentId: reviewedDocument.id,
      reason: "Bekræftet via bilagsgennemgang.",
      idempotencyKey: `internal-no-party-${reviewedDocument.id}`,
      confirm: true,
    }).catch(partyOutcome.reject);
    if (!result.ok) throw new Error(result.errors?.join(", ") ?? "Beslutningen kunne ikke gemmes.");
    await partyLinks.reload();
    setPartyReviewId(null);
  }

  return (
    <section className="statement">
      {state.error && <Banner kind="warning">Status kunne ikke opdateres: {state.error} De tidligere hentede bilag vises fortsat.</Banner>}
      {partyOutcome.feedback}
      <PageHeader title={detail ? `Bilag ${sortedDocuments[0]?.documentNo ?? documentId ?? ""}` : "Bilag"}
        description={`${d.company.name} · ${currency} · Alle bilag på tværs af regnskabsår`}
        actions={detail ? <ButtonLink className="btn secondary" to={returnTo}>Tilbage til bilag</ButtonLink> : !selectedYearArchived && can("company.documents.upload") ? <Button onClick={() => setIngesting(true)}>Indlæs bilag</Button> : undefined} />

      <CompanyNav
        slug={slug}
        years={fiscalYears}
        selectedYear={selectedYear}
        onYearChange={setYear}
      />

      {ingesting && (
        <DocumentIngestModal
          slug={slug}
          onIngested={state.reload}
          onClose={() => setIngesting(false)}
        />
      )}

      {confirmingInternal && reviewedDocument && !selectedYearArchived && can("company.master-data") && <ConfirmDialog
        title="Bekræft internt bilag uden ekstern part"
        body={<p>Bekræft at bilag {reviewedDocument.documentNo ?? reviewedDocument.id} bevidst ikke har en ekstern part. Beslutningen registreres i revisionssporet.</p>}
        confirmLabel="Bekræft ingen ekstern part"
        onConfirm={confirmInternalNoParty}
        onRefresh={() => { partyLinks.reload(); state.reload(); }}
        onClose={() => setConfirmingInternal(false)} />}

      {!detail && <FilterBar activeCount={[q, fromDate, toDate, status === "all" ? "" : status, type === "all" ? "" : type, party === "all" ? "" : party].filter(Boolean).length} onReset={clearAllFilters}>
        <label className="journal-filter-field journal-filter-field--search">
          <span className="muted">Søg</span>
          <Input
            type="search"
            value={q}
            placeholder="Søg på leverandør, bilagsnr., faktura eller posteringstekst…"
            onChange={(e) => setFilter("q", e.target.value)}
          />
        </label>
        <label className="journal-filter-field">
          <span className="muted">Fra</span>
          <Input
            type="date"
            value={fromDate}
            onChange={(e) => setFilter("from", e.target.value)}
          />
        </label>
        <label className="journal-filter-field">
          <span className="muted">Registreret modpart</span>
          <Select value={party} onChange={(e) => setFilter("party", e.target.value)}>
            <option value="all">Alle</option>
            <option value="linked">Koblet</option>
            <option value="unlinked">Mangler review</option>
            <option value="internal_no_external_party">Internt uden ekstern part</option>
            <option value="ambiguous">Tvetydige (kræver review)</option>
          </Select>
        </label>
        <label className="journal-filter-field">
          <span className="muted">Til</span>
          <Input
            type="date"
            value={toDate}
            onChange={(e) => setFilter("to", e.target.value)}
          />
        </label>
        <label className="journal-filter-field">
          <span className="muted">Status</span>
          <Select
            value={status}
            onChange={(e) => setFilter("status", e.target.value)}
          >
            <option value="all">Alle</option>
            <option value="booked">Bogført</option>
            <option value="unbooked">Kun ubehandlede</option>
          </Select>
        </label>
        <label className="journal-filter-field">
          <span className="muted">Type</span>
          <Select
            value={type}
            onChange={(e) => setFilter("type", e.target.value)}
          >
            <option value="all">Alle</option>
            <option value="purchase_sale">Køb/salg</option>
            <option value="cash_register_receipt">Kassebon</option>
            <option value="internal_voucher">Internt bilag</option>
          </Select>
        </label>

        <label className="journal-filter-field">Sortering<Select value={sort?.key ?? "default"} onChange={(event) => setSorting(event.target.value)}><option value="default">Nyeste indlæsning</option><option value="date">Fakturadato</option><option value="amount">Beløb</option></Select></label>
        {sort && <label className="journal-filter-field">Rækkefølge<Select value={sort.dir} onChange={(event) => setSorting(sort.key, event.target.value)}><option value="asc">Stigende</option><option value="desc">Faldende</option></Select></label>}
      </FilterBar>}

      <p className="statement-asof muted">
        {hasActiveFilter
          ? `${matchCount} af ${totalCount} bilag matcher`
          : `${totalCount} bilag`}
        {" · "}
        {bookedCount} bogført · {totalCount - bookedCount} ubehandlet
      </p>

      {reviewedDocument && !selectedYearArchived && can("company.master-data") && (
        <section className="card" aria-label="Gennemgå registreret modpart">
          <div className="page-head">
            <div>
              <h3>Gennemgå registreret modpart</h3>
              <p className="muted">Bilag {reviewedDocument.documentNo ?? `#${reviewedDocument.id}`}. Navne er kun søgehjælp — koblingen kræver den uforanderlige identitet nedenfor.</p>
            </div>
            <Button type="button" className="btn secondary" onClick={() => setPartyReviewId(null)}>Luk</Button>
          </div>
          <dl className="key-value-list">
            <div><dt>Identitet på bilaget</dt><dd>{reviewedDocument.supplierCountryCode ?? "—"} · {reviewedDocument.supplierIdentifierKind ?? "—"} · {reviewedDocument.supplierVatOrCvr ?? "Ingen verificerbar identifikator"}</dd></div>
            <div><dt>Bevis</dt><dd>Originalfilen og bogføringen ændres ikke. Planen binder bilagets hash til den valgte part.</dd></div>
          </dl>
          <div className="row-actions">
            <label>Rolle <Select value={partyRole} onChange={(event) => { setPartyRole(event.target.value as "vendor" | "customer"); setPartyPlan(null); setPartyConfirmed(false); }}><option value="vendor">Leverandør</option><option value="customer">Kunde</option></Select></label>
            <label>Vælg registreret modpart <Select aria-label="Vælg registreret modpart" value={selectedPartyId} onChange={(event) => { setSelectedPartyId(event.target.value); setPartyPlan(null); setPartyConfirmed(false); }} disabled={partyBusy || partyOutcome.blocked}><option value="">Vælg en synlig part…</option>{partyCandidates.map((candidate) => <option key={candidate.partyId} value={candidate.partyId}>{candidate.name}</option>)}</Select></label>
            <Button type="button" className="btn secondary" disabled={partyOutcome.blocked || partyBusy || !selectedPartyId || !reviewedDocument.supplierVatOrCvr} onClick={planPartyLink}>Vis plan</Button>
          </div>
          {!reviewedDocument.supplierVatOrCvr && <p className="flag warning">Bilaget har ingen verificerbar identifikator. Navne alene kan ikke kobles.</p>}
          {partyError && <p className="flag warning" role="alert">{partyError}</p>}
          {partyPlan && <div className="card"><p><strong>Plan klar</strong> — {partyPlan.partySnapshot?.name ?? "Valgt part"}; bevis: {partyPlan.evidence?.kind ?? "exact_identifier"}.</p><p className="muted">Plan-hash: <code>{partyPlan.planHash}</code></p><label><Input type="checkbox" disabled={partyBusy || partyOutcome.blocked} checked={partyConfirmed} onChange={(event) => setPartyConfirmed(event.target.checked)} /> Jeg har gennemgået planen og vil oprette den append-only kobling.</label><div className="row-actions"><Button type="button" className="btn" disabled={partyOutcome.blocked || partyBusy || !partyConfirmed} onClick={applyPartyLink}>Bekræft og anvend</Button></div></div>}
          {reviewedDocument.documentType === "internal_voucher" && <div className="card"><p className="muted">Interne bilag kan bekræftes uden ekstern part. Beslutningen er append-only og ændrer ikke bilag, moms eller journal.</p><Button type="button" className="btn secondary" disabled={partyBusy || partyOutcome.blocked} onClick={() => setConfirmingInternal(true)}>Bekræft ingen ekstern part</Button></div>}
        </section>
      )}

      {detail && sortedDocuments.length === 0 && <div className="card" role="status"><h2>Bilaget findes ikke</h2><p>Gå tilbage til bilagslisten og vælg et eksisterende bilag.</p></div>}
      <div className="card statement-card table-scroll">
        <table className="data statement-table daily-table" role="table">
          <thead role="rowgroup">
            <tr role="row">
              <th>Bilagsnr.</th>
              <th>Type</th>
              <th>Modpart / grundlag</th>
              <th>Faktura</th>
              <th>
                <Button
                  type="button"
                  className="th-sort"
                  onClick={() => toggleSort("date")}
                  aria-label="Sortér efter dato"
                >
                  Dato{sortIndicator("date")}
                </Button>
              </th>
              <th className="num">
                <Button
                  type="button"
                  className="th-sort"
                  onClick={() => toggleSort("amount")}
                  aria-label="Sortér efter beløb"
                >
                  Beløb inkl. moms{sortIndicator("amount")}
                </Button>
              </th>
              <th>Postering</th>
              <th>Bilagsfil</th>
            </tr>
          </thead>
          <tbody role="rowgroup">
            {sortedDocuments.length === 0 ? (
              <tr role="row">
                <td colSpan={8} className="empty-inline">
                  {hasActiveFilter
                    ? "Ingen bilag matcher filtrene."
                    : "Ingen bilag indlæst endnu."}
                </td>
              </tr>
            ) : (
              visibleDocuments.map((doc) => (
                <tr role="row" key={doc.id}>
                  <td role="cell" data-label="Bilag" className="account-no">
                    <Link to={workflowTo(slug, "bilag", String(doc.id), params, selectedYear)}>{doc.documentNo ?? `#${doc.id}`}</Link>
                  </td>
                  <td role="cell" data-label="Type">
                    {DOC_TYPE_LABELS[doc.documentType] ?? doc.documentType}
                  </td>
                  <td role="cell" data-label="Modpart / grundlag">
                    <div>
                      {doc.documentType === "internal_voucher"
                        ? `Bankpost #${doc.sourceBankTransactionId ?? "—"}`
                        : doc.supplierName ?? "—"}
                    </div>
                    {doc.documentType === "internal_voucher" && doc.accountingRationale ? (
                      <div className="muted">{doc.accountingRationale}</div>
                    ) : null}
                    {(doc.supplierCountryCode || doc.supplierIdentifierKind || doc.supplierIdentityStatus) && (
                      <div className="muted">
                        {doc.supplierCountryCode ?? "—"} · {doc.supplierIdentifierKind ?? "—"} · {doc.supplierIdentityStatus === "resolved" ? "Identitet bekræftet" : doc.supplierIdentityStatus ? "Identitet kræver gennemgang" : "—"}
                      </div>
                    )}
                    <div className="muted">{internalNoPartyIds.has(doc.id) ? "Bekræftet internt bilag uden ekstern part" : linkedIds.has(doc.id) ? "Registreret modpart koblet" : "Registreret modpart ikke koblet — gennemgå før anvendelse"}</div>
                    {!selectedYearArchived && can("company.master-data") && !linkedIds.has(doc.id) && !internalNoPartyIds.has(doc.id) && <Button type="button" className="btn small secondary" disabled={partyBusy || partyOutcome.blocked} onClick={() => beginPartyReview(doc)}>Gennemgå part</Button>}
                  </td>
                  <td role="cell" data-label="Faktura">{doc.invoiceNo ?? "—"}</td>
                  <td role="cell" data-label="Dato" className="entry-date">{doc.invoiceDate ?? "—"}</td>
                  <td role="cell" data-label="Beløb inkl. moms" className="num"><Amount value={documentAmount(doc)} currency={doc.amountIncVat !== null ? doc.currency : "DKK"} />{doc.amountIncVat === null && doc.associations.filter((entry) => entry.journalEntryNo).length > 1 && <span className="muted">Se de tilknyttede posteringer</span>}</td>
                  <td role="cell" data-label="Postering">
                    {doc.journalEntryNo ? doc.associations.filter((association) => association.journalEntryNo).map((association) => (
                      <div className="doc-posting" key={`${association.journalEntryId}-${association.voucherRef}`}>
                        <span className="flag ok">{association.journalEntryNo}{association.voucherRef ? ` · bilag ${association.voucherRef}` : ""}</span>
                        {association.journalEntryText && <span className="doc-posting-text muted">{association.journalEntryText}</span>}
                        {detail && <Amount value={association.journalEntryTotal} currency="DKK" />}
                      </div>
                    )) : ["purchase_sale", "cash_register_receipt", "internal_voucher"].includes(doc.documentType) ? <div className="doc-posting"><span className="flag warning">Ikke bogført</span>
                      {!selectedYearArchived && can("company.ledger.post") && <ButtonLink className="btn small" to={workflowTo(slug, "bilag", `${doc.id}/bogfoer`, params, selectedYear)}>Bogfør bilag</ButtonLink>}
                    </div> : <span className="muted">{doc.documentType === "issued_invoice_pdf" ? "PDF af udstedt faktura" : doc.documentType === "issued_invoice" ? "Bogføres fra Fakturaer" : "—"}</span>}

                  </td>
                  <td>
                    {doc.hasFile ? (
                      <a
                        href={api.documentFileUrl(slug, doc.id)}
                        target="_blank"
                        rel="noreferrer"
                      >
                        Åbn bilag
                      </a>
                    ) : (
                      <span className="muted">—</span>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      {!detail && <Pagination total={matchCount} {...pagination} onPageChange={(page) => setPageParam("page", page)} onPageSizeChange={(size) => setPageParam("pageSize", size)} />}
    </section>
  );
}

export function DocumentDetailView() { return <DocumentsView detail />; }

definition.viewSpecificRefusals:
import { useEffect, useMemo, useState } from "react";
import { Link, useParams, useSearchParams } from "react-router-dom";
import { api } from "../lib/api";
import { useCapabilities } from "../lib/useCapabilities";
import { useAsync } from "../lib/useAsync";
import { useMutationOutcome } from "../lib/useMutationOutcome";
import { useUnsavedChanges } from "../lib/useUnsavedChanges";
import type {
  CompanyDocuments,
  DocumentRow,
  FiscalYearEntry,
} from "../lib/types";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { CompanyNav, useCompanyYear } from "../components/CompanyNav";
import { DocumentIngestModal } from "../components/DocumentIngestModal";
import { ConfirmDialog } from "../components/ConfirmDialog";
import { ButtonLink, Button, Input, Select, Amount, PageHeader, Pagination, FilterBar } from "../components/ui";
import { listPagination, listReturnTo, workflowTo } from "./workflow-navigation";

export type DocumentsPage = {
  documents: CompanyDocuments;
  fiscalYears: FiscalYearEntry[];
};

const DOC_TYPE_LABELS: Record<string, string> = {
  purchase_sale: "Køb/salg",
  cash_register_receipt: "Kassebon",
  internal_voucher: "Internt bilag",
  issued_invoice: "Udstedt faktura",
  issued_invoice_pdf: "PDF af udstedt faktura",
};

// #433 — the keys we own in the URL. Listed once so "Ryd filtre" can clear
// them all without touching other params (e.g. `?year=`).
const FILTER_PARAM_KEYS = ["q", "from", "to", "status", "type", "party"] as const;

type StatusFilter = "all" | "booked" | "unbooked";
type TypeFilter = "all" | "purchase_sale" | "cash_register_receipt" | "internal_voucher";

type SortKey = "date" | "amount";
type SortDir = "asc" | "desc";
type PartyFilter = "all" | "linked" | "unlinked" | "internal_no_external_party" | "ambiguous";
type PartyCandidate = { partyId: string; name: string };
type PartyPlan = {
  planHash: string;
  documentSha256?: string;
  documentPayloadSha256?: string;
  evidence?: { kind?: string; jurisdiction?: string; identifierKind?: string; identifier?: string };
  partySnapshot?: { name?: string };
};

function isStatusFilter(v: string): v is StatusFilter {
  return v === "all" || v === "booked" || v === "unbooked";
}
function isTypeFilter(v: string): v is TypeFilter {
  return (
    v === "all" ||
    v === "purchase_sale" ||
    v === "cash_register_receipt" ||
    v === "internal_voucher"
  );
}

export function documentAmount(doc: DocumentRow & { associations?: DocumentRow[] }): number | null {
  if (doc.amountIncVat !== null) return doc.amountIncVat;
  if (doc.associations && doc.associations.filter((entry) => entry.journalEntryNo).length > 1) return null;
  if (doc.journalEntryTotal !== null) return doc.journalEntryTotal;
  return null;
}

function documentMatchesText(doc: DocumentRow, needle: string): boolean {
  if (doc.supplierName && doc.supplierName.toLowerCase().includes(needle))
    return true;
  if (doc.documentNo && doc.documentNo.toLowerCase().includes(needle))
    return true;
  if (doc.invoiceNo && doc.invoiceNo.toLowerCase().includes(needle))
    return true;
  if (
    doc.accountingRationale &&
    doc.accountingRationale.toLowerCase().includes(needle)
  )
    return true;
  if (
    doc.sourceBankTransactionId !== null &&
    String(doc.sourceBankTransactionId).includes(needle)
  )
    return true;
  if (
    doc.journalEntryText &&
    doc.journalEntryText.toLowerCase().includes(needle)
  )
    return true;
  if (
    doc.journalEntryNo &&
    doc.journalEntryNo.toLowerCase().includes(needle)
  )
    return true;
  return false;
}

export type GroupedDocument = DocumentRow & { associations: DocumentRow[] };

/** One row per original document; each linked posting remains available. */
export function groupDocuments(rows: DocumentRow[]): GroupedDocument[] {
  const groups = new Map<number, GroupedDocument>();
  for (const row of rows) {
    const existing = groups.get(row.id);
    if (!existing) {
      groups.set(row.id, { ...row, associations: [row] });
      continue;
    }
    if (!existing.associations.some((entry) => entry.journalEntryId === row.journalEntryId && entry.journalEntryNo === row.journalEntryNo && entry.voucherRef === row.voucherRef)) existing.associations.push(row);
    // Representative posting identifies booked documents without summing relations.
    if (!existing.journalEntryNo && row.journalEntryNo) {
      existing.journalEntryNo = row.journalEntryNo;
      existing.journalEntryId = row.journalEntryId;
      existing.journalEntryText = row.journalEntryText;
      existing.journalEntryTotal = row.journalEntryTotal;
      existing.voucherRef = row.voucherRef;
    }
    existing.hasFile ||= row.hasFile;
  }
  return [...groups.values()];
}

export function DocumentsView({ detail = false }: { detail?: boolean } = {}) {
  const { slug = "", documentId: routeDocumentId } = useParams();
  const { can } = useCapabilities(slug);
  const { year, setYear } = useCompanyYear();
  const [params, setParams] = useSearchParams();
  const parsedDocumentId = Number(detail ? routeDocumentId : params.get("documentId"));
  const documentId = Number.isSafeInteger(parsedDocumentId) && parsedDocumentId > 0 ? parsedDocumentId : null;
  const state = useAsync<DocumentsPage>(
    async (signal) => {
      const [documents, fiscalYears] = await Promise.all([
        api.documents(slug, { signal }),
        api.fiscalYears(slug, { signal }),
      ]);
      return { documents, fiscalYears };
    },
    [slug],
  );
  const partyLinks = useAsync((signal) => api.documentPartyLinks(slug, undefined, { signal }), [slug]);
  // True while the document-intake modal (#213, slice 3) is open.
  const [ingesting, setIngesting] = useState(false);
  const [confirmingInternal, setConfirmingInternal] = useState(false);
  // #588: a deliberately small, reviewed flow. A person selects a document,
  // sees its recorded identity, then selects a visible canonical party. Names
  // only help find a candidate; the server still requires exact evidence.
  const [partyReviewId, setPartyReviewId] = useState<number | null>(null);
  const [partyCandidates, setPartyCandidates] = useState<PartyCandidate[]>([]);
  const [selectedPartyId, setSelectedPartyId] = useState("");
  const [partyRole, setPartyRole] = useState<"vendor" | "customer">("vendor");
  const [partyPlan, setPartyPlan] = useState<PartyPlan | null>(null);
  const [partyError, setPartyError] = useState<string | null>(null);
  const [partyBusy, setPartyBusy] = useState(false);
  const [partyConfirmed, setPartyConfirmed] = useState(false);
  const [reviewScope, setReviewScope] = useState<string | null>(null);
  const currentScope = `${slug}:${year ?? "default"}`;
  const partyOutcome = useMutationOutcome(() => { partyLinks.reload(); state.reload(); });
  const markPartySaved = useUnsavedChanges(partyReviewId !== null && selectedPartyId !== "" && reviewScope === currentScope);
  useEffect(() => {
    setReviewScope(currentScope);
    setPartyReviewId(null); setPartyPlan(null); setPartyConfirmed(false); setConfirmingInternal(false); setIngesting(false);
  }, [currentScope]);

  // --- #433 filter-bar params (client-side; reflected in URL) ---------------
  const q = params.get("q") ?? "";
  const fromDate = params.get("from") ?? "";
  const toDate = params.get("to") ?? "";
  const statusRaw = params.get("status") ?? "all";
  const typeRaw = params.get("type") ?? "all";
  const partyRaw = params.get("party") ?? "all";
  const status: StatusFilter = isStatusFilter(statusRaw) ? statusRaw : "all";
  const type: TypeFilter = isTypeFilter(typeRaw) ? typeRaw : "all";
  const party: PartyFilter = partyRaw === "linked" || partyRaw === "unlinked" || partyRaw === "internal_no_external_party" || partyRaw === "ambiguous" ? partyRaw : "all";

  // #433 — sorter for the date/amount columns. Default is the order returned
  // by the server (the document id), which is what the page used to do; only
  // after the owner clicks a column-header do we override that order.
  const sortKey = params.get("sort");
  const sort: { key: SortKey; dir: SortDir } | null = sortKey === "date" || sortKey === "amount" ? { key: sortKey, dir: params.get("dir") === "desc" ? "desc" : "asc" } : null;

  function setFilter(key: (typeof FILTER_PARAM_KEYS)[number], value: string) {
    const next = new URLSearchParams(params);
    if (value === "" || value === "all") {
      next.delete(key);
    } else {
      next.set(key, value);
    }
    next.delete("page");
    setParams(next, { replace: true });
  }

  function clearAllFilters() {
    const next = new URLSearchParams(params);
    for (const k of [...FILTER_PARAM_KEYS, "documentId", "page"]) next.delete(k);
    setParams(next, { replace: true });
  }

  const hasActiveFilter =
    q !== "" ||
    fromDate !== "" ||
    toDate !== "" ||
    status !== "all" ||
    type !== "all" ||
    party !== "all" ||
    documentId !== null;

  function toggleSort(key: SortKey) {
    const next = new URLSearchParams(params);
    if (sort?.key === key && sort.dir === "desc") { next.delete("sort"); next.delete("dir"); }
    else { next.set("sort", key); next.set("dir", sort?.key === key ? "desc" : "asc"); }
    next.delete("page");
    setParams(next, { replace: true });
  }

  function setSorting(key: string, direction?: string) {
    const next = new URLSearchParams(params);
    if (key === "default") { next.delete("sort"); next.delete("dir"); }
    else { next.set("sort", key); next.set("dir", direction ?? sort?.dir ?? "asc"); }
    next.delete("page");
    setParams(next, { replace: true });
  }

  function sortIndicator(key: SortKey): string {
    if (!sort || sort.key !== key) return "";
    return sort.dir === "asc" ? " ▲" : " ▼";
  }

  const allDocuments = useMemo(() => groupDocuments(state.data?.documents.documents ?? []), [state.data?.documents.documents]);
  const linkedIds = useMemo(() => new Set((partyLinks.data ?? []).filter((link) => link.linked === 1).map((link) => link.id)), [partyLinks.data]);
  const internalNoPartyIds = useMemo(() => new Set((partyLinks.data ?? []).filter((link) => link.resolution_state === "internal_no_external_party").map((link) => link.id)), [partyLinks.data]);

  const filteredDocuments = useMemo(() => {
    if (detail && documentId === null) return [];
    if (!hasActiveFilter) return allDocuments;
    const needle = q.trim().toLowerCase();
    return allDocuments.filter((doc) => {
      if (documentId !== null && doc.id !== documentId) return false;
      if (!detail && needle !== "" && !doc.associations.some((association) => documentMatchesText(association, needle))) return false;
      if (!detail && fromDate !== "") {
        if (!doc.invoiceDate || doc.invoiceDate < fromDate) return false;
      }
      if (!detail && toDate !== "") {
        if (!doc.invoiceDate || doc.invoiceDate > toDate) return false;
      }
      if (!detail && status === "booked" && doc.journalEntryNo === null) return false;
      if (!detail && status === "unbooked" && doc.journalEntryNo !== null) return false;
      if (!detail && type !== "all" && doc.documentType !== type) return false;
      if (!detail && party === "linked" && !linkedIds.has(doc.id)) return false;
      if (!detail && party === "unlinked" && (linkedIds.has(doc.id) || internalNoPartyIds.has(doc.id))) return false;
      if (!detail && party === "internal_no_external_party" && !internalNoPartyIds.has(doc.id)) return false;
      // Ambiguity is intentionally not inferred: it needs an explicit reviewed
      // plan conflict, so this view offers the bounded unlinked review queue.
      if (!detail && party === "ambiguous") return false;
      return true;
    });
  }, [allDocuments, hasActiveFilter, q, fromDate, toDate, status, type, party, documentId, linkedIds, internalNoPartyIds, detail]);

  const sortedDocuments = useMemo(() => {
    if (!sort) return filteredDocuments;
    const out = [...filteredDocuments];
    out.sort((a, b) => {
      let cmp = 0;
      if (sort.key === "date") {
        const ad = a.invoiceDate ?? "";
        const bd = b.invoiceDate ?? "";
        cmp = ad < bd ? -1 : ad > bd ? 1 : 0;
      } else {
        const av = documentAmount(a);
        const bv = documentAmount(b);
        if (av === null && bv === null) cmp = 0;
        else if (av === null) cmp = 1;
        else if (bv === null) cmp = -1;
        else cmp = av - bv;
      }
      return sort.dir === "asc" ? cmp : -cmp;
    });
    return out;
  }, [filteredDocuments, sort]);

  if (state.loading && !state.data) return <Loading label="Henter bilag…" />;
  if (state.error && !state.data)
    return <ErrorState message={state.error} onRetry={state.reload} />;

  const { documents: d, fiscalYears } = state.data!;
  const currency = d.company.currency || "DKK";
  const selectedYear =
    year ??
    fiscalYears.find((y) => y.source === "live")?.label ??
    fiscalYears[0]?.label ??
    String(new Date().getFullYear());
  // The intake action is hidden when the selected year is an archived
  // (pre-cut-over, read-only) year — there is no live ledger to ingest into.
  const selectedYearArchived =
    fiscalYears.find((y) => y.label === selectedYear)?.source === "archive";

  const totalCount = allDocuments.length;
  const bookedCount = allDocuments.filter((doc) => doc.journalEntryNo !== null).length;
  const pagination = listPagination(params, sortedDocuments.length);
  const visibleDocuments = detail ? sortedDocuments : sortedDocuments.slice(pagination.offset, pagination.offset + pagination.pageSize);
  const returnTo = listReturnTo(slug, "bilag", params.get("returnTo"), year);
  function setPageParam(key: "page" | "pageSize", value: number) {
    const next = new URLSearchParams(params); next.set(key, String(value));
    if (key === "pageSize") next.delete("page");
    setParams(next, { replace: true });
  }
  const matchCount = sortedDocuments.length;
  const reviewedDocument = partyReviewId === null || reviewScope !== currentScope ? null : allDocuments.find((doc) => doc.id === partyReviewId) ?? null;

  async function beginPartyReview(doc: DocumentRow) {
    if (partyOutcome.isBlocked()) return;
    setReviewScope(currentScope);
    setPartyReviewId(doc.id);
    setSelectedPartyId("");
    setPartyRole("vendor");
    setPartyPlan(null);
    setPartyError(null);
    setPartyConfirmed(false);
    setPartyBusy(true);
    try {
      // This is a membership-scoped search. It is not a match decision.
      const result = await api.searchCanonicalParties(slug, doc.supplierName ?? "");
      setPartyCandidates(result.rows);
    } catch (error) {
      setPartyCandidates([]);
      setPartyError(error instanceof Error ? error.message : "Kunne ikke hente synlige parter.");
    } finally {
      setPartyBusy(false);
    }
  }

  function identityInput(doc: DocumentRow) {
    return {
      documentId: doc.id,
      partyId: selectedPartyId,
      role: partyRole,
      jurisdiction: doc.supplierCountryCode ?? undefined,
      identifierKind: doc.supplierIdentifierKind ?? undefined,
      identifier: doc.supplierVatOrCvr ?? undefined,
    };
  }

  async function planPartyLink() {
    if (partyOutcome.isBlocked()) return;
    if (!reviewedDocument || !selectedPartyId) return;
    setPartyBusy(true);
    setPartyError(null);
    setPartyPlan(null);
    setPartyConfirmed(false);
    try {
      const result = await api.planDocumentPartyLink(slug, identityInput(reviewedDocument));
      if (!result.ok || !result.plan) {
        setPartyError(result.errors?.join(", ") ?? "Planen kunne ikke godkendes.");
        return;
      }
      setPartyPlan(result.plan as PartyPlan);
    } catch (error) {
      setPartyError(error instanceof Error ? error.message : "Kunne ikke planlægge koblingen.");
    } finally {
      setPartyBusy(false);
    }
  }

  async function applyPartyLink() {
    if (partyOutcome.isBlocked() || partyBusy || !reviewedDocument || !partyPlan || !partyConfirmed) return;
    setPartyBusy(true);
    setPartyError(null);
    try {
      const result = await api.applyDocumentPartyLink(slug, {
        ...identityInput(reviewedDocument),
        planHash: partyPlan.planHash,
        confirm: true,
        // A UI retry remains safe for this exact reviewed plan.
        idempotencyKey: `document-party-link-${reviewedDocument.id}-${partyPlan.planHash}`,
      }).catch(partyOutcome.reject);
      if (!result.ok) {
        setPartyError(result.errors?.join(", ") ?? "Koblingen kunne ikke gemmes.");
        return;
      }
      await Promise.all([partyLinks.reload(), state.reload()]);
      // Inspect after the write so the visible status/history is current.
      await api.documentPartyLinkHistory(slug, reviewedDocument.id);
      markPartySaved();
      setPartyReviewId(null);
    } catch (error) {
      setPartyError(error instanceof Error ? error.message : "Koblingen kunne ikke gemmes.");
    } finally {
      setPartyBusy(false);
    }
  }

  async function confirmInternalNoParty() {
    if (partyOutcome.isBlocked() || !reviewedDocument || reviewedDocument.documentType !== "internal_voucher") return;
    const result = await api.confirmInternalNoExternalParty(slug, {
      documentId: reviewedDocument.id,
      reason: "Bekræftet via bilagsgennemgang.",
      idempotencyKey: `internal-no-party-${reviewedDocument.id}`,
      confirm: true,
    }).catch(partyOutcome.reject);
    if (!result.ok) throw new Error(result.errors?.join(", ") ?? "Beslutningen kunne ikke gemmes.");
    await partyLinks.reload();
    setPartyReviewId(null);
  }

  return (
    <section className="statement">
      {state.error && <Banner kind="warning">Status kunne ikke opdateres: {state.error} De tidligere hentede bilag vises fortsat.</Banner>}
      {partyOutcome.feedback}
      <PageHeader title={detail ? `Bilag ${sortedDocuments[0]?.documentNo ?? documentId ?? ""}` : "Bilag"}
        description={`${d.company.name} · ${currency} · Alle bilag på tværs af regnskabsår`}
        actions={detail ? <ButtonLink className="btn secondary" to={returnTo}>Tilbage til bilag</ButtonLink> : !selectedYearArchived && can("company.documents.upload") ? <Button onClick={() => setIngesting(true)}>Indlæs bilag</Button> : undefined} />

      <CompanyNav
        slug={slug}
        years={fiscalYears}
        selectedYear={selectedYear}
        onYearChange={setYear}
      />

      {ingesting && (
        <DocumentIngestModal
          slug={slug}
          onIngested={state.reload}
          onClose={() => setIngesting(false)}
        />
      )}

      {confirmingInternal && reviewedDocument && !selectedYearArchived && can("company.master-data") && <ConfirmDialog
        title="Bekræft internt bilag uden ekstern part"
        body={<p>Bekræft at bilag {reviewedDocument.documentNo ?? reviewedDocument.id} bevidst ikke har en ekstern part. Beslutningen registreres i revisionssporet.</p>}
        confirmLabel="Bekræft ingen ekstern part"
        onConfirm={confirmInternalNoParty}
        onRefresh={() => { partyLinks.reload(); state.reload(); }}
        onClose={() => setConfirmingInternal(false)} />}

      {!detail && <FilterBar activeCount={[q, fromDate, toDate, status === "all" ? "" : status, type === "all" ? "" : type, party === "all" ? "" : party].filter(Boolean).length} onReset={clearAllFilters}>
        <label className="journal-filter-field journal-filter-field--search">
          <span className="muted">Søg</span>
          <Input
            type="search"
            value={q}
            placeholder="Søg på leverandør, bilagsnr., faktura eller posteringstekst…"
            onChange={(e) => setFilter("q", e.target.value)}
          />
        </label>
        <label className="journal-filter-field">
          <span className="muted">Fra</span>
          <Input
            type="date"
            value={fromDate}
            onChange={(e) => setFilter("from", e.target.value)}
          />
        </label>
        <label className="journal-filter-field">
          <span className="muted">Registreret modpart</span>
          <Select value={party} onChange={(e) => setFilter("party", e.target.value)}>
            <option value="all">Alle</option>
            <option value="linked">Koblet</option>
            <option value="unlinked">Mangler review</option>
            <option value="internal_no_external_party">Internt uden ekstern part</option>
            <option value="ambiguous">Tvetydige (kræver review)</option>
          </Select>
        </label>
        <label className="journal-filter-field">
          <span className="muted">Til</span>
          <Input
            type="date"
            value={toDate}
            onChange={(e) => setFilter("to", e.target.value)}
          />
        </label>
        <label className="journal-filter-field">
          <span className="muted">Status</span>
          <Select
            value={status}
            onChange={(e) => setFilter("status", e.target.value)}
          >
            <option value="all">Alle</option>
            <option value="booked">Bogført</option>
            <option value="unbooked">Kun ubehandlede</option>
          </Select>
        </label>
        <label className="journal-filter-field">
          <span className="muted">Type</span>
          <Select
            value={type}
            onChange={(e) => setFilter("type", e.target.value)}
          >
            <option value="all">Alle</option>
            <option value="purchase_sale">Køb/salg</option>
            <option value="cash_register_receipt">Kassebon</option>
            <option value="internal_voucher">Internt bilag</option>
          </Select>
        </label>

        <label className="journal-filter-field">Sortering<Select value={sort?.key ?? "default"} onChange={(event) => setSorting(event.target.value)}><option value="default">Nyeste indlæsning</option><option value="date">Fakturadato</option><option value="amount">Beløb</option></Select></label>
        {sort && <label className="journal-filter-field">Rækkefølge<Select value={sort.dir} onChange={(event) => setSorting(sort.key, event.target.value)}><option value="asc">Stigende</option><option value="desc">Faldende</option></Select></label>}
      </FilterBar>}

      <p className="statement-asof muted">
        {hasActiveFilter
          ? `${matchCount} af ${totalCount} bilag matcher`
          : `${totalCount} bilag`}
        {" · "}
        {bookedCount} bogført · {totalCount - bookedCount} ubehandlet
      </p>

      {reviewedDocument && !selectedYearArchived && can("company.master-data") && (
        <section className="card" aria-label="Gennemgå registreret modpart">
          <div className="page-head">
            <div>
              <h3>Gennemgå registreret modpart</h3>
              <p className="muted">Bilag {reviewedDocument.documentNo ?? `#${reviewedDocument.id}`}. Navne er kun søgehjælp — koblingen kræver den uforanderlige identitet nedenfor.</p>
            </div>
            <Button type="button" className="btn secondary" onClick={() => setPartyReviewId(null)}>Luk</Button>
          </div>
          <dl className="key-value-list">
            <div><dt>Identitet på bilaget</dt><dd>{reviewedDocument.supplierCountryCode ?? "—"} · {reviewedDocument.supplierIdentifierKind ?? "—"} · {reviewedDocument.supplierVatOrCvr ?? "Ingen verificerbar identifikator"}</dd></div>
            <div><dt>Bevis</dt><dd>Originalfilen og bogføringen ændres ikke. Planen binder bilagets hash til den valgte part.</dd></div>
          </dl>
          <div className="row-actions">
            <label>Rolle <Select value={partyRole} onChange={(event) => { setPartyRole(event.target.value as "vendor" | "customer"); setPartyPlan(null); setPartyConfirmed(false); }}><option value="vendor">Leverandør</option><option value="customer">Kunde</option></Select></label>
            <label>Vælg registreret modpart <Select aria-label="Vælg registreret modpart" value={selectedPartyId} onChange={(event) => { setSelectedPartyId(event.target.value); setPartyPlan(null); setPartyConfirmed(false); }} disabled={partyBusy || partyOutcome.blocked}><option value="">Vælg en synlig part…</option>{partyCandidates.map((candidate) => <option key={candidate.partyId} value={candidate.partyId}>{candidate.name}</option>)}</Select></label>
            <Button type="button" className="btn secondary" disabled={partyOutcome.blocked || partyBusy || !selectedPartyId || !reviewedDocument.supplierVatOrCvr} onClick={planPartyLink}>Vis plan</Button>
          </div>
          {!reviewedDocument.supplierVatOrCvr && <p className="flag warning">Bilaget har ingen verificerbar identifikator. Navne alene kan ikke kobles.</p>}
          {partyError && <p className="flag warning" role="alert">{partyError}</p>}
          {partyPlan && <div className="card"><p><strong>Plan klar</strong> — {partyPlan.partySnapshot?.name ?? "Valgt part"}; bevis: {partyPlan.evidence?.kind ?? "exact_identifier"}.</p><p className="muted">Plan-hash: <code>{partyPlan.planHash}</code></p><label><Input type="checkbox" disabled={partyBusy || partyOutcome.blocked} checked={partyConfirmed} onChange={(event) => setPartyConfirmed(event.target.checked)} /> Jeg har gennemgået planen og vil oprette den append-only kobling.</label><div className="row-actions"><Button type="button" className="btn" disabled={partyOutcome.blocked || partyBusy || !partyConfirmed} onClick={applyPartyLink}>Bekræft og anvend</Button></div></div>}
          {reviewedDocument.documentType === "internal_voucher" && <div className="card"><p className="muted">Interne bilag kan bekræftes uden ekstern part. Beslutningen er append-only og ændrer ikke bilag, moms eller journal.</p><Button type="button" className="btn secondary" disabled={partyBusy || partyOutcome.blocked} onClick={() => setConfirmingInternal(true)}>Bekræft ingen ekstern part</Button></div>}
        </section>
      )}

      {detail && sortedDocuments.length === 0 && <div className="card" role="status"><h2>Bilaget findes ikke</h2><p>Gå tilbage til bilagslisten og vælg et eksisterende bilag.</p></div>}
      <div className="card statement-card table-scroll">
        <table className="data statement-table daily-table" role="table">
          <thead role="rowgroup">
            <tr role="row">
              <th>Bilagsnr.</th>
              <th>Type</th>
              <th>Modpart / grundlag</th>
              <th>Faktura</th>
              <th>
                <Button
                  type="button"
                  className="th-sort"
                  onClick={() => toggleSort("date")}
                  aria-label="Sortér efter dato"
                >
                  Dato{sortIndicator("date")}
                </Button>
              </th>
              <th className="num">
                <Button
                  type="button"
                  className="th-sort"
                  onClick={() => toggleSort("amount")}
                  aria-label="Sortér efter beløb"
                >
                  Beløb inkl. moms{sortIndicator("amount")}
                </Button>
              </th>
              <th>Postering</th>
              <th>Bilagsfil</th>
            </tr>
          </thead>
          <tbody role="rowgroup">
            {sortedDocuments.length === 0 ? (
              <tr role="row">
                <td colSpan={8} className="empty-inline">
                  {hasActiveFilter
                    ? "Ingen bilag matcher filtrene."
                    : "Ingen bilag indlæst endnu."}
                </td>
              </tr>
            ) : (
              visibleDocuments.map((doc) => (
                <tr role="row" key={doc.id}>
                  <td role="cell" data-label="Bilag" className="account-no">
                    <Link to={workflowTo(slug, "bilag", String(doc.id), params, selectedYear)}>{doc.documentNo ?? `#${doc.id}`}</Link>
                  </td>
                  <td role="cell" data-label="Type">
                    {DOC_TYPE_LABELS[doc.documentType] ?? doc.documentType}
                  </td>
                  <td role="cell" data-label="Modpart / grundlag">
                    <div>
                      {doc.documentType === "internal_voucher"
                        ? `Bankpost #${doc.sourceBankTransactionId ?? "—"}`
                        : doc.supplierName ?? "—"}
                    </div>
                    {doc.documentType === "internal_voucher" && doc.accountingRationale ? (
                      <div className="muted">{doc.accountingRationale}</div>
                    ) : null}
                    {(doc.supplierCountryCode || doc.supplierIdentifierKind || doc.supplierIdentityStatus) && (
                      <div className="muted">
                        {doc.supplierCountryCode ?? "—"} · {doc.supplierIdentifierKind ?? "—"} · {doc.supplierIdentityStatus === "resolved" ? "Identitet bekræftet" : doc.supplierIdentityStatus ? "Identitet kræver gennemgang" : "—"}
                      </div>
                    )}
                    <div className="muted">{internalNoPartyIds.has(doc.id) ? "Bekræftet internt bilag uden ekstern part" : linkedIds.has(doc.id) ? "Registreret modpart koblet" : "Registreret modpart ikke koblet — gennemgå før anvendelse"}</div>
                    {!selectedYearArchived && can("company.master-data") && !linkedIds.has(doc.id) && !internalNoPartyIds.has(doc.id) && <Button type="button" className="btn small secondary" disabled={partyBusy || partyOutcome.blocked} onClick={() => beginPartyReview(doc)}>Gennemgå part</Button>}
                  </td>
                  <td role="cell" data-label="Faktura">{doc.invoiceNo ?? "—"}</td>
                  <td role="cell" data-label="Dato" className="entry-date">{doc.invoiceDate ?? "—"}</td>
                  <td role="cell" data-label="Beløb inkl. moms" className="num"><Amount value={documentAmount(doc)} currency={doc.amountIncVat !== null ? doc.currency : "DKK"} />{doc.amountIncVat === null && doc.associations.filter((entry) => entry.journalEntryNo).length > 1 && <span className="muted">Se de tilknyttede posteringer</span>}</td>
                  <td role="cell" data-label="Postering">
                    {doc.journalEntryNo ? doc.associations.filter((association) => association.journalEntryNo).map((association) => (
                      <div className="doc-posting" key={`${association.journalEntryId}-${association.voucherRef}`}>
                        <span className="flag ok">{association.journalEntryNo}{association.voucherRef ? ` · bilag ${association.voucherRef}` : ""}</span>
                        {association.journalEntryText && <span className="doc-posting-text muted">{association.journalEntryText}</span>}
                        {detail && <Amount value={association.journalEntryTotal} currency="DKK" />}
                      </div>
                    )) : ["purchase_sale", "cash_register_receipt", "internal_voucher"].includes(doc.documentType) ? <div className="doc-posting"><span className="flag warning">Ikke bogført</span>
                      {!selectedYearArchived && can("company.ledger.post") && <ButtonLink className="btn small" to={workflowTo(slug, "bilag", `${doc.id}/bogfoer`, params, selectedYear)}>Bogfør bilag</ButtonLink>}
                    </div> : <span className="muted">{doc.documentType === "issued_invoice_pdf" ? "PDF af udstedt faktura" : doc.documentType === "issued_invoice" ? "Bogføres fra Fakturaer" : "—"}</span>}

                  </td>
                  <td>
                    {doc.hasFile ? (
                      <a
                        href={api.documentFileUrl(slug, doc.id)}
                        target="_blank"
                        rel="noreferrer"
                      >
                        Åbn bilag
                      </a>
                    ) : (
                      <span className="muted">—</span>
                    )}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
      {!detail && <Pagination total={matchCount} {...pagination} onPageChange={(page) => setPageParam("page", page)} onPageSizeChange={(size) => setPageParam("pageSize", size)} />}
    </section>
  );
}

export function DocumentDetailView() { return <DocumentsView detail />; }

definition.api:
import { ordinaryWorkspaceWriteAllowed } from "../workspace-write-mode";
// Shared primitives for the cockpit API client.
//
// `ApiError` is the canonical error class every per-domain module throws via
// `request<T>(...)`. Re-exported from `app/src/lib/api.ts` so external callers
// keep importing it from the barrel.

/** Optional cancellation belongs to one read request, never shared state. */
export type ReadRequestOptions = Pick<RequestInit, "signal">;

function isAborted(cause: unknown, signal: AbortSignal | null | undefined): boolean {
  return signal?.aborted === true || (cause instanceof Error && cause.name === "AbortError");
}

/** A failed API call — carries the backend error code for precise handling. */
export class ApiError extends Error {
  readonly code: string;
  readonly status: number;
  constructor(code: string, message: string, status: number) {
    super(message);
    this.name = "ApiError";
    this.code = code;
    this.status = status;
  }
}

/** Raised once for an expired hosted browser session.  The app shell listens
 * for this event so an old view is never left visible after a 401. */
function signalAuthExpired(): void {
  if (typeof window !== "undefined") {
    window.dispatchEvent(new Event("rentemester:auth-expired"));
  }
}

type ApiRequestOptions = RequestInit & { readOnly?: boolean };

function isWrite(init?: ApiRequestOptions): boolean {
  return !init?.readOnly && init?.method !== undefined && !["GET", "HEAD"].includes(init.method.toUpperCase());
}

async function fetchResponse(path: string, init?: ApiRequestOptions): Promise<Response> {
  if (!ordinaryWorkspaceWriteAllowed(path, init?.method ?? "GET", init?.readOnly)) throw new ApiError("workspace_not_active", "Workspace er skrivebeskyttet. Kontrollér flytningens aktuelle tilstand.", 423);
  const { readOnly, ...fetchOptions } = init ?? {};
  try {
    return await fetch(path, {
      ...fetchOptions,
      credentials: "same-origin",
      headers: { "content-type": "application/json", ...(init?.headers ?? {}) },
    });
  } catch (cause) {
    if (isAborted(cause, init?.signal)) throw cause;
    throw new ApiError(
      "network",
      isWrite(init) ? "Handlingen kan være gennemført, men serverens resultat kunne ikke bekræftes. Kontrollér status, før du starter en ny handling." : "Kunne ikke nå serveren. Kontrollér forbindelsen og prøv igen.",
      0,
    );
  }
}

/** Decode the same server envelope for JSON responses and binary failures. */
function responseError(res: Response, body: unknown, fallback: string): ApiError {
  const env = body && typeof body === "object" ? body as { errors?: unknown; code?: unknown } : undefined;
  const errors = Array.isArray(env?.errors) ? env.errors.map(String) : [];
  const code = res.status === 401 ? "unauthorized" : typeof env?.code === "string" ? env.code : "internal";
  if (code === "unauthorized") signalAuthExpired();
  const message = res.status === 403 && ["access_denied", "forbidden", "internal"].includes(code)
    ? "Du har ikke adgang til denne handling. Bed workspace-ejeren kontrollere dine rettigheder."
    : errors[0] ?? (res.status === 401 ? "Din session er udløbet. Log ind igen." : fallback);
  return new ApiError(code, message, res.status);
}

function bodyReadError(res: Response, cause: unknown, init?: ApiRequestOptions): unknown {
  if (isAborted(cause, init?.signal)) return cause;
  return responseError(res, undefined, isWrite(init)
    ? "Serverens svar på handlingen kunne ikke læses. Kontrollér status, før du starter en ny handling."
    : "Serveren gav et ugyldigt svar.");
}

export async function request<T>(path: string, init?: ApiRequestOptions): Promise<T> {
  const res = await fetchResponse(path, init);
  let body: unknown;
  try {
    body = await res.json();
  } catch (cause) {
    throw bodyReadError(res, cause, init);
  }
  // A superseded auth read must not expire the newer session via its old 401.
  init?.signal?.throwIfAborted();
  if (body && typeof body === "object" && (body as { ok?: unknown }).ok === false) throw responseError(res, body, "Ukendt serverfejl.");
  if (!res.ok) throw responseError(res, undefined, `HTTP ${res.status}`);
  return body as T;
}

/** Binary success keeps domain headers; transport failures use the canonical seam. */
export async function requestBlob(path: string, init?: ApiRequestOptions): Promise<{ blob: Blob; headers: Headers }> {
  const res = await fetchResponse(path, init);
  if (!res.ok) {
    let body: unknown;
    try { body = await res.json(); } catch (cause) {
      if (isAborted(cause, init?.signal)) throw cause;
    }
    throw responseError(res, body, `HTTP ${res.status}`);
  }
  try {
    return { blob: await res.blob(), headers: res.headers };
  } catch (cause) {
    throw bodyReadError(res, cause, init);
  }
}

/** Picks the filename from a `filename*=UTF-8''…` content-disposition header. */
export function parseFilenameFromContentDisposition(cd: string | null): string | null {
  if (!cd) return null;
  const m = cd.match(/filename\*=UTF-8''([^;]+)/i);
  if (!m || !m[1]) return null;
  try {
    return decodeURIComponent(m[1]);
  } catch {
    return null;
  }
}

