import { useParams } from "react-router-dom";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { Button, Input, PageHeader, Select, Textarea } from "../components/ui";
import { workspaceRegistryApi } from "../lib/api/workspace-registry";
import { useAsync } from "../lib/useAsync";
import { useMutationOutcome } from "../lib/useMutationOutcome";
import { useUnsavedChanges } from "../lib/useUnsavedChanges";
import { CompanyKnowledgePanel } from "./CompanyKnowledgePanel";
import { WorkspacePartiesPanel } from "./WorkspacePartiesPanel";

type Action={permission:"company.admin"|"company.master-data"|"company.review"|"company.knowledge.manage"|"company.ownership.manage";label:string;help:string;initial:string;run:(body:Record<string,unknown>)=>Promise<unknown>};
const parse=(value:string):Record<string,unknown>=>{const result=JSON.parse(value);if(!result||Array.isArray(result)||typeof result!=="object")throw new Error("Indtast et JSON-objekt.");return result as Record<string,unknown>;};

/** Thin Cockpit adapter: the server remains the single role/business gate. */
function ActionForm({action,onDone}:{action:Action;onDone:()=>void}){const [payload,setPayload]=useState(action.initial);const [savedPayload,setSavedPayload]=useState(action.initial);const [confirmed,setConfirmed]=useState(false);const [busy,setBusy]=useState(false);const [result,setResult]=useState<string>();const outcome = useMutationOutcome(onDone);
  useUnsavedChanges(payload !== savedPayload);async function submit(event:FormEvent){event.preventDefault();
    if (outcome.isBlocked()) return;setResult(undefined);try{setBusy(true);await action.run(parse(payload)).catch(outcome.reject);setSavedPayload(payload);setResult("Handlingen er registreret i revisionssporet.");onDone();}catch(error){setResult(error instanceof Error?error.message:"Handlingen kunne ikke udføres.");}finally{setBusy(false);}}return <form aria-label={action.label} onSubmit={event=>void submit(event)} className="modal-body">
    {outcome.feedback}<p className="muted">{action.help} Serveren kontrollerer din aktuelle rolle og adgang.</p><label className="modal-field">JSON-data<Textarea disabled={outcome.blocked} aria-label={`${action.label} JSON`} value={payload} onChange={event=>setPayload(event.target.value)} rows={5}/></label><label className="modal-checkbox"><Input disabled={outcome.blocked} type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)}/> Jeg bekræfter denne auditerede ændring</label><div className="modal-actions"><Button requiredPermission={action.permission} variant="secondary" className="btn secondary" type="submit" disabled={outcome.blocked || (!confirmed||busy)}>{busy?"Arbejder…":action.label}</Button></div>{result&&<Banner kind={result.includes("registreret")?"success":"error"}>{result}</Banner>}</form>}

function RecordIngest({slug,onDone}:{slug:string;onDone:()=>void}){const [file,setFile]=useState<File>();const [type,setType]=useState("other");const [confirmed,setConfirmed]=useState(false);const [busy,setBusy]=useState(false);const [result,setResult]=useState<string>();const outcome = useMutationOutcome(onDone);
  useUnsavedChanges(Boolean(file) && !result?.includes("indlæst"));async function submit(event:FormEvent){event.preventDefault();
    if (outcome.isBlocked()) return;if(!file){setResult("Vælg en fil først.");return;}if(file.size>8*1024*1024){setResult("Filen er for stor til Cockpit; brug CLI/MCP for den kontrollerede import.");return;}try{setBusy(true);const bytesBase64=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error("Filen kunne ikke læses."));reader.onload=()=>resolve(String(reader.result).split(",")[1]??"");reader.readAsDataURL(file);});await workspaceRegistryApi.recordIngest(slug,{type,bytesBase64,filename:file.name,source:"cockpit_upload",receivedAt:new Date().toISOString(),uploader:"cockpit",sensitivity:"normal",links:[{type:"company",id:slug}]}).catch(outcome.reject);setResult("Den immutable record er indlæst.");onDone();}catch(error){setResult(error instanceof Error?error.message:"Record kunne ikke indlæses.");}finally{setBusy(false);}}return <form aria-label="Indlæs corporate record" onSubmit={event=>void submit(event)} className="modal-body">
    {outcome.feedback}<p className="muted">Filen gemmes som immutable original med SHA-256. Upload aldrig credentials eller hemmeligheder.</p><label className="modal-field">Fil<Input disabled={outcome.blocked} aria-label="Corporate record fil" type="file" onChange={event=>{setFile(event.target.files?.[0]);setResult(undefined);}}/></label><label className="modal-field">Type<Select aria-label="Corporate record type" disabled={outcome.blocked} value={type} onChange={event=>setType(event.target.value)}><option value="other">Andet governance-materiale</option><option value="articles">Vedtægter</option><option value="registration">Registrering</option><option value="board_resolution">Bestyrelsesbeslutning</option><option value="ownership_register">Ejerbog</option></Select></label><label className="modal-checkbox"><Input aria-label="Bekræft corporate record upload" disabled={outcome.blocked} type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)}/> Jeg bekræfter upload af dette governance-dokument</label><div className="modal-actions"><Button requiredPermission="company.master-data" variant="secondary" className="btn secondary" type="submit" disabled={outcome.blocked || (!file||!confirmed||busy)}>{busy?"Indlæser…":"Indlæs immutable record"}</Button></div>{result&&<Banner kind={result.includes("indlæst")?"success":"error"}>{result}</Banner>}</form>}

function RecordEvidence({slug,id}:{slug:string;id:string}) {
 const [record,setRecord]=useState<Awaited<ReturnType<typeof workspaceRegistryApi.corporateRecord>>["record"]>();
 const [error,setError]=useState<string>(); const [busy,setBusy]=useState(false);
 async function inspect(){setBusy(true);setError(undefined);try{setRecord((await workspaceRegistryApi.corporateRecord(slug,id)).record);}catch(e){setRecord(undefined);setError(e instanceof Error?e.message:"Record kan ikke vises med aktuel adgang");}finally{setBusy(false);}}
 async function download(){if(!record)return;setBusy(true);setError(undefined);try{const response=await workspaceRegistryApi.corporateRecordDownload(slug,id);if(response.sha256!==record.sha256)throw Error("Originalens hash ændrede sig; genlæs record");const bytes=Uint8Array.from(atob(response.bytesBase64),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes],{type:"application/octet-stream"}));const a=document.createElement("a");a.href=url;a.download=record.filename;a.click();URL.revokeObjectURL(url);}catch(e){setError(e instanceof Error?e.message:"Originalen kunne ikke hentes");}finally{setBusy(false);}}
 return <div><Button type="button" variant="secondary" disabled={busy} onClick={()=>void inspect()}>Vis record {id}</Button>{error&&<p role="alert">{error}</p>}{record&&<div><p>Record ID: <code>{record.recordId}</code> · SHA-256 <code>{record.sha256}</code> · {record.sensitivity}</p><Button type="button" variant="secondary" disabled={busy} onClick={()=>void download()}>Hent original {id}</Button><ul>{record.links.map(l=><li key={`${l.type}:${l.id}`}>{l.type}: {l.id}</li>)}</ul><ul>{record.history.map((h,i)=><li key={`${h.payload_hash}:${i}`}>{h.event_type} · {h.actor} · {h.created_at} · {h.payload_hash}</li>)}</ul></div>}</div>;
}

export function WorkspaceRegistryView(){const {slug=""}=useParams();const [revision,setRevision]=useState(0);const [asOf,setAsOf]=useState(()=>new Date().toISOString().slice(0,10));const records=useAsync((signal)=>workspaceRegistryApi.corporateRecords(slug, { signal }),[slug]);const ownership=useAsync((signal)=>workspaceRegistryApi.ownership(slug, asOf, { signal }),[slug,asOf]);const history=useAsync((signal)=>workspaceRegistryApi.ownershipHistory(slug, { signal }),[slug]);const reload=()=>{setRevision(v=>v+1);records.reload();ownership.reload();history.reload();};

const recordActions:Action[]=[{permission:"company.master-data",label:"Knyt record",run:body=>workspaceRegistryApi.recordAction(slug,String(body.recordId??""),"link",body),initial:`{"recordId":"","type":"company","id":"${slug}"}`,help:"Knytter eksisterende immutable evidence med en typed reference."},{permission:"company.master-data",label:"Berig metadata",run:body=>workspaceRegistryApi.recordAction(slug,String(body.recordId??""),"enrich",body),initial:'{"recordId":"","assertion":""}',help:"Tilføjer provenance uden at ændre filens bytes eller hash."},{permission:"company.master-data",label:"Supersedér record",run:body=>workspaceRegistryApi.recordAction(slug,String(body.recordId??""),"supersede",body),initial:'{"recordId":"","replacementRecordId":"","reason":""}',help:"Opretter en append-only korrektionskæde; ingen original overskrives."}];

const ownershipActions:Action[]=[{permission:"company.ownership.manage",label:"Foreslå snapshot",run:body=>workspaceRegistryApi.ownershipMutate(slug,"propose",body),initial:'{"source":"registry","observedAt":"2026-01-01T00:00:00.000Z","facts":[]}',help:"Gemmer en kilde-hashet legal observation og deterministic diff."},{permission:"company.admin",label:"Review snapshot",run:body=>workspaceRegistryApi.ownershipMutate(slug,"review",body),initial:'{"snapshotId":"","decision":"approved"}',help:"Godkender eller afviser den konkrete snapshot uden at ændre facts."},{permission:"company.admin",label:"Apply eksakt diff",run:body=>workspaceRegistryApi.ownershipMutate(slug,"apply",body),initial:'{"snapshotId":"","snapshotHash":"","diffHash":""}',help:"Anvender kun den eksakt reviewede hash; adgang til alle endpoints genkontrolleres."}];
return <section className="page">{records.loading&&!records.data&&<Loading label="Henter workspace-register…"/>}{records.error&&<Banner kind="warning">Status kunne ikke opdateres. Formularerne er bevaret; oplysningerne er fra den seneste gennemførte læsning.</Banner>}<PageHeader title="Parter og virksomhedsforhold" actions={<><Button variant="secondary" type="button" className="secondary" onClick={reload}>Opdater</Button></>}><div><p className="eyebrow">Workspace</p><p className="muted">Kun relationer, der er synlige i denne virksomhed, vises. Originale records ændres aldrig her.</p></div></PageHeader><div className="split-grid"><WorkspacePartiesPanel key={`parties-${slug}`} slug={slug} refreshVersion={revision}/><section className="card"><h3>Corporate records</h3>{records.error&&!records.data?<ErrorState message={records.error} onRetry={records.reload}/>:records.data?.rows.length?<ul>{records.data.rows.map(r=><li key={r.recordId}><strong>{r.filename}</strong> <span className="muted">{r.type} · SHA-256 {r.sha256.slice(0,12)}…</span><RecordEvidence slug={slug} id={r.recordId}/></li>)}</ul>:<p className="muted">Ingen synlige governance-records endnu.</p>}<details><summary>Indlæs og vedligehold records</summary><RecordIngest slug={slug} onDone={reload}/>{recordActions.map(action=><ActionForm key={action.label} action={action} onDone={reload}/>)}</details></section><CompanyKnowledgePanel key={slug} slug={slug}/><section className="card" aria-label="Ejer- og kontrolforhold"><h3>Ejer- og kontrolforhold</h3><label>Pr. dato <Input aria-label="Ownership as-of" type="date" value={asOf} onChange={e=>setAsOf(e.target.value)}/></label><p className="muted">{ownership.data?.partial?"Delvist synlige relationer; skjulte endpoints og antal vises ikke.":ownership.data?.consolidation?.reason??"Ownership-forhold kan ikke vises med den aktuelle adgang."}</p>{ownership.error?<ErrorState message={ownership.error} onRetry={ownership.reload}/>:ownership.data?.facts?.length?<ul aria-label="Direkte ejerfacts">{ownership.data.facts.map((fact,index)=><li key={index}><code>{fact.owner.kind==="company"?fact.owner.companySlug:fact.owner.partyId}</code> → <code>{fact.ownedCompanySlug}</code> · {fact.economicBasisPoints!=null?`${fact.economicBasisPoints} bp`:`${fact.economicIntervalBasisPoints?.min}..${fact.economicIntervalBasisPoints?.max} bp`} · {fact.controlType} · {fact.validFrom} til {fact.validToExclusive??"åben slutdato"} (slutdato eksklusiv){fact.votingBasisPoints!=null&&` · stemmer ${fact.votingBasisPoints} bp`} · {fact.jurisdiction}<div>Kilder: {fact.evidenceRefs?.map(ref=><code key={ref}>{ref} </code>)}</div></li>)}</ul>:<p className="muted">Ingen synlige, godkendte facts.</p>}<details><summary>Forslag, review og apply</summary><p className="muted">Historik er append-only. Uunderstøttede projektioner vises aldrig som konsolidering; brug kun den eksplicitte serverstatus.</p>{ownershipActions.map(action=><ActionForm key={action.label} action={action} onDone={reload}/>)}<p className="muted">Review kræver en anden autentificeret person end forslagsstilleren. Apply bruger de fulde snapshot- og diff-hashes. En senere dateret fact kan afslutte en tidligere fact; manglende observationer afslutter aldrig en fact.</p>{history.error?<ErrorState message={history.error} onRetry={history.reload}/>:<ul>{history.data?.history?.map(item=><li key={item.snapshotId}><details><summary>{item.snapshotId} · {item.state}</summary><p>Snapshot-hash: <code>{item.snapshotHash}</code><br/>Diff-hash: <code>{item.diffHash}</code></p><pre>{JSON.stringify(item,null,2)}</pre></details></li>)}</ul>}</details></section></div></section>}

