      <td className="entry-date">{row.writeOffDate}</td>
      <td className="num">{formatKroner(row.cost, currency)}</td>
      <td className="account-no">{row.expenseAccountNo}</td>
      <td>{row.thresholdRuleSource}</td>
    </tr>
