      <h3 {...stylex.props(viewStyles.site0)}>Forslag</h3>
      {data.rows.length === 0 ? (
        <div className="card archived-notice">
          <p className="muted">
            Agenten har ingen åbne forslag. Hver gang en automatisk kørsel
            løber ind i en sag, der kræver din vurdering — fx en overforfalden
            kreditorpost, et muligt anlæg, eller en periodeafgrænsning klar
            til bogføring — dukker forslaget op her.
          </p>
        </div>
      ) : (
        <div className="card statement-card table-scroll">
          <table className="data statement-table">
            <thead>
              <tr>
                <th>Prioritet</th>
                <th>Type</th>
                <th>Agentens vurdering</th>
                <th>Hjemmel</th>
                <th>Handling</th>
              </tr>
            </thead>
            <tbody>
              {data.rows.map((row) => (
                <SuggestionRowView
                  key={row.exceptionId}
                  row={row}
                  slug={slug}
                  onChanged={() => state.reload()}
                  onError={setActionError}
                />
              ))}
            </tbody>
          </table>
        </div>
      )}

      <p className="statement-check ok">
        Hvert forslag er en åben undtagelse i ledger'en — godkendelse og
        afvisning løser undtagelsen via samme kerne (
        <code>resolveException</code>) som CLI'en og MCP-kald bruger, så
        beslutningen står på audit-sporet med din actor og en
        beslutningstekst.
      </p>
    </section>
  );
}

function SuggestionRowView({
  row,
  slug,
  onChanged,
  onError,
}: {
  row: AgentSuggestionRow;
  slug: string;
  onChanged: () => void;
  onError: (msg: string) => void;
}) {
  const [busy, setBusy] = useState<"approve" | "reject" | null>(null);
  const [pending, setPending] = useState<"approve" | "reject" | null>(null);

  async function doApprove() {
    setBusy("approve");
    try {
      await api.approveAgentSuggestion(slug, row.exceptionId);
      onChanged();
    } catch (err) {
      onError(
        err instanceof ApiError
          ? err.message
          : "Kunne ikke godkende forslaget.",
      );
      throw err;
    } finally {
      setBusy(null);
    }
  }

  async function doReject(note: string) {
    setBusy("reject");
    try {
      await api.rejectAgentSuggestion(
        slug,
        row.exceptionId,
        note.length > 0 ? note : undefined,
      );
      onChanged();
    } catch (err) {
      onError(
        err instanceof ApiError ? err.message : "Kunne ikke afvise forslaget.",
      );
      throw err;
    } finally {
      setBusy(null);
    }
  }

  const severityLabel = SEVERITY_LABEL[row.severity];
  const flagClass =
    row.severity === "high"
      ? "warn"
      : row.severity === "medium"
        ? "neutral"
        : "ok";

  return (
    <tr>
      <td>
        <span className={`flag ${flagClass}`}>{severityLabel}</span>
      </td>
      <td>
        <strong>{row.kindLabel}</strong>
        <div className={["muted", stylex.props(viewStyles.site1).className].filter(Boolean).join(" ")} >
          {row.type}
          {row.agentActor ? ` · ${row.agentActor}` : ""}
        </div>
      </td>
      <td>
        <p {...stylex.props(viewStyles.site2)}>{row.rationale}</p>
        {row.requiredAction ? (
          <p
            className={["muted", stylex.props(viewStyles.site3).className].filter(Boolean).join(" ")}

          >
            <strong>Foreslået handling:</strong> {row.requiredAction}
          </p>
        ) : null}
        {row.link ? (
          <p {...stylex.props(viewStyles.site4)}>
            <Link to={`/companies/${slug}/${row.link}`}>
              Åbn relateret side →
            </Link>
          </p>
        ) : null}
      </td>
      <td>
        {row.ruleId ? (
          <code>{row.ruleId}</code>
        ) : (
          <span className="muted">—</span>
        )}
      </td>
      <td>
        <div className="row-actions">
          <Button requiredPermission="company.review"
            type="button"
            className="btn"
            onClick={() => setPending("approve")}
            disabled={busy !== null}
            aria-label={`Godkend ${row.kindLabel}`}
          >
            {busy === "approve" ? "Godkender…" : "Godkend"}
          </Button>
          <Button requiredPermission="company.review" variant="secondary"
            type="button"
            className="btn secondary"
            onClick={() => setPending("reject")}
            disabled={busy !== null}
            aria-label={`Afvis ${row.kindLabel}`}
          >
            {busy === "reject" ? "Afviser…" : "Afvis"}
          </Button>
        </div>
        {pending === "approve" && (
          <ConfirmDialog
            title={`Godkend forslag: ${row.kindLabel}`}
            body={
              <p>
                Forslaget løses som godkendt — du bogfører selv den konkrete
                handling bagefter. Godkendelsen gemmes på revisionssporet.
              </p>
            }
            confirmLabel="Godkend"
            onConfirm={async () => {
              await doApprove();
            }}
            onClose={() => setPending(null)} onRefresh={onChanged}
          />
        )}
        {pending === "reject" && (
          <ConfirmDialog
            title={`Afvis forslag: ${row.kindLabel}`}
            body={
              <p>
                Skriv eventuelt en kort begrundelse — den gemmes på
                revisionssporet, så agenten kan lære af afvisningen. Du kan
                også lade feltet stå tomt.
              </p>
            }
            confirmLabel="Afvis forslag"
            confirmKind="danger"
            noteLabel="Begrundelse (valgfri)"
            notePlaceholder="fx 'ikke et nyt anlæg — direkte i drift'"
            onConfirm={async (note) => {
              await doReject(note);
            }}
            onClose={() => setPending(null)} onRefresh={onChanged}
          />
        )}
      </td>
    </tr>
  );
}

const viewStyles = stylex.create({
site0: { marginTop: "1.5rem" },
site1: { fontSize: "0.85em" },
site2: { margin: 0 },
site3: { margin: "0.25rem 0 0 0", fontSize: "0.9em" },
site4: { margin: "0.25rem 0 0 0", fontSize: "0.9em" }
});

