import { DineroImportPanel } from "../components/DineroImportPanel";
import { OpeningBalancePanel } from "../components/OpeningBalancePanel";
import { useOptionalAuth } from "../lib/auth-context";
import { useMutationOutcome } from "../lib/useMutationOutcome";
import { useUnsavedChanges } from "../lib/useUnsavedChanges";
import * as stylex from "@stylexjs/stylex";
import { ButtonLink, Button, Input, PageHeader, Select } from "../components/ui";
// Company management — rename the display name, sync CVR stamdata, and
// archive/restore.
//
// Strictly non-destructive: there is intentionally no delete of ledger data.
// Archiving only flips a manifest flag; the ledger stays on disk untouched.

import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { api, ApiError } from "../lib/api";
import { useAsync } from "../lib/useAsync";
import { formatDateDa } from "../lib/format";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { AccountantExportCard } from "../components/AccountantExportCard";
import { ConfirmDialog } from "../components/ConfirmDialog";
import type {
  CompanyEntry,
  CompanySettings,
  VatPeriodType,
} from "../lib/types";

// #UI-3 — the cockpit serves no /docs/* routes, so the old `/docs/cvr-opsaetning`
// link was a dead end. CVR-login setup is covered by the public installation
// guide; link there with an absolute URL, matching HelpView's DOCS_BASE pattern.
const CVR_SETUP_GUIDE_URL = "https://rentemester.dk/docs/installation";

/**
 * VAT-cadence options for the profile selector (#300). `"none"` is the
 * form-level sentinel for a NOT VAT-registered company; it is submitted to the
 * PATCH-profile endpoint as `null`, which deregisters the company. Without this
 * option an owner of a non-registered holding ApS could never keep — and would
 * silently re-register on — the not-registered state when saving the profile.
 */
const VAT_PERIOD_OPTIONS: Array<{ value: VatPeriodType | "none"; label: string }> = [
  { value: "month", label: "Måned (måneds-moms)" },
  { value: "quarter", label: "Kvartal (kvartals-moms)" },
  { value: "half-year", label: "Halvår (halvårs-moms)" },
  { value: "none", label: "Ikke momsregistreret" },
];

export function ManageCompanyView() {
  const { slug = "" } = useParams();
  const navigate = useNavigate();
  const state = useAsync(async (signal) => {
    const companies = await api.companies({ signal });
    const found = companies.find((c) => c.slug === slug);
    if (!found) throw new ApiError("not_found", "Virksomheden findes ikke.", 404);
    const settings = await api.companySettings(slug, { signal });
    return { found, settings };
  }, [slug]);

  if (state.loading && !state.data) return <Loading />;
  if (state.error && !state.data)
    return <ErrorState message={state.error} onRetry={state.reload} />;

  return (
    <ManageForm
      onRefresh={state.reload}
      company={state.data!.found}
      settings={state.data!.settings}
      onArchivedAway={() => navigate("/")}
    />
  );
}

function ManageForm({
  onRefresh,
  company,
  settings,
  onArchivedAway,
}: {
  onRefresh: () => void;
  company: CompanyEntry;
  settings: CompanySettings;
  onArchivedAway: () => void;
}) {
  const native = useOptionalAuth()?.backend === "rust";
  const [name, setName] = useState(company.name);
  // Local mirrors of the persisted state, so the form stays consistent after a
  // save without re-fetching (a re-fetch would unmount this form mid-notice).
  const [savedName, setSavedName] = useState(company.name);
  const [archived, setArchived] = useState(company.archived);
  // #UI-17 — archiving navigates the owner away from this view, so it must not
  // fire on a single stray click. Gate it behind a confirm dialog. (Restoring
  // is non-destructive and stays on the page, so it stays one-click.)
  const [confirmingArchive, setConfirmingArchive] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const renameDisabled =
    busy || name.trim().length === 0 || name.trim() === savedName;

  const outcome = useMutationOutcome(onRefresh);
  useUnsavedChanges(name.trim() !== savedName.trim());

  async function rename(e: React.FormEvent) {
    e.preventDefault();
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      const updated = await api.updateCompany(company.slug, {
        name: name.trim(),
      }).catch(outcome.reject);
      setSavedName(updated.name);
      setName(updated.name);
      setNotice("Visningsnavn opdateret.");
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Kunne ikke gemme navnet.");
    } finally {
      setBusy(false);
    }
  }

  // Restoring is non-destructive and keeps the owner on the page — one click.
  async function restoreCompany() {
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      await api.updateCompany(company.slug, { archived: false }).catch(outcome.reject);
      setArchived(false);
      setNotice("Virksomheden er gendannet.");
    } catch (err) {
      setError(
        err instanceof ApiError ? err.message : "Kunne ikke ændre arkivstatus.",
      );
    } finally {
      setBusy(false);
    }
  }

  // #UI-17 — archiving runs from the confirm dialog. It rejects on failure so
  // the dialog surfaces the error (and the backup-lock conflict) inline rather
  // than navigating away on a half-finished write.
  async function confirmArchive() {
    await api.updateCompany(company.slug, { archived: true }).catch(outcome.reject);
    onArchivedAway();
  }

  return (
    <section>
    {outcome.feedback}
      <PageHeader title="Virksomhedsoplysninger" actions={<><ButtonLink className="btn secondary" to={`/companies/${company.slug}`}>
          Tilbage til regnskab
        </ButtonLink></>}>
        <div>

          <p className="muted">
            Slug <code>{company.slug}</code> · oprettet{" "}
            {formatDateDa(company.createdAt.slice(0, 10))}
            {archived ? " · arkiveret" : ""}
          </p>
        </div>

      </PageHeader>

      {error && <Banner kind="error">{error}</Banner>}
      {notice && <Banner kind="success">{notice}</Banner>}

      <form className="form" onSubmit={rename} aria-label="Omdøb virksomhed">
        <label>
          Visningsnavn
          <Input disabled={outcome.blocked}
            name="name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <span className="field-hint">
            Ændrer kun det viste navn — slug og regnskabsdata berøres ikke.
          </span>
        </label>
        <div className="row-actions">
          <Button requiredPermission="company.admin" className="btn" type="submit" disabled={outcome.blocked || (renameDisabled)}>
            Gem navn
          </Button>
        </div>
      </form>

      <DineroImportPanel slug={company.slug} />
      <ProfileCard slug={company.slug} initial={settings} />

      <CvrCard slug={company.slug} initial={settings} />

      {native && <OpeningBalancePanel slug={company.slug} />}

      <AccountantExportCard slug={company.slug} />

      <div className={["card", stylex.props(viewStyles.site0).className].filter(Boolean).join(" ")} >
        <h3 {...stylex.props(viewStyles.site1)}>
          {archived ? "Gendan virksomhed" : "Arkivér virksomhed"}
        </h3>
        <p className="muted">
          {archived
            ? "Virksomheden er arkiveret. Gendan den for at vise den i porteføljen igen."
            : "Arkivering skjuler virksomheden fra den aktive portefølje. Regnskabsdata slettes aldrig og kan gendannes."}
        </p>
        <Button requiredPermission="company.admin" variant="secondary"
          className="btn secondary"
          type="button"
          onClick={
            archived ? restoreCompany : () => setConfirmingArchive(true)
          }
          disabled={outcome.blocked || (busy)}
        >
          {archived ? "Gendan virksomhed" : "Arkivér virksomhed"}
        </Button>
      </div>

      {confirmingArchive && (
        <ConfirmDialog
          title="Arkivér virksomhed"
          body={
            <p>
              Arkivér <strong>{savedName}</strong>? Virksomheden skjules fra den
              aktive portefølje, og du sendes tilbage til oversigten.
              Regnskabsdata slettes aldrig og kan gendannes herfra igen.
            </p>
          }
          confirmLabel="Arkivér virksomhed"
          confirmKind="danger"
          onConfirm={confirmArchive}
          onClose={() => setConfirmingArchive(false)} onRefresh={onRefresh}
        />
      )}
    </section>
  );
}

/**
 * The editable company profile + bank-details card (#284).
 *
 * A Cockpit owner must be able to record the company's own postal address,
 * default payment terms and — critically — its bank account. Without a bank
 * account every issued invoice goes out with no payment instructions, so the
 * card warns prominently when none is configured. Saving calls the same
 * `setCompanyProfile` core function the CLI's `company profile` command uses.
 */
function ProfileCard({
  slug,
  initial,
}: {
  slug: string;
  initial: CompanySettings;
}) {
  const [settings, setSettings] = useState(initial);
  const [cvr, setCvr] = useState(initial.cvr ?? "");
  const [address, setAddress] = useState(initial.address ?? "");
  const [postalCode, setPostalCode] = useState(initial.postalCode ?? "");
  const [city, setCity] = useState(initial.city ?? "");
  // #300: the VAT settlement cadence is editable from the cockpit, including
  // turning registration OFF (`"none"` → submitted as `null`). Initialise the
  // form state from `initial.vatPeriodType` so a not-VAT-registered company
  // (null) shows "Ikke momsregistreret" selected — defaulting to `quarter`
  // here would silently re-register the company on the next profile save.
  const [vatPeriodType, setVatPeriodType] = useState<VatPeriodType | "none">(
    initial.vatPeriodType ?? "none",
  );
  const [bankName, setBankName] = useState(initial.payment?.bankName ?? "");
  const [registrationNo, setRegistrationNo] = useState(
    initial.payment?.registrationNo ?? "",
  );
  const [accountNo, setAccountNo] = useState(
    initial.payment?.accountNo ?? "",
  );
  const [iban, setIban] = useState(initial.payment?.iban ?? "");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const hasPayment = Boolean(
    settings.payment &&
      (settings.payment.bankName ||
        settings.payment.registrationNo ||
        settings.payment.accountNo ||
        settings.payment.iban),
  );

  const outcome = useMutationOutcome(async () => { await api.companySettings(slug); setNotice("Gemte stamdata er hentet. Indtastningerne i formularen er bevaret."); });
  useUnsavedChanges(cvr.trim() !== (settings.cvr ?? "") || address.trim() !== (settings.address ?? "") || postalCode.trim() !== (settings.postalCode ?? "") || city.trim() !== (settings.city ?? "") || vatPeriodType !== (settings.vatPeriodType ?? "none") || bankName.trim() !== (settings.payment?.bankName ?? "") || registrationNo.trim() !== (settings.payment?.registrationNo ?? "") || accountNo.trim() !== (settings.payment?.accountNo ?? "") || iban.trim() !== (settings.payment?.iban ?? ""));

  async function save(e: React.FormEvent) {
    e.preventDefault();
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      const updated = await api.updateCompanyProfile(slug, {
        cvr: cvr.trim(),
        address: address.trim(),
        postalCode: postalCode.trim(),
        city: city.trim(),
        // `"none"` → null so the server deregisters the company; a real
        // cadence is sent verbatim.
        vatPeriodType: vatPeriodType === "none" ? null : vatPeriodType,
        payment: {
          bankName: bankName.trim(),
          registrationNo: registrationNo.trim(),
          accountNo: accountNo.trim(),
          iban: iban.trim(),
        },
      }).catch(outcome.reject);
      setSettings(updated);
      setCvr(updated.cvr ?? "");
      setVatPeriodType(updated.vatPeriodType ?? "none");
      setNotice("Stamdata opdateret.");
    } catch (err) {
      setError(
        err instanceof ApiError
          ? err.message
          : "Kunne ikke gemme stamdata.",
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className={["card", stylex.props(viewStyles.site2).className].filter(Boolean).join(" ")} >
    {outcome.feedback}
      <h3 {...stylex.props(viewStyles.site3)}>Stamdata og bankoplysninger</h3>
      <p className="muted">
        Virksomhedens egen adresse og bankkonto. Bankkontoen vises som
        betalingsoplysninger på alle fakturaer du udsteder.
      </p>

      {error && <Banner kind="error">{error}</Banner>}
      {notice && <Banner kind="success">{notice}</Banner>}
      {!hasPayment && (
        <Banner kind="warning">
          Der er ingen bankkonto registreret. Fakturaer udstedes uden
          betalingsoplysninger, indtil du tilføjer en konto her.
        </Banner>
      )}

      <form className="form" onSubmit={save} aria-label="Rediger stamdata">
        <label>
          CVR-nummer
          <Input disabled={outcome.blocked}
            name="cvr"
            value={cvr}
            onChange={(e) => setCvr(e.target.value)}
            inputMode="numeric"
            placeholder="12345678"
          />
        </label>
        <label>
          Adresse
          <Input disabled={outcome.blocked}
            name="address"
            value={address}
            onChange={(e) => setAddress(e.target.value)}
            placeholder="Vej 1"
          />
        </label>
        <label>
          Postnummer
          <Input disabled={outcome.blocked}
            name="postalCode"
            value={postalCode}
            onChange={(e) => setPostalCode(e.target.value)}
            placeholder="1000"
          />
        </label>
        <label>
          By
          <Input disabled={outcome.blocked}
            name="city"
            value={city}
            onChange={(e) => setCity(e.target.value)}
            placeholder="København"
          />
        </label>
        <label>
          Momsperiode
          <Select disabled={outcome.blocked}
            name="vatPeriodType"
            value={vatPeriodType}
            onChange={(e) =>
              setVatPeriodType(e.target.value as VatPeriodType | "none")
            }
          >
            {VAT_PERIOD_OPTIONS.map((o) => (
              <option key={o.value} value={o.value}>
                {o.label}
              </option>
            ))}
          </Select>
          <span className="field-hint">
            Den momsperiode virksomheden er registreret for hos SKAT.
            Momsperioder og -frister følger dette valg. Vælg «Ikke
            momsregistreret» for en virksomhed uden momsregistrering (fx
            holdingselskab) — momsfrister og momsangivelse slås så fra.
          </span>
        </label>
        <label>
          Pengeinstitut
          <Input disabled={outcome.blocked}
            name="bankName"
            value={bankName}
            onChange={(e) => setBankName(e.target.value)}
            placeholder="Danske Bank"
          />
        </label>
        <label>
          Registreringsnummer
          <Input disabled={outcome.blocked}
            name="registrationNo"
            value={registrationNo}
            onChange={(e) => setRegistrationNo(e.target.value)}
            placeholder="1234"
          />
        </label>
        <label>
          Kontonummer
          <Input disabled={outcome.blocked}
            name="accountNo"
            value={accountNo}
            onChange={(e) => setAccountNo(e.target.value)}
            placeholder="0001234567"
          />
        </label>
        <label>
          IBAN (valgfrit)
          <Input disabled={outcome.blocked}
            name="iban"
            value={iban}
            onChange={(e) => setIban(e.target.value)}
            placeholder="DK0000000000000000"
          />
          <span className="field-hint">
            Bruges til betalinger fra udlandet.
          </span>
        </label>
        <div className="row-actions">
          <Button requiredPermission="company.admin" className="btn" type="submit" disabled={outcome.blocked || (busy)}>
            {busy ? "Gemmer…" : "Gem stamdata"}
          </Button>
        </div>
      </form>
    </div>
  );
}

/**
 * The CVR-stamdata card: shows the company's registered address / branche /
 * status and a "Hent fra CVR" button that refreshes it from the CVR register.
 * The lookup runs server-side, so the CVR credentials never reach the browser.
 */
function CvrCard({ slug, initial }: { slug: string; initial: CompanySettings }) {
  const [settings, setSettings] = useState(initial);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [fiscalWarning, setFiscalWarning] = useState<string | null>(null);
  // #402 — `null` = "we haven't checked yet", so we don't flicker the
  // "CVR-login mangler"-banner during the initial fetch.
  const [cvrLoginConfigured, setCvrLoginConfigured] = useState<boolean | null>(
    null,
  );

  const hasCvr = Boolean(settings.cvr);
  const loginMissing = cvrLoginConfigured === false;

  // #402 — find out if the server has CVR_USERNAME / CVR_PASSWORD before the
  // owner clicks anything. An owner who lacks the login should *see* that fact
  // — and the path to fix it — instead of clicking a button that throws a raw
  // 401 their way and leaves them guessing.
  useEffect(() => {
    let cancelled = false;
    api
      .cvrStatus()
      .then((status) => {
        if (!cancelled) setCvrLoginConfigured(status.configured);
      })
      .catch(() => {
        // A failure to *check* status shouldn't block the owner from trying —
        // treat it as "unknown" and let the sync call surface any real issue.
        if (!cancelled) setCvrLoginConfigured(null);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const outcome = useMutationOutcome(async () => { await api.companySettings(slug); setNotice("Gemte CVR-oplysninger er hentet. Kontrollér oplysningerne ved næste åbning af formularen."); });
  async function sync() {
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    setFiscalWarning(null);
    try {
      const result = await api.syncCvr(slug).catch(outcome.reject);
      if (!result.ok) {
        setError(translateCvrError(result.errors[0]));
        return;
      }
      const fresh = await api.companySettings(slug);
      setSettings(fresh);
      const changed = result.updatedFields ?? [];
      setNotice(
        changed.length > 0
          ? `Hentet fra CVR. Opdaterede felter: ${changed.join(", ")}.`
          : "Hentet fra CVR. Stamdata var allerede opdateret.",
      );
      const fy = result.fiscalYearStartMonth;
      if (fy && !fy.matches && fy.cvr !== null) {
        setFiscalWarning(
          `CVR har regnskabsår der starter i måned ${fy.cvr}, men virksomheden ` +
            `er sat op med måned ${fy.current}. Regnskabsåret ændres aldrig ` +
            `automatisk — ret det manuelt hvis det er forkert.`,
        );
      }
    } catch (err) {
      setError(
        err instanceof ApiError
          ? translateCvrError(err.message)
          : "Kunne ikke hente fra CVR.",
      );
    } finally {
      setBusy(false);
    }
  }

  const buttonDisabled = busy || !hasCvr || loginMissing;
  const buttonTitle = loginMissing
    ? "CVR-login mangler på serveren — se forklaringen ovenfor."
    : !hasCvr
      ? "Tilføj først et CVR-nummer på virksomheden."
      : undefined;

  return (
    <div className={["card", stylex.props(viewStyles.site4).className].filter(Boolean).join(" ")} >
    {outcome.feedback}
      <h3 {...stylex.props(viewStyles.site5)}>CVR-stamdata</h3>

      {error && <Banner kind="error">{error}</Banner>}
      {notice && <Banner kind="success">{notice}</Banner>}
      {fiscalWarning && <Banner kind="warning">{fiscalWarning}</Banner>}

      {/*
        #402 — Owner-facing explanation when the server has no virk.dk-login.
        We say *what* is missing and *how* to fix it, in plain Danish, without
        sending the owner to the terminal for an environment variable they
        won't recognise.
      */}
      {loginMissing && (
        <Banner kind="warning">
          Cockpittet mangler dit virk.dk-login. Indtil det er sat op, kan
          stamdata ikke hentes automatisk fra CVR. Se{" "}
          <a
            href={CVR_SETUP_GUIDE_URL}
            target="_blank"
            rel="noreferrer noopener"
          >
            installationsguiden
          </a>{" "}
          for hvordan du konfigurerer det.
        </Banner>
      )}

      {!hasCvr && (
        <p className="muted">
          Der er ikke registreret et CVR-nummer på virksomheden. Tilføj et
          CVR-nummer for at kunne hente stamdata fra CVR-registret.
        </p>
      )}

      {hasCvr && (
        <dl className="cvr-facts">
          <Fact label="CVR-nummer" value={settings.cvr} />
          <Fact label="Adresse" value={cvrAddressLine(settings)} />
          <Fact label="Virksomhedsform" value={settings.companyForm} />
          <Fact
            label="Branche"
            value={
              settings.industryText && settings.industryCode
                ? `${settings.industryCode} — ${settings.industryText}`
                : settings.industryText
            }
          />
          <Fact label="Status" value={settings.cvrStatus} />
          <Fact
            label="Revision fravalgt"
            value={
              settings.auditWaived === null
                ? null
                : settings.auditWaived
                  ? "Ja"
                  : "Nej"
            }
          />
          <Fact
            label="Sidst hentet"
            value={
              settings.cvrSyncedAt
                ? formatDateDa(settings.cvrSyncedAt.slice(0, 10))
                : "Aldrig"
            }
          />
        </dl>
      )}

      <Button requiredPermission="company.external-lookup" variant="secondary"
        className="btn secondary"
        type="button"
        onClick={sync}
        disabled={buttonDisabled}
        title={buttonTitle}
      >
        {busy ? "Henter…" : "Hent fra CVR"}
      </Button>
      <p className="field-hint">
        Kræver dit virk.dk-login. Konfigurér det én gang under CVR-login —{" "}
        regnskabsåret ændres aldrig automatisk.
      </p>
    </div>
  );
}

/**
 * #402 — Map raw CVR-register error messages to something an owner can act
 * on. The CVR core surfaces "kræver miljøvariablerne CVR_USERNAME og
 * CVR_PASSWORD" when credentials are missing; that's developer-speak, so we
 * translate it into a plain-Danish call to action. Everything else passes
 * through verbatim.
 */
function translateCvrError(raw: string | undefined): string {
  const fallback = "CVR-opslaget mislykkedes.";
  if (!raw) return fallback;
  const lower = raw.toLowerCase();
  if (
    lower.includes("cvr_username") ||
    lower.includes("cvr_password") ||
    lower.includes("http 401")
  ) {
    return (
      "Cockpittet mangler CVR-login. Konfigurér dit virk.dk-login (se " +
      "installationsguiden på rentemester.dk/docs/installation) og prøv igen."
    );
  }
  return raw;
}

function Fact({ label, value }: { label: string; value: string | null | undefined }) {
  return (
    <div className="cvr-fact">
      <dt className="muted">{label}</dt>
      <dd>{value && value.length > 0 ? value : "—"}</dd>
    </div>
  );
}

function cvrAddressLine(settings: CompanySettings): string | null {
  const cityLine = [settings.postalCode, settings.city].filter(Boolean).join(" ");
  const full = [settings.address, cityLine].filter((p) => p && p.length > 0).join(", ");
  return full.length > 0 ? full : null;
}

const viewStyles = stylex.create({
site0: { marginTop: 24, maxWidth: 460 },
site1: { marginTop: 0 },
site2: { marginTop: 24, maxWidth: 460 },
site3: { marginTop: 0 },
site4: { marginTop: 24, maxWidth: 460 },
site5: { marginTop: 0 }
});

renderingAndEffects.viewTypeScript:
import { DineroImportPanel } from "../components/DineroImportPanel";
import { OpeningBalancePanel } from "../components/OpeningBalancePanel";
import { useOptionalAuth } from "../lib/auth-context";
import { useMutationOutcome } from "../lib/useMutationOutcome";
import { useUnsavedChanges } from "../lib/useUnsavedChanges";
import * as stylex from "@stylexjs/stylex";
import { ButtonLink, Button, Input, PageHeader, Select } from "../components/ui";
// Company management — rename the display name, sync CVR stamdata, and
// archive/restore.
//
// Strictly non-destructive: there is intentionally no delete of ledger data.
// Archiving only flips a manifest flag; the ledger stays on disk untouched.

import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { api, ApiError } from "../lib/api";
import { useAsync } from "../lib/useAsync";
import { formatDateDa } from "../lib/format";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { AccountantExportCard } from "../components/AccountantExportCard";
import { ConfirmDialog } from "../components/ConfirmDialog";
import type {
  CompanyEntry,
  CompanySettings,
  VatPeriodType,
} from "../lib/types";

// #UI-3 — the cockpit serves no /docs/* routes, so the old `/docs/cvr-opsaetning`
// link was a dead end. CVR-login setup is covered by the public installation
// guide; link there with an absolute URL, matching HelpView's DOCS_BASE pattern.
const CVR_SETUP_GUIDE_URL = "https://rentemester.dk/docs/installation";

/**
 * VAT-cadence options for the profile selector (#300). `"none"` is the
 * form-level sentinel for a NOT VAT-registered company; it is submitted to the
 * PATCH-profile endpoint as `null`, which deregisters the company. Without this
 * option an owner of a non-registered holding ApS could never keep — and would
 * silently re-register on — the not-registered state when saving the profile.
 */
const VAT_PERIOD_OPTIONS: Array<{ value: VatPeriodType | "none"; label: string }> = [
  { value: "month", label: "Måned (måneds-moms)" },
  { value: "quarter", label: "Kvartal (kvartals-moms)" },
  { value: "half-year", label: "Halvår (halvårs-moms)" },
  { value: "none", label: "Ikke momsregistreret" },
];

export function ManageCompanyView() {
  const { slug = "" } = useParams();
  const navigate = useNavigate();
  const state = useAsync(async (signal) => {
    const companies = await api.companies({ signal });
    const found = companies.find((c) => c.slug === slug);
    if (!found) throw new ApiError("not_found", "Virksomheden findes ikke.", 404);
    const settings = await api.companySettings(slug, { signal });
    return { found, settings };
  }, [slug]);

  if (state.loading && !state.data) return <Loading />;
  if (state.error && !state.data)
    return <ErrorState message={state.error} onRetry={state.reload} />;

  return (
    <ManageForm
      onRefresh={state.reload}
      company={state.data!.found}
      settings={state.data!.settings}
      onArchivedAway={() => navigate("/")}
    />
  );
}

function ManageForm({
  onRefresh,
  company,
  settings,
  onArchivedAway,
}: {
  onRefresh: () => void;
  company: CompanyEntry;
  settings: CompanySettings;
  onArchivedAway: () => void;
}) {
  const native = useOptionalAuth()?.backend === "rust";
  const [name, setName] = useState(company.name);
  // Local mirrors of the persisted state, so the form stays consistent after a
  // save without re-fetching (a re-fetch would unmount this form mid-notice).
  const [savedName, setSavedName] = useState(company.name);
  const [archived, setArchived] = useState(company.archived);
  // #UI-17 — archiving navigates the owner away from this view, so it must not
  // fire on a single stray click. Gate it behind a confirm dialog. (Restoring
  // is non-destructive and stays on the page, so it stays one-click.)
  const [confirmingArchive, setConfirmingArchive] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const renameDisabled =
    busy || name.trim().length === 0 || name.trim() === savedName;

  const outcome = useMutationOutcome(onRefresh);
  useUnsavedChanges(name.trim() !== savedName.trim());

  async function rename(e: React.FormEvent) {
    e.preventDefault();
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      const updated = await api.updateCompany(company.slug, {
        name: name.trim(),
      }).catch(outcome.reject);
      setSavedName(updated.name);
      setName(updated.name);
      setNotice("Visningsnavn opdateret.");
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Kunne ikke gemme navnet.");
    } finally {
      setBusy(false);
    }
  }

  // Restoring is non-destructive and keeps the owner on the page — one click.
  async function restoreCompany() {
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      await api.updateCompany(company.slug, { archived: false }).catch(outcome.reject);
      setArchived(false);
      setNotice("Virksomheden er gendannet.");
    } catch (err) {
      setError(
        err instanceof ApiError ? err.message : "Kunne ikke ændre arkivstatus.",
      );
    } finally {
      setBusy(false);
    }
  }

  // #UI-17 — archiving runs from the confirm dialog. It rejects on failure so
  // the dialog surfaces the error (and the backup-lock conflict) inline rather
  // than navigating away on a half-finished write.
  async function confirmArchive() {
    await api.updateCompany(company.slug, { archived: true }).catch(outcome.reject);
    onArchivedAway();
  }

  return (
    <section>
    {outcome.feedback}
      <PageHeader title="Virksomhedsoplysninger" actions={<><ButtonLink className="btn secondary" to={`/companies/${company.slug}`}>
          Tilbage til regnskab
        </ButtonLink></>}>
        <div>

          <p className="muted">
            Slug <code>{company.slug}</code> · oprettet{" "}
            {formatDateDa(company.createdAt.slice(0, 10))}
            {archived ? " · arkiveret" : ""}
          </p>
        </div>

      </PageHeader>

      {error && <Banner kind="error">{error}</Banner>}
      {notice && <Banner kind="success">{notice}</Banner>}

      <form className="form" onSubmit={rename} aria-label="Omdøb virksomhed">
        <label>
          Visningsnavn
          <Input disabled={outcome.blocked}
            name="name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <span className="field-hint">
            Ændrer kun det viste navn — slug og regnskabsdata berøres ikke.
          </span>
        </label>
        <div className="row-actions">
          <Button requiredPermission="company.admin" className="btn" type="submit" disabled={outcome.blocked || (renameDisabled)}>
            Gem navn
          </Button>
        </div>
      </form>

      <DineroImportPanel slug={company.slug} />
      <ProfileCard slug={company.slug} initial={settings} />

      <CvrCard slug={company.slug} initial={settings} />

      {native && <OpeningBalancePanel slug={company.slug} />}

      <AccountantExportCard slug={company.slug} />

      <div className={["card", stylex.props(viewStyles.site0).className].filter(Boolean).join(" ")} >
        <h3 {...stylex.props(viewStyles.site1)}>
          {archived ? "Gendan virksomhed" : "Arkivér virksomhed"}
        </h3>
        <p className="muted">
          {archived
            ? "Virksomheden er arkiveret. Gendan den for at vise den i porteføljen igen."
            : "Arkivering skjuler virksomheden fra den aktive portefølje. Regnskabsdata slettes aldrig og kan gendannes."}
        </p>
        <Button requiredPermission="company.admin" variant="secondary"
          className="btn secondary"
          type="button"
          onClick={
            archived ? restoreCompany : () => setConfirmingArchive(true)
          }
          disabled={outcome.blocked || (busy)}
        >
          {archived ? "Gendan virksomhed" : "Arkivér virksomhed"}
        </Button>
      </div>

      {confirmingArchive && (
        <ConfirmDialog
          title="Arkivér virksomhed"
          body={
            <p>
              Arkivér <strong>{savedName}</strong>? Virksomheden skjules fra den
              aktive portefølje, og du sendes tilbage til oversigten.
              Regnskabsdata slettes aldrig og kan gendannes herfra igen.
            </p>
          }
          confirmLabel="Arkivér virksomhed"
          confirmKind="danger"
          onConfirm={confirmArchive}
          onClose={() => setConfirmingArchive(false)} onRefresh={onRefresh}
        />
      )}
    </section>
  );
}

/**
 * The editable company profile + bank-details card (#284).
 *
 * A Cockpit owner must be able to record the company's own postal address,
 * default payment terms and — critically — its bank account. Without a bank
 * account every issued invoice goes out with no payment instructions, so the
 * card warns prominently when none is configured. Saving calls the same
 * `setCompanyProfile` core function the CLI's `company profile` command uses.
 */
function ProfileCard({
  slug,
  initial,
}: {
  slug: string;
  initial: CompanySettings;
}) {
  const [settings, setSettings] = useState(initial);
  const [cvr, setCvr] = useState(initial.cvr ?? "");
  const [address, setAddress] = useState(initial.address ?? "");
  const [postalCode, setPostalCode] = useState(initial.postalCode ?? "");
  const [city, setCity] = useState(initial.city ?? "");
  // #300: the VAT settlement cadence is editable from the cockpit, including
  // turning registration OFF (`"none"` → submitted as `null`). Initialise the
  // form state from `initial.vatPeriodType` so a not-VAT-registered company
  // (null) shows "Ikke momsregistreret" selected — defaulting to `quarter`
  // here would silently re-register the company on the next profile save.
  const [vatPeriodType, setVatPeriodType] = useState<VatPeriodType | "none">(
    initial.vatPeriodType ?? "none",
  );
  const [bankName, setBankName] = useState(initial.payment?.bankName ?? "");
  const [registrationNo, setRegistrationNo] = useState(
    initial.payment?.registrationNo ?? "",
  );
  const [accountNo, setAccountNo] = useState(
    initial.payment?.accountNo ?? "",
  );
  const [iban, setIban] = useState(initial.payment?.iban ?? "");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const hasPayment = Boolean(
    settings.payment &&
      (settings.payment.bankName ||
        settings.payment.registrationNo ||
        settings.payment.accountNo ||
        settings.payment.iban),
  );

  const outcome = useMutationOutcome(async () => { await api.companySettings(slug); setNotice("Gemte stamdata er hentet. Indtastningerne i formularen er bevaret."); });
  useUnsavedChanges(cvr.trim() !== (settings.cvr ?? "") || address.trim() !== (settings.address ?? "") || postalCode.trim() !== (settings.postalCode ?? "") || city.trim() !== (settings.city ?? "") || vatPeriodType !== (settings.vatPeriodType ?? "none") || bankName.trim() !== (settings.payment?.bankName ?? "") || registrationNo.trim() !== (settings.payment?.registrationNo ?? "") || accountNo.trim() !== (settings.payment?.accountNo ?? "") || iban.trim() !== (settings.payment?.iban ?? ""));

  async function save(e: React.FormEvent) {
    e.preventDefault();
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      const updated = await api.updateCompanyProfile(slug, {
        cvr: cvr.trim(),
        address: address.trim(),
        postalCode: postalCode.trim(),
        city: city.trim(),
        // `"none"` → null so the server deregisters the company; a real
        // cadence is sent verbatim.
        vatPeriodType: vatPeriodType === "none" ? null : vatPeriodType,
        payment: {
          bankName: bankName.trim(),
          registrationNo: registrationNo.trim(),
          accountNo: accountNo.trim(),
          iban: iban.trim(),
        },
      }).catch(outcome.reject);
      setSettings(updated);
      setCvr(updated.cvr ?? "");
      setVatPeriodType(updated.vatPeriodType ?? "none");
      setNotice("Stamdata opdateret.");
    } catch (err) {
      setError(
        err instanceof ApiError
          ? err.message
          : "Kunne ikke gemme stamdata.",
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className={["card", stylex.props(viewStyles.site2).className].filter(Boolean).join(" ")} >
    {outcome.feedback}
      <h3 {...stylex.props(viewStyles.site3)}>Stamdata og bankoplysninger</h3>
      <p className="muted">
        Virksomhedens egen adresse og bankkonto. Bankkontoen vises som
        betalingsoplysninger på alle fakturaer du udsteder.
      </p>

      {error && <Banner kind="error">{error}</Banner>}
      {notice && <Banner kind="success">{notice}</Banner>}
      {!hasPayment && (
        <Banner kind="warning">
          Der er ingen bankkonto registreret. Fakturaer udstedes uden
          betalingsoplysninger, indtil du tilføjer en konto her.
        </Banner>
      )}

      <form className="form" onSubmit={save} aria-label="Rediger stamdata">
        <label>
          CVR-nummer
          <Input disabled={outcome.blocked}
            name="cvr"
            value={cvr}
            onChange={(e) => setCvr(e.target.value)}
            inputMode="numeric"
            placeholder="12345678"
          />
        </label>
        <label>
          Adresse
          <Input disabled={outcome.blocked}
            name="address"
            value={address}
            onChange={(e) => setAddress(e.target.value)}
            placeholder="Vej 1"
          />
        </label>
        <label>
          Postnummer
          <Input disabled={outcome.blocked}
            name="postalCode"
            value={postalCode}
            onChange={(e) => setPostalCode(e.target.value)}
            placeholder="1000"
          />
        </label>
        <label>
          By
          <Input disabled={outcome.blocked}
            name="city"
            value={city}
            onChange={(e) => setCity(e.target.value)}
            placeholder="København"
          />
        </label>
        <label>
          Momsperiode
          <Select disabled={outcome.blocked}
            name="vatPeriodType"
            value={vatPeriodType}
            onChange={(e) =>
              setVatPeriodType(e.target.value as VatPeriodType | "none")
            }
          >
            {VAT_PERIOD_OPTIONS.map((o) => (
              <option key={o.value} value={o.value}>
                {o.label}
              </option>
            ))}
          </Select>
          <span className="field-hint">
            Den momsperiode virksomheden er registreret for hos SKAT.
            Momsperioder og -frister følger dette valg. Vælg «Ikke
            momsregistreret» for en virksomhed uden momsregistrering (fx
            holdingselskab) — momsfrister og momsangivelse slås så fra.
          </span>
        </label>
        <label>
          Pengeinstitut
          <Input disabled={outcome.blocked}
            name="bankName"
            value={bankName}
            onChange={(e) => setBankName(e.target.value)}
            placeholder="Danske Bank"
          />
        </label>
        <label>
          Registreringsnummer
          <Input disabled={outcome.blocked}
            name="registrationNo"
            value={registrationNo}
            onChange={(e) => setRegistrationNo(e.target.value)}
            placeholder="1234"
          />
        </label>
        <label>
          Kontonummer
          <Input disabled={outcome.blocked}
            name="accountNo"
            value={accountNo}
            onChange={(e) => setAccountNo(e.target.value)}
            placeholder="0001234567"
          />
        </label>
        <label>
          IBAN (valgfrit)
          <Input disabled={outcome.blocked}
            name="iban"
            value={iban}
            onChange={(e) => setIban(e.target.value)}
            placeholder="DK0000000000000000"
          />
          <span className="field-hint">
            Bruges til betalinger fra udlandet.
          </span>
        </label>
        <div className="row-actions">
          <Button requiredPermission="company.admin" className="btn" type="submit" disabled={outcome.blocked || (busy)}>
            {busy ? "Gemmer…" : "Gem stamdata"}
          </Button>
        </div>
      </form>
    </div>
  );
}

/**
 * The CVR-stamdata card: shows the company's registered address / branche /
 * status and a "Hent fra CVR" button that refreshes it from the CVR register.
 * The lookup runs server-side, so the CVR credentials never reach the browser.
 */
function CvrCard({ slug, initial }: { slug: string; initial: CompanySettings }) {
  const [settings, setSettings] = useState(initial);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [fiscalWarning, setFiscalWarning] = useState<string | null>(null);
  // #402 — `null` = "we haven't checked yet", so we don't flicker the
  // "CVR-login mangler"-banner during the initial fetch.
  const [cvrLoginConfigured, setCvrLoginConfigured] = useState<boolean | null>(
    null,
  );

  const hasCvr = Boolean(settings.cvr);
  const loginMissing = cvrLoginConfigured === false;

  // #402 — find out if the server has CVR_USERNAME / CVR_PASSWORD before the
  // owner clicks anything. An owner who lacks the login should *see* that fact
  // — and the path to fix it — instead of clicking a button that throws a raw
  // 401 their way and leaves them guessing.
  useEffect(() => {
    let cancelled = false;
    api
      .cvrStatus()
      .then((status) => {
        if (!cancelled) setCvrLoginConfigured(status.configured);
      })
      .catch(() => {
        // A failure to *check* status shouldn't block the owner from trying —
        // treat it as "unknown" and let the sync call surface any real issue.
        if (!cancelled) setCvrLoginConfigured(null);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const outcome = useMutationOutcome(async () => { await api.companySettings(slug); setNotice("Gemte CVR-oplysninger er hentet. Kontrollér oplysningerne ved næste åbning af formularen."); });
  async function sync() {
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    setFiscalWarning(null);
    try {
      const result = await api.syncCvr(slug).catch(outcome.reject);
      if (!result.ok) {
        setError(translateCvrError(result.errors[0]));
        return;
      }
      const fresh = await api.companySettings(slug);
      setSettings(fresh);
      const changed = result.updatedFields ?? [];
      setNotice(
        changed.length > 0
          ? `Hentet fra CVR. Opdaterede felter: ${changed.join(", ")}.`
          : "Hentet fra CVR. Stamdata var allerede opdateret.",
      );
      const fy = result.fiscalYearStartMonth;
      if (fy && !fy.matches && fy.cvr !== null) {
        setFiscalWarning(
          `CVR har regnskabsår der starter i måned ${fy.cvr}, men virksomheden ` +
            `er sat op med måned ${fy.current}. Regnskabsåret ændres aldrig ` +
            `automatisk — ret det manuelt hvis det er forkert.`,
        );
      }
    } catch (err) {
      setError(
        err instanceof ApiError
          ? translateCvrError(err.message)
          : "Kunne ikke hente fra CVR.",
      );
    } finally {
      setBusy(false);
    }
  }

  const buttonDisabled = busy || !hasCvr || loginMissing;
  const buttonTitle = loginMissing
    ? "CVR-login mangler på serveren — se forklaringen ovenfor."
    : !hasCvr
      ? "Tilføj først et CVR-nummer på virksomheden."
      : undefined;

  return (
    <div className={["card", stylex.props(viewStyles.site4).className].filter(Boolean).join(" ")} >
    {outcome.feedback}
      <h3 {...stylex.props(viewStyles.site5)}>CVR-stamdata</h3>

      {error && <Banner kind="error">{error}</Banner>}
      {notice && <Banner kind="success">{notice}</Banner>}
      {fiscalWarning && <Banner kind="warning">{fiscalWarning}</Banner>}

      {/*
        #402 — Owner-facing explanation when the server has no virk.dk-login.
        We say *what* is missing and *how* to fix it, in plain Danish, without
        sending the owner to the terminal for an environment variable they
        won't recognise.
      */}
      {loginMissing && (
        <Banner kind="warning">
          Cockpittet mangler dit virk.dk-login. Indtil det er sat op, kan
          stamdata ikke hentes automatisk fra CVR. Se{" "}
          <a
            href={CVR_SETUP_GUIDE_URL}
            target="_blank"
            rel="noreferrer noopener"
          >
            installationsguiden
          </a>{" "}
          for hvordan du konfigurerer det.
        </Banner>
      )}

      {!hasCvr && (
        <p className="muted">
          Der er ikke registreret et CVR-nummer på virksomheden. Tilføj et
          CVR-nummer for at kunne hente stamdata fra CVR-registret.
        </p>
      )}

      {hasCvr && (
        <dl className="cvr-facts">
          <Fact label="CVR-nummer" value={settings.cvr} />
          <Fact label="Adresse" value={cvrAddressLine(settings)} />
          <Fact label="Virksomhedsform" value={settings.companyForm} />
          <Fact
            label="Branche"
            value={
              settings.industryText && settings.industryCode
                ? `${settings.industryCode} — ${settings.industryText}`
                : settings.industryText
            }
          />
          <Fact label="Status" value={settings.cvrStatus} />
          <Fact
            label="Revision fravalgt"
            value={
              settings.auditWaived === null
                ? null
                : settings.auditWaived
                  ? "Ja"
                  : "Nej"
            }
          />
          <Fact
            label="Sidst hentet"
            value={
              settings.cvrSyncedAt
                ? formatDateDa(settings.cvrSyncedAt.slice(0, 10))
                : "Aldrig"
            }
          />
        </dl>
      )}

      <Button requiredPermission="company.external-lookup" variant="secondary"
        className="btn secondary"
        type="button"
        onClick={sync}
        disabled={buttonDisabled}
        title={buttonTitle}
      >
        {busy ? "Henter…" : "Hent fra CVR"}
      </Button>
      <p className="field-hint">
        Kræver dit virk.dk-login. Konfigurér det én gang under CVR-login —{" "}
        regnskabsåret ændres aldrig automatisk.
      </p>
    </div>
  );
}

/**
 * #402 — Map raw CVR-register error messages to something an owner can act
 * on. The CVR core surfaces "kræver miljøvariablerne CVR_USERNAME og
 * CVR_PASSWORD" when credentials are missing; that's developer-speak, so we
 * translate it into a plain-Danish call to action. Everything else passes
 * through verbatim.
 */
function translateCvrError(raw: string | undefined): string {
  const fallback = "CVR-opslaget mislykkedes.";
  if (!raw) return fallback;
  const lower = raw.toLowerCase();
  if (
    lower.includes("cvr_username") ||
    lower.includes("cvr_password") ||
    lower.includes("http 401")
  ) {
    return (
      "Cockpittet mangler CVR-login. Konfigurér dit virk.dk-login (se " +
      "installationsguiden på rentemester.dk/docs/installation) og prøv igen."
    );
  }
  return raw;
}

function Fact({ label, value }: { label: string; value: string | null | undefined }) {
  return (
    <div className="cvr-fact">
      <dt className="muted">{label}</dt>
      <dd>{value && value.length > 0 ? value : "—"}</dd>
    </div>
  );
}

function cvrAddressLine(settings: CompanySettings): string | null {
  const cityLine = [settings.postalCode, settings.city].filter(Boolean).join(" ");
  const full = [settings.address, cityLine].filter((p) => p && p.length > 0).join(", ");
  return full.length > 0 ? full : null;
}

const viewStyles = stylex.create({
site0: { marginTop: 24, maxWidth: 460 },
site1: { marginTop: 0 },
site2: { marginTop: 24, maxWidth: 460 },
site3: { marginTop: 0 },
site4: { marginTop: 24, maxWidth: 460 },
site5: { marginTop: 0 }
});

definition.viewSpecificRefusals:
import { DineroImportPanel } from "../components/DineroImportPanel";
import { OpeningBalancePanel } from "../components/OpeningBalancePanel";
import { useOptionalAuth } from "../lib/auth-context";
import { useMutationOutcome } from "../lib/useMutationOutcome";
import { useUnsavedChanges } from "../lib/useUnsavedChanges";
import * as stylex from "@stylexjs/stylex";
import { ButtonLink, Button, Input, PageHeader, Select } from "../components/ui";
// Company management — rename the display name, sync CVR stamdata, and
// archive/restore.
//
// Strictly non-destructive: there is intentionally no delete of ledger data.
// Archiving only flips a manifest flag; the ledger stays on disk untouched.

import { useEffect, useState } from "react";
import { useNavigate, useParams } from "react-router-dom";
import { api, ApiError } from "../lib/api";
import { useAsync } from "../lib/useAsync";
import { formatDateDa } from "../lib/format";
import { Banner, ErrorState, Loading } from "../components/Feedback";
import { AccountantExportCard } from "../components/AccountantExportCard";
import { ConfirmDialog } from "../components/ConfirmDialog";
import type {
  CompanyEntry,
  CompanySettings,
  VatPeriodType,
} from "../lib/types";

// #UI-3 — the cockpit serves no /docs/* routes, so the old `/docs/cvr-opsaetning`
// link was a dead end. CVR-login setup is covered by the public installation
// guide; link there with an absolute URL, matching HelpView's DOCS_BASE pattern.
const CVR_SETUP_GUIDE_URL = "https://rentemester.dk/docs/installation";

/**
 * VAT-cadence options for the profile selector (#300). `"none"` is the
 * form-level sentinel for a NOT VAT-registered company; it is submitted to the
 * PATCH-profile endpoint as `null`, which deregisters the company. Without this
 * option an owner of a non-registered holding ApS could never keep — and would
 * silently re-register on — the not-registered state when saving the profile.
 */
const VAT_PERIOD_OPTIONS: Array<{ value: VatPeriodType | "none"; label: string }> = [
  { value: "month", label: "Måned (måneds-moms)" },
  { value: "quarter", label: "Kvartal (kvartals-moms)" },
  { value: "half-year", label: "Halvår (halvårs-moms)" },
  { value: "none", label: "Ikke momsregistreret" },
];

export function ManageCompanyView() {
  const { slug = "" } = useParams();
  const navigate = useNavigate();
  const state = useAsync(async (signal) => {
    const companies = await api.companies({ signal });
    const found = companies.find((c) => c.slug === slug);
    if (!found) throw new ApiError("not_found", "Virksomheden findes ikke.", 404);
    const settings = await api.companySettings(slug, { signal });
    return { found, settings };
  }, [slug]);

  if (state.loading && !state.data) return <Loading />;
  if (state.error && !state.data)
    return <ErrorState message={state.error} onRetry={state.reload} />;

  return (
    <ManageForm
      onRefresh={state.reload}
      company={state.data!.found}
      settings={state.data!.settings}
      onArchivedAway={() => navigate("/")}
    />
  );
}

function ManageForm({
  onRefresh,
  company,
  settings,
  onArchivedAway,
}: {
  onRefresh: () => void;
  company: CompanyEntry;
  settings: CompanySettings;
  onArchivedAway: () => void;
}) {
  const native = useOptionalAuth()?.backend === "rust";
  const [name, setName] = useState(company.name);
  // Local mirrors of the persisted state, so the form stays consistent after a
  // save without re-fetching (a re-fetch would unmount this form mid-notice).
  const [savedName, setSavedName] = useState(company.name);
  const [archived, setArchived] = useState(company.archived);
  // #UI-17 — archiving navigates the owner away from this view, so it must not
  // fire on a single stray click. Gate it behind a confirm dialog. (Restoring
  // is non-destructive and stays on the page, so it stays one-click.)
  const [confirmingArchive, setConfirmingArchive] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const renameDisabled =
    busy || name.trim().length === 0 || name.trim() === savedName;

  const outcome = useMutationOutcome(onRefresh);
  useUnsavedChanges(name.trim() !== savedName.trim());

  async function rename(e: React.FormEvent) {
    e.preventDefault();
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      const updated = await api.updateCompany(company.slug, {
        name: name.trim(),
      }).catch(outcome.reject);
      setSavedName(updated.name);
      setName(updated.name);
      setNotice("Visningsnavn opdateret.");
    } catch (err) {
      setError(err instanceof ApiError ? err.message : "Kunne ikke gemme navnet.");
    } finally {
      setBusy(false);
    }
  }

  // Restoring is non-destructive and keeps the owner on the page — one click.
  async function restoreCompany() {
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      await api.updateCompany(company.slug, { archived: false }).catch(outcome.reject);
      setArchived(false);
      setNotice("Virksomheden er gendannet.");
    } catch (err) {
      setError(
        err instanceof ApiError ? err.message : "Kunne ikke ændre arkivstatus.",
      );
    } finally {
      setBusy(false);
    }
  }

  // #UI-17 — archiving runs from the confirm dialog. It rejects on failure so
  // the dialog surfaces the error (and the backup-lock conflict) inline rather
  // than navigating away on a half-finished write.
  async function confirmArchive() {
    await api.updateCompany(company.slug, { archived: true }).catch(outcome.reject);
    onArchivedAway();
  }

  return (
    <section>
    {outcome.feedback}
      <PageHeader title="Virksomhedsoplysninger" actions={<><ButtonLink className="btn secondary" to={`/companies/${company.slug}`}>
          Tilbage til regnskab
        </ButtonLink></>}>
        <div>

          <p className="muted">
            Slug <code>{company.slug}</code> · oprettet{" "}
            {formatDateDa(company.createdAt.slice(0, 10))}
            {archived ? " · arkiveret" : ""}
          </p>
        </div>

      </PageHeader>

      {error && <Banner kind="error">{error}</Banner>}
      {notice && <Banner kind="success">{notice}</Banner>}

      <form className="form" onSubmit={rename} aria-label="Omdøb virksomhed">
        <label>
          Visningsnavn
          <Input disabled={outcome.blocked}
            name="name"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <span className="field-hint">
            Ændrer kun det viste navn — slug og regnskabsdata berøres ikke.
          </span>
        </label>
        <div className="row-actions">
          <Button requiredPermission="company.admin" className="btn" type="submit" disabled={outcome.blocked || (renameDisabled)}>
            Gem navn
          </Button>
        </div>
      </form>

      <DineroImportPanel slug={company.slug} />
      <ProfileCard slug={company.slug} initial={settings} />

      <CvrCard slug={company.slug} initial={settings} />

      {native && <OpeningBalancePanel slug={company.slug} />}

      <AccountantExportCard slug={company.slug} />

      <div className={["card", stylex.props(viewStyles.site0).className].filter(Boolean).join(" ")} >
        <h3 {...stylex.props(viewStyles.site1)}>
          {archived ? "Gendan virksomhed" : "Arkivér virksomhed"}
        </h3>
        <p className="muted">
          {archived
            ? "Virksomheden er arkiveret. Gendan den for at vise den i porteføljen igen."
            : "Arkivering skjuler virksomheden fra den aktive portefølje. Regnskabsdata slettes aldrig og kan gendannes."}
        </p>
        <Button requiredPermission="company.admin" variant="secondary"
          className="btn secondary"
          type="button"
          onClick={
            archived ? restoreCompany : () => setConfirmingArchive(true)
          }
          disabled={outcome.blocked || (busy)}
        >
          {archived ? "Gendan virksomhed" : "Arkivér virksomhed"}
        </Button>
      </div>

      {confirmingArchive && (
        <ConfirmDialog
          title="Arkivér virksomhed"
          body={
            <p>
              Arkivér <strong>{savedName}</strong>? Virksomheden skjules fra den
              aktive portefølje, og du sendes tilbage til oversigten.
              Regnskabsdata slettes aldrig og kan gendannes herfra igen.
            </p>
          }
          confirmLabel="Arkivér virksomhed"
          confirmKind="danger"
          onConfirm={confirmArchive}
          onClose={() => setConfirmingArchive(false)} onRefresh={onRefresh}
        />
      )}
    </section>
  );
}

/**
 * The editable company profile + bank-details card (#284).
 *
 * A Cockpit owner must be able to record the company's own postal address,
 * default payment terms and — critically — its bank account. Without a bank
 * account every issued invoice goes out with no payment instructions, so the
 * card warns prominently when none is configured. Saving calls the same
 * `setCompanyProfile` core function the CLI's `company profile` command uses.
 */
function ProfileCard({
  slug,
  initial,
}: {
  slug: string;
  initial: CompanySettings;
}) {
  const [settings, setSettings] = useState(initial);
  const [cvr, setCvr] = useState(initial.cvr ?? "");
  const [address, setAddress] = useState(initial.address ?? "");
  const [postalCode, setPostalCode] = useState(initial.postalCode ?? "");
  const [city, setCity] = useState(initial.city ?? "");
  // #300: the VAT settlement cadence is editable from the cockpit, including
  // turning registration OFF (`"none"` → submitted as `null`). Initialise the
  // form state from `initial.vatPeriodType` so a not-VAT-registered company
  // (null) shows "Ikke momsregistreret" selected — defaulting to `quarter`
  // here would silently re-register the company on the next profile save.
  const [vatPeriodType, setVatPeriodType] = useState<VatPeriodType | "none">(
    initial.vatPeriodType ?? "none",
  );
  const [bankName, setBankName] = useState(initial.payment?.bankName ?? "");
  const [registrationNo, setRegistrationNo] = useState(
    initial.payment?.registrationNo ?? "",
  );
  const [accountNo, setAccountNo] = useState(
    initial.payment?.accountNo ?? "",
  );
  const [iban, setIban] = useState(initial.payment?.iban ?? "");
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const hasPayment = Boolean(
    settings.payment &&
      (settings.payment.bankName ||
        settings.payment.registrationNo ||
        settings.payment.accountNo ||
        settings.payment.iban),
  );

  const outcome = useMutationOutcome(async () => { await api.companySettings(slug); setNotice("Gemte stamdata er hentet. Indtastningerne i formularen er bevaret."); });
  useUnsavedChanges(cvr.trim() !== (settings.cvr ?? "") || address.trim() !== (settings.address ?? "") || postalCode.trim() !== (settings.postalCode ?? "") || city.trim() !== (settings.city ?? "") || vatPeriodType !== (settings.vatPeriodType ?? "none") || bankName.trim() !== (settings.payment?.bankName ?? "") || registrationNo.trim() !== (settings.payment?.registrationNo ?? "") || accountNo.trim() !== (settings.payment?.accountNo ?? "") || iban.trim() !== (settings.payment?.iban ?? ""));

  async function save(e: React.FormEvent) {
    e.preventDefault();
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    try {
      const updated = await api.updateCompanyProfile(slug, {
        cvr: cvr.trim(),
        address: address.trim(),
        postalCode: postalCode.trim(),
        city: city.trim(),
        // `"none"` → null so the server deregisters the company; a real
        // cadence is sent verbatim.
        vatPeriodType: vatPeriodType === "none" ? null : vatPeriodType,
        payment: {
          bankName: bankName.trim(),
          registrationNo: registrationNo.trim(),
          accountNo: accountNo.trim(),
          iban: iban.trim(),
        },
      }).catch(outcome.reject);
      setSettings(updated);
      setCvr(updated.cvr ?? "");
      setVatPeriodType(updated.vatPeriodType ?? "none");
      setNotice("Stamdata opdateret.");
    } catch (err) {
      setError(
        err instanceof ApiError
          ? err.message
          : "Kunne ikke gemme stamdata.",
      );
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className={["card", stylex.props(viewStyles.site2).className].filter(Boolean).join(" ")} >
    {outcome.feedback}
      <h3 {...stylex.props(viewStyles.site3)}>Stamdata og bankoplysninger</h3>
      <p className="muted">
        Virksomhedens egen adresse og bankkonto. Bankkontoen vises som
        betalingsoplysninger på alle fakturaer du udsteder.
      </p>

      {error && <Banner kind="error">{error}</Banner>}
      {notice && <Banner kind="success">{notice}</Banner>}
      {!hasPayment && (
        <Banner kind="warning">
          Der er ingen bankkonto registreret. Fakturaer udstedes uden
          betalingsoplysninger, indtil du tilføjer en konto her.
        </Banner>
      )}

      <form className="form" onSubmit={save} aria-label="Rediger stamdata">
        <label>
          CVR-nummer
          <Input disabled={outcome.blocked}
            name="cvr"
            value={cvr}
            onChange={(e) => setCvr(e.target.value)}
            inputMode="numeric"
            placeholder="12345678"
          />
        </label>
        <label>
          Adresse
          <Input disabled={outcome.blocked}
            name="address"
            value={address}
            onChange={(e) => setAddress(e.target.value)}
            placeholder="Vej 1"
          />
        </label>
        <label>
          Postnummer
          <Input disabled={outcome.blocked}
            name="postalCode"
            value={postalCode}
            onChange={(e) => setPostalCode(e.target.value)}
            placeholder="1000"
          />
        </label>
        <label>
          By
          <Input disabled={outcome.blocked}
            name="city"
            value={city}
            onChange={(e) => setCity(e.target.value)}
            placeholder="København"
          />
        </label>
        <label>
          Momsperiode
          <Select disabled={outcome.blocked}
            name="vatPeriodType"
            value={vatPeriodType}
            onChange={(e) =>
              setVatPeriodType(e.target.value as VatPeriodType | "none")
            }
          >
            {VAT_PERIOD_OPTIONS.map((o) => (
              <option key={o.value} value={o.value}>
                {o.label}
              </option>
            ))}
          </Select>
          <span className="field-hint">
            Den momsperiode virksomheden er registreret for hos SKAT.
            Momsperioder og -frister følger dette valg. Vælg «Ikke
            momsregistreret» for en virksomhed uden momsregistrering (fx
            holdingselskab) — momsfrister og momsangivelse slås så fra.
          </span>
        </label>
        <label>
          Pengeinstitut
          <Input disabled={outcome.blocked}
            name="bankName"
            value={bankName}
            onChange={(e) => setBankName(e.target.value)}
            placeholder="Danske Bank"
          />
        </label>
        <label>
          Registreringsnummer
          <Input disabled={outcome.blocked}
            name="registrationNo"
            value={registrationNo}
            onChange={(e) => setRegistrationNo(e.target.value)}
            placeholder="1234"
          />
        </label>
        <label>
          Kontonummer
          <Input disabled={outcome.blocked}
            name="accountNo"
            value={accountNo}
            onChange={(e) => setAccountNo(e.target.value)}
            placeholder="0001234567"
          />
        </label>
        <label>
          IBAN (valgfrit)
          <Input disabled={outcome.blocked}
            name="iban"
            value={iban}
            onChange={(e) => setIban(e.target.value)}
            placeholder="DK0000000000000000"
          />
          <span className="field-hint">
            Bruges til betalinger fra udlandet.
          </span>
        </label>
        <div className="row-actions">
          <Button requiredPermission="company.admin" className="btn" type="submit" disabled={outcome.blocked || (busy)}>
            {busy ? "Gemmer…" : "Gem stamdata"}
          </Button>
        </div>
      </form>
    </div>
  );
}

/**
 * The CVR-stamdata card: shows the company's registered address / branche /
 * status and a "Hent fra CVR" button that refreshes it from the CVR register.
 * The lookup runs server-side, so the CVR credentials never reach the browser.
 */
function CvrCard({ slug, initial }: { slug: string; initial: CompanySettings }) {
  const [settings, setSettings] = useState(initial);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const [fiscalWarning, setFiscalWarning] = useState<string | null>(null);
  // #402 — `null` = "we haven't checked yet", so we don't flicker the
  // "CVR-login mangler"-banner during the initial fetch.
  const [cvrLoginConfigured, setCvrLoginConfigured] = useState<boolean | null>(
    null,
  );

  const hasCvr = Boolean(settings.cvr);
  const loginMissing = cvrLoginConfigured === false;

  // #402 — find out if the server has CVR_USERNAME / CVR_PASSWORD before the
  // owner clicks anything. An owner who lacks the login should *see* that fact
  // — and the path to fix it — instead of clicking a button that throws a raw
  // 401 their way and leaves them guessing.
  useEffect(() => {
    let cancelled = false;
    api
      .cvrStatus()
      .then((status) => {
        if (!cancelled) setCvrLoginConfigured(status.configured);
      })
      .catch(() => {
        // A failure to *check* status shouldn't block the owner from trying —
        // treat it as "unknown" and let the sync call surface any real issue.
        if (!cancelled) setCvrLoginConfigured(null);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const outcome = useMutationOutcome(async () => { await api.companySettings(slug); setNotice("Gemte CVR-oplysninger er hentet. Kontrollér oplysningerne ved næste åbning af formularen."); });
  async function sync() {
    if (outcome.isBlocked()) return;
    setBusy(true);
    setError(null);
    setNotice(null);
    setFiscalWarning(null);
    try {
      const result = await api.syncCvr(slug).catch(outcome.reject);
      if (!result.ok) {
        setError(translateCvrError(result.errors[0]));
        return;
      }
      const fresh = await api.companySettings(slug);
      setSettings(fresh);
      const changed = result.updatedFields ?? [];
      setNotice(
        changed.length > 0
          ? `Hentet fra CVR. Opdaterede felter: ${changed.join(", ")}.`
          : "Hentet fra CVR. Stamdata var allerede opdateret.",
      );
      const fy = result.fiscalYearStartMonth;
      if (fy && !fy.matches && fy.cvr !== null) {
        setFiscalWarning(
          `CVR har regnskabsår der starter i måned ${fy.cvr}, men virksomheden ` +
            `er sat op med måned ${fy.current}. Regnskabsåret ændres aldrig ` +
            `automatisk — ret det manuelt hvis det er forkert.`,
        );
      }
    } catch (err) {
      setError(
        err instanceof ApiError
          ? translateCvrError(err.message)
          : "Kunne ikke hente fra CVR.",
      );
    } finally {
      setBusy(false);
    }
  }

  const buttonDisabled = busy || !hasCvr || loginMissing;
  const buttonTitle = loginMissing
    ? "CVR-login mangler på serveren — se forklaringen ovenfor."
    : !hasCvr
      ? "Tilføj først et CVR-nummer på virksomheden."
      : undefined;

  return (
    <div className={["card", stylex.props(viewStyles.site4).className].filter(Boolean).join(" ")} >
    {outcome.feedback}
      <h3 {...stylex.props(viewStyles.site5)}>CVR-stamdata</h3>

      {error && <Banner kind="error">{error}</Banner>}
      {notice && <Banner kind="success">{notice}</Banner>}
      {fiscalWarning && <Banner kind="warning">{fiscalWarning}</Banner>}

      {/*
        #402 — Owner-facing explanation when the server has no virk.dk-login.
        We say *what* is missing and *how* to fix it, in plain Danish, without
        sending the owner to the terminal for an environment variable they
        won't recognise.
      */}
      {loginMissing && (
        <Banner kind="warning">
          Cockpittet mangler dit virk.dk-login. Indtil det er sat op, kan
          stamdata ikke hentes automatisk fra CVR. Se{" "}
          <a
            href={CVR_SETUP_GUIDE_URL}
            target="_blank"
            rel="noreferrer noopener"
          >
            installationsguiden
          </a>{" "}
          for hvordan du konfigurerer det.
        </Banner>
      )}

      {!hasCvr && (
        <p className="muted">
          Der er ikke registreret et CVR-nummer på virksomheden. Tilføj et
          CVR-nummer for at kunne hente stamdata fra CVR-registret.
        </p>
      )}

      {hasCvr && (
        <dl className="cvr-facts">
          <Fact label="CVR-nummer" value={settings.cvr} />
          <Fact label="Adresse" value={cvrAddressLine(settings)} />
          <Fact label="Virksomhedsform" value={settings.companyForm} />
          <Fact
            label="Branche"
            value={
              settings.industryText && settings.industryCode
                ? `${settings.industryCode} — ${settings.industryText}`
                : settings.industryText
            }
          />
          <Fact label="Status" value={settings.cvrStatus} />
          <Fact
            label="Revision fravalgt"
            value={
              settings.auditWaived === null
                ? null
                : settings.auditWaived
                  ? "Ja"
                  : "Nej"
            }
          />
          <Fact
            label="Sidst hentet"
            value={
              settings.cvrSyncedAt
                ? formatDateDa(settings.cvrSyncedAt.slice(0, 10))
                : "Aldrig"
            }
          />
        </dl>
      )}

      <Button requiredPermission="company.external-lookup" variant="secondary"
        className="btn secondary"
        type="button"
        onClick={sync}
        disabled={buttonDisabled}
        title={buttonTitle}
      >
        {busy ? "Henter…" : "Hent fra CVR"}
      </Button>
      <p className="field-hint">
        Kræver dit virk.dk-login. Konfigurér det én gang under CVR-login —{" "}
        regnskabsåret ændres aldrig automatisk.
      </p>
    </div>
  );
}

/**
 * #402 — Map raw CVR-register error messages to something an owner can act
 * on. The CVR core surfaces "kræver miljøvariablerne CVR_USERNAME og
 * CVR_PASSWORD" when credentials are missing; that's developer-speak, so we
 * translate it into a plain-Danish call to action. Everything else passes
 * through verbatim.
 */
function translateCvrError(raw: string | undefined): string {
  const fallback = "CVR-opslaget mislykkedes.";
  if (!raw) return fallback;
  const lower = raw.toLowerCase();
  if (
    lower.includes("cvr_username") ||
    lower.includes("cvr_password") ||
    lower.includes("http 401")
  ) {
    return (
      "Cockpittet mangler CVR-login. Konfigurér dit virk.dk-login (se " +
      "installationsguiden på rentemester.dk/docs/installation) og prøv igen."
    );
  }
  return raw;
}

function Fact({ label, value }: { label: string; value: string | null | undefined }) {
  return (
    <div className="cvr-fact">
      <dt className="muted">{label}</dt>
      <dd>{value && value.length > 0 ? value : "—"}</dd>
    </div>
  );
}

function cvrAddressLine(settings: CompanySettings): string | null {
  const cityLine = [settings.postalCode, settings.city].filter(Boolean).join(" ");
  const full = [settings.address, cityLine].filter((p) => p && p.length > 0).join(", ");
  return full.length > 0 ? full : null;
}

const viewStyles = stylex.create({
site0: { marginTop: 24, maxWidth: 460 },
site1: { marginTop: 0 },
site2: { marginTop: 24, maxWidth: 460 },
site3: { marginTop: 0 },
site4: { marginTop: 24, maxWidth: 460 },
site5: { marginTop: 0 }
});

definition.api:
import { ordinaryWorkspaceWriteAllowed } from "../workspace-write-mode";
// Shared primitives for the cockpit API client.
//
// `ApiError` is the canonical error class every per-domain module throws via
// `request<T>(...)`. Re-exported from `app/src/lib/api.ts` so external callers
// keep importing it from the barrel.

/** Optional cancellation belongs to one read request, never shared state. */
export type ReadRequestOptions = Pick<RequestInit, "signal">;

function isAborted(cause: unknown, signal: AbortSignal | null | undefined): boolean {
  return signal?.aborted === true || (cause instanceof Error && cause.name === "AbortError");
}

/** A failed API call — carries the backend error code for precise handling. */
export class ApiError extends Error {
  readonly code: string;
  readonly status: number;
  constructor(code: string, message: string, status: number) {
    super(message);
    this.name = "ApiError";
    this.code = code;
    this.status = status;
  }
}

/** Raised once for an expired hosted browser session.  The app shell listens
 * for this event so an old view is never left visible after a 401. */
function signalAuthExpired(): void {
  if (typeof window !== "undefined") {
    window.dispatchEvent(new Event("rentemester:auth-expired"));
  }
}

type ApiRequestOptions = RequestInit & { readOnly?: boolean };

function isWrite(init?: ApiRequestOptions): boolean {
  return !init?.readOnly && init?.method !== undefined && !["GET", "HEAD"].includes(init.method.toUpperCase());
}

async function fetchResponse(path: string, init?: ApiRequestOptions): Promise<Response> {
  if (!ordinaryWorkspaceWriteAllowed(path, init?.method ?? "GET", init?.readOnly)) throw new ApiError("workspace_not_active", "Workspace er skrivebeskyttet. Kontrollér flytningens aktuelle tilstand.", 423);
  const { readOnly, ...fetchOptions } = init ?? {};
  try {
    return await fetch(path, {
      ...fetchOptions,
      credentials: "same-origin",
      headers: { "content-type": "application/json", ...(init?.headers ?? {}) },
    });
  } catch (cause) {
    if (isAborted(cause, init?.signal)) throw cause;
    throw new ApiError(
      "network",
      isWrite(init) ? "Handlingen kan være gennemført, men serverens resultat kunne ikke bekræftes. Kontrollér status, før du starter en ny handling." : "Kunne ikke nå serveren. Kontrollér forbindelsen og prøv igen.",
      0,
    );
  }
}

/** Decode the same server envelope for JSON responses and binary failures. */
function responseError(res: Response, body: unknown, fallback: string): ApiError {
  const env = body && typeof body === "object" ? body as { errors?: unknown; code?: unknown } : undefined;
  const errors = Array.isArray(env?.errors) ? env.errors.map(String) : [];
  const code = res.status === 401 ? "unauthorized" : typeof env?.code === "string" ? env.code : "internal";
  if (code === "unauthorized") signalAuthExpired();
  const message = res.status === 403 && ["access_denied", "forbidden", "internal"].includes(code)
    ? "Du har ikke adgang til denne handling. Bed workspace-ejeren kontrollere dine rettigheder."
    : errors[0] ?? (res.status === 401 ? "Din session er udløbet. Log ind igen." : fallback);
  return new ApiError(code, message, res.status);
}

function bodyReadError(res: Response, cause: unknown, init?: ApiRequestOptions): unknown {
  if (isAborted(cause, init?.signal)) return cause;
  return responseError(res, undefined, isWrite(init)
    ? "Serverens svar på handlingen kunne ikke læses. Kontrollér status, før du starter en ny handling."
    : "Serveren gav et ugyldigt svar.");
}

export async function request<T>(path: string, init?: ApiRequestOptions): Promise<T> {
  const res = await fetchResponse(path, init);
  let body: unknown;
  try {
    body = await res.json();
  } catch (cause) {
    throw bodyReadError(res, cause, init);
  }
  // A superseded auth read must not expire the newer session via its old 401.
  init?.signal?.throwIfAborted();
  if (body && typeof body === "object" && (body as { ok?: unknown }).ok === false) throw responseError(res, body, "Ukendt serverfejl.");
  if (!res.ok) throw responseError(res, undefined, `HTTP ${res.status}`);
  return body as T;
}

/** Binary success keeps domain headers; transport failures use the canonical seam. */
export async function requestBlob(path: string, init?: ApiRequestOptions): Promise<{ blob: Blob; headers: Headers }> {
  const res = await fetchResponse(path, init);
  if (!res.ok) {
    let body: unknown;
    try { body = await res.json(); } catch (cause) {
      if (isAborted(cause, init?.signal)) throw cause;
    }
    throw responseError(res, body, `HTTP ${res.status}`);
  }
  try {
    return { blob: await res.blob(), headers: res.headers };
  } catch (cause) {
    throw bodyReadError(res, cause, init);
  }
}

/** Picks the filename from a `filename*=UTF-8''…` content-disposition header. */
export function parseFilenameFromContentDisposition(cd: string | null): string | null {
  if (!cd) return null;
  const m = cd.match(/filename\*=UTF-8''([^;]+)/i);
  if (!m || !m[1]) return null;
  try {
    return decodeURIComponent(m[1]);
  } catch {
    return null;
  }
