                  <td>{d.nonRelatedParty ? "Ja" : "Nej"}</td>
                  <td>{d.lastPlacementAt ?? "—"}</td>
                </tr>
              ))}
            </tbody>
          </table></div>
        )}
      </section>

      <section className="card">
        <h3>Lovgrundlag</h3>
        <p>
          {data.legalCitation.note}{" "}
          <Link to={`/lovgrundlag#${data.legalCitation.sourceId}`}>
            Se {data.legalCitation.sourceId} i Lovgrundlag-visningen
          </Link>
          .
        </p>
      </section>
    </section>
  );
}

