import { Button, Input, PageHeader } from "../components/ui";
import { FormEvent, useState } from "react";
import { useParams } from "react-router-dom";
import { api } from "../lib/api";
import { useMutationOutcome } from "../lib/useMutationOutcome";
import { useUnsavedChanges } from "../lib/useUnsavedChanges";
import { useAsync } from "../lib/useAsync";
import { ErrorState, Loading, Banner } from "../components/Feedback";
import { ConfirmDialog } from "../components/ConfirmDialog";

type Pending = { create?:"definition"|"member"; title:string; body:string; noteLabel?:string; noteInitialValue?:string; run:(note:string)=>Promise<unknown> };

/** Small review surface: all changes are append-only and are made through the
 * reviewed API flows; this screen intentionally makes history visible. */
export function DimensionsView(){
  const {slug=""}=useParams(); const definitions=useAsync((signal)=>api.dimensionDefinitions(slug, { signal }),[slug]); const members=useAsync((signal)=>api.dimensionMembers(slug, undefined, { signal }),[slug]);
  const [pending,setPending]=useState<Pending|null>(null); const [message,setMessage]=useState<string|null>(null);
  const [definition,setDefinition]=useState({dimensionId:"",kind:"",name:""}); const [member,setMember]=useState({dimensionId:"",memberId:"",name:""});
  const reload=()=>{definitions.reload();members.reload();};
  const outcome=useMutationOutcome(reload);
  const markDefinitionSaved=useUnsavedChanges(Boolean(definition.dimensionId||definition.kind||definition.name));
  const markMemberSaved=useUnsavedChanges(Boolean(member.dimensionId||member.memberId||member.name));
  const queue=(title:string,body:string,run:(note:string)=>Promise<unknown>,noteLabel?:string,noteInitialValue?:string,create?:Pending["create"])=>{if(!outcome.isBlocked())setPending({title,body,run,noteLabel,noteInitialValue,create});};
  const confirm=async(note:string)=>{if(!pending||outcome.isBlocked())return;await pending.run(note).catch(outcome.reject);if(pending.create==="definition"){setDefinition({dimensionId:"",kind:"",name:""});markDefinitionSaved();}if(pending.create==="member"){setMember({dimensionId:"",memberId:"",name:""});markMemberSaved();}setPending(null);setMessage("Ændringen er registreret i revisionssporet.");definitions.reload();members.reload();};
  const addDefinition=(event:FormEvent)=>{event.preventDefault();if(!definition.dimensionId||!definition.kind||!definition.name)return;queue("Opret dimension","Definitionen oprettes som en append-only hændelse. Eksisterende bogføring ændres ikke.",()=>api.createDimensionDefinition(slug,definition),undefined,undefined,"definition");};
  const addMember=(event:FormEvent)=>{event.preventDefault();if(!member.dimensionId||!member.memberId||!member.name)return;queue("Opret medlem","Medlemmet oprettes som en append-only hændelse. Det kan efterfølgende aktiveres, deaktiveres eller omdøbes med historik.",()=>api.createDimensionMember(slug,member),undefined,undefined,"member");};
  if((definitions.loading&&!definitions.data)||(members.loading&&!members.data))return <Loading/>; if((definitions.error&&!definitions.data)||(members.error&&!members.data))return <ErrorState message={definitions.error??members.error??"Kunne ikke hente dimensioner"} onRetry={() => { definitions.reload(); members.reload(); }}/>;
  return <section>{outcome.feedback}{(definitions.error||members.error)&&<Banner kind="warning">Status kunne ikke opdateres. Formularen er bevaret; de tidligere hentede dimensioner vises fortsat.</Banner>}<PageHeader title="Dimensioner"><div><p className="muted">Administrér og gennemgå append-only definitioner, medlemmer og deres historiske navne.</p></div></PageHeader>{message&&<Banner kind="success">{message}</Banner>}<div className="card"><h3>Opret dimension</h3><form className="row-actions" onSubmit={addDefinition}><Input disabled={outcome.blocked} aria-label="Dimensions-id" value={definition.dimensionId} onChange={e=>setDefinition({...definition,dimensionId:e.target.value})} placeholder="fx projekt" required/><Input disabled={outcome.blocked} aria-label="Dimensionstype" value={definition.kind} onChange={e=>setDefinition({...definition,kind:e.target.value})} placeholder="fx projekt" required/><Input disabled={outcome.blocked} aria-label="Dimensionsnavn" value={definition.name} onChange={e=>setDefinition({...definition,name:e.target.value})} placeholder="fx Projekter" required/><Button disabled={outcome.blocked} requiredPermission="company.master-data" className="btn" type="submit">Opret dimension</Button></form></div><h3>Definitioner</h3><div className="table-scroll"><table><thead><tr><th>Id</th><th>Navn</th><th>Status</th><th>Hændelse</th><th>Handling</th></tr></thead><tbody>{definitions.data!.length?definitions.data!.map(row=><tr key={row.id}><td>{row.dimension_id}</td><td>{row.name}</td><td>{row.status}</td><td>{row.event_type}</td><td className="row-actions"><Button disabled={outcome.blocked} requiredPermission="company.master-data" variant="secondary" type="button" className="btn secondary" onClick={()=>queue("Omdøb dimension",`Det nye navn bliver en append-only revision af ${row.dimension_id}.`,name=>api.changeDimensionDefinition(slug,{dimensionId:row.dimension_id,action:"rename",name}),"Nyt navn",row.name)}>Omdøb</Button><Button disabled={outcome.blocked} requiredPermission="company.master-data" variant="secondary" type="button" className="btn secondary" onClick={()=>queue(row.status==="active"?"Deaktiver dimension":"Aktivér dimension",`Statusændringen gemmes med historik for ${row.dimension_id}.`,()=>api.changeDimensionDefinition(slug,{dimensionId:row.dimension_id,action:row.status==="active"?"deactivate":"activate"}))}>{row.status==="active"?"Deaktiver":"Aktivér"}</Button></td></tr>):<tr><td colSpan={5} className="muted">Ingen definitioner endnu.</td></tr>}</tbody></table></div><div className="card"><h3>Opret medlem</h3><form className="row-actions" onSubmit={addMember}><Input disabled={outcome.blocked} aria-label="Medlemmets dimension" value={member.dimensionId} onChange={e=>setMember({...member,dimensionId:e.target.value})} placeholder="dimensions-id" required/><Input disabled={outcome.blocked} aria-label="Medlems-id" value={member.memberId} onChange={e=>setMember({...member,memberId:e.target.value})} placeholder="fx projekt-a" required/><Input disabled={outcome.blocked} aria-label="Medlemsnavn" value={member.name} onChange={e=>setMember({...member,name:e.target.value})} placeholder="fx Projekt A" required/><Button disabled={outcome.blocked} requiredPermission="company.master-data" className="btn" type="submit">Opret medlem</Button></form></div><h3>Medlemmer</h3><div className="table-scroll"><table><thead><tr><th>Dimension</th><th>Id</th><th>Navn</th><th>Status</th><th>Hændelse</th><th>Handling</th></tr></thead><tbody>{members.data!.length?members.data!.map(row=><tr key={row.id}><td>{row.dimension_id}</td><td>{row.member_id}</td><td>{row.name}</td><td>{row.status}</td><td>{row.event_type}</td><td className="row-actions"><Button disabled={outcome.blocked} requiredPermission="company.master-data" variant="secondary" type="button" className="btn secondary" onClick={()=>queue("Omdøb medlem",`Det nye navn bliver en append-only revision af ${row.member_id}.`,name=>api.changeDimensionMember(slug,{dimensionId:row.dimension_id,memberId:row.member_id!,action:"rename",name}),"Nyt navn",row.name)}>Omdøb</Button><Button disabled={outcome.blocked} requiredPermission="company.master-data" variant="secondary" type="button" className="btn secondary" onClick={()=>queue(row.status==="active"?"Deaktiver medlem":"Aktivér medlem",`Statusændringen gemmes med historik for ${row.member_id}.`,()=>api.changeDimensionMember(slug,{dimensionId:row.dimension_id,memberId:row.member_id!,action:row.status==="active"?"deactivate":"activate"}))}>{row.status==="active"?"Deaktiver":"Aktivér"}</Button></td></tr>):<tr><td colSpan={6} className="muted">Ingen medlemmer endnu.</td></tr>}</tbody></table></div>{pending&&<ConfirmDialog title={pending.title} body={<p>{pending.body}</p>} confirmLabel="Bekræft ændring" noteLabel={pending.noteLabel} noteInitialValue={pending.noteInitialValue} onConfirm={confirm} onRefresh={reload} onClose={()=>setPending(null)}/>}</section>;
}

