 * reviewed API flows; this screen intentionally makes history visible. */
export function DimensionsView(){
  const {slug=""}=useParams(); const definitions=useAsync((signal)=>api.dimensionDefinitions(slug, { signal }),[slug]); const members=useAsync((signal)=>api.dimensionMembers(slug, undefined, { signal }),[slug]);
  const [pending,setPending]=useState<Pending|null>(null); const [message,setMessage]=useState<string|null>(null);
