 requiredPermission="company.master-data" variant="secondary" type="button" className="btn secondary" onClick={()=>queue(row.status==="active"?"Deaktiver dimension":"Aktivér dimension",`Statusændringen gemmes med historik for ${row.dimension_id}.`,()=>api.changeDimensionDefinition(slug,{dimensionId:row.dimension_id,action:row.status==="active"?"deactivate":"activate"}))}>{row.status==="active"?"Deaktiver":"Aktivér"}</Button></td></tr>):<tr><td colSpan={5} className="muted">Ingen definitioner endnu.</td></tr>}</tbody></table></div><div className="card"><h3>Opret medlem</h3><form className="row-actions" onSubmit={addMember}><Input disabled={outcome.blocked} aria-label="Medlemmets dimension" value={member.dimensionId} onChange={e=>setMember({...member,dimensionId:e.target.value})} placeholder="dimensions-id" required/><Input disabled={outcome.blocked} aria-label="Medlems-id" value={member.memberId} onChange={e=>setMember({...member,memberId:e.target.value})} placeholder="fx projekt-a" required/><Input disabled={outcome.blocked} aria-label="Medlemsnavn" value={member.name} onChange={e=>setMember({...member,name:e.target.value})} placeholder="fx Projekt A" required/><Button disabled={outcome.blocked} requiredPermission="company.master-data" className="btn" type="submit">Opret medlem</Button></form></div><h3>Medlemmer</h3><div className="table-scroll"><table><thead><tr><th>Dimension</th><th>Id</th><th>Navn</th><th>Status</th><th>Hændelse</th><th>Handling</th></tr></thead><tbody>{members.data!.length?members.data!.map(row=><tr key={row.id}><td>{row.dimension_id}</td><td>{row.member_id}</td><td>{row.name}</td><td>{row.status}</td><td>{row.event_type}</td><td className="row-actions"><Button disabled={outcome.blocked} requiredPermission="company.master-data" variant="secondary" type="button" className="btn secondary" onClick={()=>queue("Omdøb medlem",`Det nye navn bliver en append-only revision af ${row.member_id}.`,name=>api.changeDimensionMember(slug,{dimensionId:row.dimension_id,memberId:row.member_id!,action:"rename",name}),"Nyt navn",row.name)}>Omdøb</Button><Button disabled={outcome.blocked} requiredPermission="company.master-data" variant="secondary" type="button" className="btn secondary" onClick={()=>queue(row.status==="active"?"Deaktiver medlem":"Aktivér medlem",`Statusændringen gemmes med historik for ${row.member_id}.`,()=>api.changeDimensionMember(slug,{dimensionId:row.dimension_id,memberId:row.member_id!,action:row.status==="active"?"deactivate":"activate"}))}>{row.status==="active"?"Deaktiver":"Aktivér"}</Button></td></tr>):<tr><td colSpan={6} className="muted">Ingen medlemmer endnu.</td></tr>}</tbody></table></div>{pending&&<ConfirmDialog title={pending.title} body={<p>{pending.body}</p>} confirmLabel="Bekræft ændring" noteLabel={pending.noteLabel} noteInitialValue={pending.noteInitialValue} onConfirm={confirm} onRefresh={reload} onClose={()=>setPending(null)}/>}</section>;
