              </p>
            </div>
          }
          confirmLabel="Send faktura"
          confirmKind="danger"
          noteLabel="Modtager"
          notePlaceholder="kunde@eksempel.dk"
          noteInitialValue={sendingEmail.customerEmail ?? ""}
          noteInputType="email"
