  return <section className="table-wrap" aria-label="Kildeposter"><div className="table-scroll"><table><thead><tr><th>Dato</th><th>Virksomhed</th><th>Postering</th><th>Modpart</th><th>Beløb</th><th>Kilde</th><th>Kildedetaljer</th></tr></thead><tbody>{rows.map((row) => <tr key={`${row.companySlug}:${row.sourceType}:${row.sourceId}`}><td>{row.transactionDate}</td><td><Link to={`/companies/${row.companySlug}`}>{row.companySlug}</Link></td><td><Link aria-label={`Postering ${row.journalEntryNo ?? row.sourceId}`} to={`/companies/${row.companySlug}/posteringer?account=${encodeURIComponent(row.accountNo)}`}>{row.journalEntryNo ?? row.accountNo}</Link></td><td>{row.partyName ?? "—"}</td><td className="num">{amountText(row.amount, row.currency)}</td><td><code title={row.sourceHash}>{row.sourceType}</code></td><td><details><summary>Kildedetaljer {row.sourceId}</summary><p>Konto: {row.accountNo} · {row.accountName ?? "Navn ikke tilgængeligt"}</p><p>{row.text ?? "Ingen posteringstekst"}</p><p>Kilde-ID: {row.sourceId} · hash: <code>{row.sourceHash}</code></p>{row.documentId !== null && <p><a href={`/api/companies/${encodeURIComponent(row.companySlug)}/documents/${row.documentId}/file`} target="_blank" rel="noopener noreferrer">Åbn originalbilag</a> · bilagshash: <code>{row.documentHash ?? "Ikke tilgængelig"}</code></p>}{row.documentPartyName && <p>Udtrukket bilagsnavn (ikke en partstilknytning): {row.documentPartyName}</p>}{row.partyLinkProvenance && <p>Partstilknytning {row.partyLinkProvenance.linkId} · {row.partyLinkProvenance.role} · {row.partyLinkProvenance.evidenceKind} · {row.partyLinkProvenance.linkedAt} · plan-hash <code>{row.partyLinkProvenance.planHash}</code></p>}{row.dimensions?.map((d,index)=><p key={index}>Dimension {d.dimensionId}: {d.memberId} · {d.amountMinor} mindsteenheder {d.currency}</p>)}</details></td></tr>)}</tbody></table></div></section>;
}

function GroupResult({ result }: { result: Extract<CfoAnalyticsResponse, { scope: "group" }> }) {
  const group = result.group;
  if (result.status !== "ready" || group.status !== "ready" || !group.consolidatedFigures || !group.currency) return <section className="banner warning" role="status"><strong>Koncernrapporten understøttes ikke for dette udsnit.</strong><ul>{[...(result.limitations ?? []), ...(group.blockers ?? [])].map((blocker) => <li key={blocker}>{blocker}</li>)}</ul></section>;
  return <section className="card" aria-label="Koncernrapport"><h3>Koncernrapport — kontrolleret profil</h3><p className="muted">Pr. {result.asOf} · rå summer, elimineringer og konsolideret beløb vises hver for sig.</p><div className="table-scroll"><table><thead><tr><th>Linje</th><th>Rå sum</th><th>Eliminering</th><th>Konsolideret</th></tr></thead><tbody>{group.consolidatedFigures.map((line) => <tr key={line.lineId}><td>{line.label}</td><td className="num">{amountText(line.rawCompanySum, group.currency)}</td><td className="num">{amountText(line.eliminationAdjustment, group.currency)}</td><td className="num">{amountText(line.consolidatedAmount, group.currency)}</td></tr>)}</tbody></table></div><ButtonLink className="btn secondary" to="/koncernstruktur">Se struktur, afstemning og kilde-evidens</ButtonLink></section>;
}

