import { Input, PageHeader, Select } from "../components/ui";
// Lovgrundlag-viewer (#347) — workspace-level read-only side der viser de
// danske regler Rentemester anvender, med klikbar SHA-256-citation pr.
// provision og deep-links til retsinformation.dk.
//
// Acceptkriterium fra #347: read-only (regler kan kun ændres via PR i
// `rules/dk/`), bruger `parseRuleBundle` + `readLegalSourceIds` via det nye
// `/api/rules`-endpoint, og citationerne er SHA-256-fingeraftryk pr. paragraf.

import { useMemo, useState } from "react";
import { api } from "../lib/api";
import { useAsync } from "../lib/useAsync";
import type {
  LegalSource,
  RuleSummary,
  RulesResponse,
} from "../lib/types";
import { ErrorState, Loading } from "../components/Feedback";

export function RulesView() {
  const state = useAsync<RulesResponse>((signal) => api.rules({ signal }), []);
  const [bundleFilter, setBundleFilter] = useState<string>("");
  const [search, setSearch] = useState("");

  const sources = useMemo(() => {
    const map = new Map<string, LegalSource>();
    for (const s of state.data?.legalSources ?? []) map.set(s.id, s);
    return map;
  }, [state.data]);

  const bundles = state.data?.ruleBundles ?? [];
  const allRules = state.data?.rules ?? [];

  const filteredRules = useMemo(() => {
    const needle = search.trim().toLowerCase();
    return allRules.filter((r) => {
      if (bundleFilter !== "" && r.bundle !== bundleFilter) return false;
      if (needle === "") return true;
      return (
        r.ruleId.toLowerCase().includes(needle) ||
        r.name.toLowerCase().includes(needle) ||
        r.explanation.toLowerCase().includes(needle) ||
        r.provisions.some((p) => p.ref.toLowerCase().includes(needle))
      );
    });
  }, [allRules, bundleFilter, search]);

  if (state.loading) return <Loading />;
  if (state.error) return <ErrorState message={state.error} />;

  return (
    <section className="rules-view">
      <PageHeader title="Lovgrundlag">
        <div>

          <p className="muted">
            Rentemester citerer linje for linje fra retsinformation.dk via
            SHA-256-fingeraftryk. Siden viser hvilke regler der p.t. styrer
            bogføringen — og hvilken paragraf hver regel hænger på. Read-only:
            regler kan kun ændres ved en PR i <code>rules/dk/</code>.
          </p>
        </div>
      </PageHeader>

      <section className="card">
        <h3>Aktive regelbundler</h3>
        <div className="table-scroll"><table className="table">
          <thead>
            <tr>
              <th>Bundle</th>
              <th>Version</th>
              <th>Antal regler</th>
              <th>Kilder</th>
              <th>VAT-koder</th>
            </tr>
          </thead>
          <tbody>
            {bundles.map((b) => (
              <tr key={b.name}>
                <td>{b.name}</td>
                <td>
                  <code>{b.version}</code>
                </td>
                <td>{b.ruleCount}</td>
                <td>{b.sources.join(", ")}</td>
                <td>{b.vatCodes.join(", ") || "—"}</td>
              </tr>
            ))}
          </tbody>
        </table></div>
      </section>

      <section className="card">
        <h3>Regler ({filteredRules.length} af {allRules.length})</h3>
        <div className="filter-bar">
          <label>
            Bundle{" "}
            <Select
              value={bundleFilter}
              onChange={(e) => setBundleFilter(e.target.value)}
            >
              <option value="">Alle</option>
              {bundles.map((b) => (
                <option key={b.name} value={b.name}>
                  {b.name}
                </option>
              ))}
            </Select>
          </label>
          <label>
            Søg{" "}
            <Input
              type="search"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="regel-id, paragraf, ord …"
            />
          </label>
        </div>

        <ul className="rule-list">
          {filteredRules.map((r) => (
            <RuleEntry
              key={r.ruleId}
              rule={r}
              source={sources.get(r.sourceId) ?? null}
            />
          ))}
          {filteredRules.length === 0 && (
            <li className="muted">Ingen regler matcher filtret.</li>
          )}
        </ul>
      </section>
    </section>
  );
}

function RuleEntry({
  rule,
  source,
}: {
  rule: RuleSummary;
  source: LegalSource | null;
}) {
  return (
    <li className="rule-entry">
      <div className="rule-head">
        <span className="rule-id">
          <code>{rule.ruleId}</code>
        </span>
        <span className="rule-name">{rule.name}</span>
        <span className={`pill severity-${rule.severity || "info"}`}>
          {rule.severity || "info"}
        </span>
        <span className="pill">{rule.category || "—"}</span>
        <span className="pill">{rule.bundle}</span>
      </div>
      {rule.explanation && <p className="rule-explanation">{rule.explanation}</p>}
      <details>
        <summary>Citationer ({rule.provisions.length})</summary>
        {source && (
          <p className="muted">
            Kilde:{" "}
            <a href={source.url} target="_blank" rel="noopener noreferrer">
              {source.title}
            </a>{" "}
            ({source.authority})
          </p>
        )}
        <div className="table-scroll"><table className="table provisions">
          <thead>
            <tr>
              <th>Paragraf</th>
              <th>SHA-256-fingeraftryk</th>
            </tr>
          </thead>
          <tbody>
            {rule.provisions.map((p, i) => (
              <tr key={`${rule.ruleId}-${i}`}>
                <td>{p.ref}</td>
                <td>
                  <code>{p.textHash}</code>
                </td>
              </tr>
            ))}
          </tbody>
        </table></div>
      </details>
    </li>
  );
}

definition.api:
import { ordinaryWorkspaceWriteAllowed } from "../workspace-write-mode";
// Shared primitives for the cockpit API client.
//
// `ApiError` is the canonical error class every per-domain module throws via
// `request<T>(...)`. Re-exported from `app/src/lib/api.ts` so external callers
// keep importing it from the barrel.

/** Optional cancellation belongs to one read request, never shared state. */
export type ReadRequestOptions = Pick<RequestInit, "signal">;

function isAborted(cause: unknown, signal: AbortSignal | null | undefined): boolean {
  return signal?.aborted === true || (cause instanceof Error && cause.name === "AbortError");
}

/** A failed API call — carries the backend error code for precise handling. */
export class ApiError extends Error {
  readonly code: string;
  readonly status: number;
  constructor(code: string, message: string, status: number) {
    super(message);
    this.name = "ApiError";
    this.code = code;
    this.status = status;
  }
}

/** Raised once for an expired hosted browser session.  The app shell listens
 * for this event so an old view is never left visible after a 401. */
function signalAuthExpired(): void {
  if (typeof window !== "undefined") {
    window.dispatchEvent(new Event("rentemester:auth-expired"));
  }
}

type ApiRequestOptions = RequestInit & { readOnly?: boolean };

function isWrite(init?: ApiRequestOptions): boolean {
  return !init?.readOnly && init?.method !== undefined && !["GET", "HEAD"].includes(init.method.toUpperCase());
}

async function fetchResponse(path: string, init?: ApiRequestOptions): Promise<Response> {
  if (!ordinaryWorkspaceWriteAllowed(path, init?.method ?? "GET", init?.readOnly)) throw new ApiError("workspace_not_active", "Workspace er skrivebeskyttet. Kontrollér flytningens aktuelle tilstand.", 423);
  const { readOnly, ...fetchOptions } = init ?? {};
  try {
    return await fetch(path, {
      ...fetchOptions,
      credentials: "same-origin",
      headers: { "content-type": "application/json", ...(init?.headers ?? {}) },
    });
  } catch (cause) {
    if (isAborted(cause, init?.signal)) throw cause;
    throw new ApiError(
      "network",
      isWrite(init) ? "Handlingen kan være gennemført, men serverens resultat kunne ikke bekræftes. Kontrollér status, før du starter en ny handling." : "Kunne ikke nå serveren. Kontrollér forbindelsen og prøv igen.",
      0,
    );
  }
}

/** Decode the same server envelope for JSON responses and binary failures. */
function responseError(res: Response, body: unknown, fallback: string): ApiError {
  const env = body && typeof body === "object" ? body as { errors?: unknown; code?: unknown } : undefined;
  const errors = Array.isArray(env?.errors) ? env.errors.map(String) : [];
  const code = res.status === 401 ? "unauthorized" : typeof env?.code === "string" ? env.code : "internal";
  if (code === "unauthorized") signalAuthExpired();
  const message = res.status === 403 && ["access_denied", "forbidden", "internal"].includes(code)
    ? "Du har ikke adgang til denne handling. Bed workspace-ejeren kontrollere dine rettigheder."
    : errors[0] ?? (res.status === 401 ? "Din session er udløbet. Log ind igen." : fallback);
  return new ApiError(code, message, res.status);
}

function bodyReadError(res: Response, cause: unknown, init?: ApiRequestOptions): unknown {
  if (isAborted(cause, init?.signal)) return cause;
  return responseError(res, undefined, isWrite(init)
    ? "Serverens svar på handlingen kunne ikke læses. Kontrollér status, før du starter en ny handling."
    : "Serveren gav et ugyldigt svar.");
}

export async function request<T>(path: string, init?: ApiRequestOptions): Promise<T> {
  const res = await fetchResponse(path, init);
  let body: unknown;
  try {
    body = await res.json();
  } catch (cause) {
    throw bodyReadError(res, cause, init);
  }
  // A superseded auth read must not expire the newer session via its old 401.
  init?.signal?.throwIfAborted();
  if (body && typeof body === "object" && (body as { ok?: unknown }).ok === false) throw responseError(res, body, "Ukendt serverfejl.");
  if (!res.ok) throw responseError(res, undefined, `HTTP ${res.status}`);
  return body as T;
}

/** Binary success keeps domain headers; transport failures use the canonical seam. */
export async function requestBlob(path: string, init?: ApiRequestOptions): Promise<{ blob: Blob; headers: Headers }> {
  const res = await fetchResponse(path, init);
  if (!res.ok) {
    let body: unknown;
    try { body = await res.json(); } catch (cause) {
      if (isAborted(cause, init?.signal)) throw cause;
    }
    throw responseError(res, body, `HTTP ${res.status}`);
  }
  try {
    return { blob: await res.blob(), headers: res.headers };
  } catch (cause) {
    throw bodyReadError(res, cause, init);
  }
}

/** Picks the filename from a `filename*=UTF-8''…` content-disposition header. */
export function parseFilenameFromContentDisposition(cd: string | null): string | null {
  if (!cd) return null;
  const m = cd.match(/filename\*=UTF-8''([^;]+)/i);
  if (!m || !m[1]) return null;
  try {
    return decodeURIComponent(m[1]);
  } catch {
    return null;
  }
}
